        ["| filename  = Ambassador_-_Come_Then,_Shed_Your_Mortal_Form_And_Rejoice.ogg"] = "| nombre de archivo = Embajador_-_Come_Then,_Shed_Your_Mortal_Form_And_Rejoice.ogg",
        ["| desc      = Castil kreath fia Roake Kal. Skek Lac Ortius!"] = "| desc = Castil kreath fia Roake Kal. ¡Skek Lac Ortius!",
        ["| filename  = Ambassador_-_Castil_Kreath_Fia_Roake_Kal_Skek_Lac_Ortius!.ogg"] = "| nombre de archivo = Ambassador_-_Castil_Kreath_Fia_Roake_Kal_Skek_Lac_Ortius!.ogg",
        ["| title     = Spoken during The Ambassador encounter, Upon summoning Sinister Fragments."] = "| title = Hablado durante el encuentro con The Ambassador, al invocar Fragmentos Siniestros.",
        ["| desc      = Your soul is but a candle in the darkness, I shall snuff it out!"] = "| desc = Tu alma no es más que una vela en la oscuridad, ¡la apagaré!",
        ["| filename  = Ambassador_-_Your_Soul_Is_But_a_Candle_In_The_Darkness,_I_Shall_Snuff_It_Out!.ogg"] = "| nombre de archivo = Embajador_-_Tu_alma_es_pero_una_vela_en_la_oscuridad,_¡lo_apagaré_!.ogg",
        ["| desc      = BURN! Like the ants you are!"] = "| desc = ¡QUEMAR! ¡Como las hormigas que eres!",
        ["| filename  = Ambassador_-_BURN_Like_The_Ants_You_Are!.ogg"] = "| nombre de archivo = Embajador_-_BURN_Like_The_Ants_You_Are!.ogg",
        ["| desc      = Have a taste... of his power!"] = "| desc = ¡Prueba... su poder!",
        ["| filename  = Ambassador_-_Have_A_Taste_of_His_Power!.ogg"] = "| nombre de archivo = Embajador_-_¡Tenga_Un_Sabor_de_Su_Poder!.ogg",
        ["| desc      = BEHOLD HIS GLORY!"] = "| desc = ¡HE AQUÍ SU GLORIA!",
        ["| filename  = Ambassador_-_Behold_His_Glory!.ogg"] = "| nombre de archivo = Embajador_-_Behold_His_Glory!.ogg",
        ["| title     = Spoken during The Ambassador encounter, As Seiryu Arrives."] = "| title = Hablado durante el encuentro con The Ambassador, cuando llega Seiryu.",
        ["| desc      = You! Pathetic worm."] = "| desc = ¡Tú! Gusano patético.",
        ["| filename  = Ambassador_-_You_Pathetic_Worm.ogg"] = "| nombre de archivo = Ambassador_-_You_Pathetic_Worm.ogg",
        ["| desc      = You could have been magnificent."] = "| desc = Podrías haber sido magnífico.",
        ["| filename  = Ambassador_-_You_Could_Have_Been_Magnificent.ogg"] = "| nombre de archivo = Ambassador_-_You_Could_Have_Been_Magnificent.ogg",
        ["| desc      = Must you fight so hard to reduce all the world to mediocrity?"] = "| desc = ¿Debes luchar tan duro para reducir a todo el mundo a la mediocridad?",
        ["| filename  = Ambassador_-_Must_You_Fight_So_Hard_To_Reduce_All_The_World_To_Mediocrity.ogg"] = "| nombre de archivo = Ambassador_-_Must_You_Fight_So_Hard_To_Reduce_All_The_World_To_Mediocrity.ogg",
        ["| desc      = Are you that pinioned by your weakness?"] = "| desc = ¿Estás tan afligido por tu debilidad?",
        ["| filename  = Ambassador_-_Are_You_That_Pinioned_By_Your_Weakness.ogg"] = "| nombre de archivo = Ambassador_-_Are_You_That_Pinioned_By_Your_Weakness.ogg",
        ["| desc      = So be it."] = "| desc = Que así sea.",
        ["| filename  = Ambassador_-_So_Be_It.ogg"] = "| nombre de archivo = Ambassador_-_So_Be_It.ogg",
        ["| desc      = If you will not rise, Then you shall FALL!"] = "| desc = ¡Si no te levantas, entonces CAERÁS!",
        ["| filename  = Ambassador_-_If_You_Will_Not_Rise,_Then_You_Shall_Fall!.ogg"] = "| nombre de archivo = Embajador_-_Si_no_te_levantarás,_entonces_te_caerás!.ogg",
        ["| title     = Spoken upon the Ambassador's Defeat."] = "| title = Hablado sobre la derrota de the Ambassador.",
        ["| desc      = *Cough* You think this is a victory? *Cough*"] = "| desc = *Cough* ¿Crees que esto es una victoria? *Cough*",
        ["| filename  = Ambassador_-_Cough!_You_Think_This_Is_A_Victory_Cough!.ogg"] = "| nombre de archivo = Embajador_-_¡Tos!_¡Tú_piensas_Esto_es_una_tos_victoria!.ogg",
        ["| desc      = All you have done is bought yourself.. A few moments of respite."] = "| desc = Lo único que has hecho es comprarte a ti mismo. Unos momentos de respiro.",
        ["| filename  = Ambassador_-_All_You_Have_Done_Is_Bought_Yourself_A_Few_Moments_of_Respite.ogg"] = "| nombre de archivo = Ambassador_-_All_You_Have_Done_Is_Bought_Yourself_A_Few_Moments_of_Respite.ogg",
        ["| desc      = You live only.. Because he has not noticed you.."] = "| desc = Vives sólo.. Porque él no se ha fijado en ti..",
        ["| filename  = Ambassador_-_You_Live_Only_Because_He_Has_Not_Noticed_You.ogg"] = "| nombre de archivo = Ambassador_-_You_Live_Only_Because_He_Has_Not_Noticed_You.ogg",
        ["| desc      = But soon.. His gaze will fall upon this world.."] = "| desc = Pero pronto... Su mirada caerá sobre este mundo...",
        ["| filename  = Ambassador_-_But_Soon_His_Gaze_Will_Fall_Upon_This_World.ogg"] = "| nombre de archivo = Ambassador_-_But_Soon_His_Gaze_Will_Fall_Upon_This_World.ogg",
        ["| desc      = His.. Arrival is Inevitable.."] = "| desc = Su... La llegada es inevitable...",
        ["| filename  = Ambassador_-_His_Arrival_Is_Inevitable.ogg"] = "| nombre de archivo = Ambassador_-_His_Arrival_Is_Inevitable.ogg",
        ["| desc      = And you will not be able to save them..."] = "| desc=Y no podrás guardarlos...",
        ["| filename  = Ambassador_-_And_You_Will_Not_Be_Able_To_Save_Them.ogg"] = "| nombre de archivo = Ambassador_-_And_You_Will_Not_Be_Able_To_Save_Them.ogg",
    },
    ["The Architect"] = {
        ["Hello. Can I assist you?"] = "Hola. ¿Puedo ayudarte?",
        ["How are things?"] = "¿Cómo van las cosas?",
        ["*After Meet the Architect:*"] = "*Después de conocer a the Architect:*",
        ["These lands are filled with many examples of fine architecture. Hopefully I can glean some insights here."] = "Estas tierras están llenas de muchos ejemplos de excelente arquitectura. Espero poder obtener algunas ideas aquí.",
        ["*After Research Continues:*"] = "*Después de que la investigación continúa:*",
        ["I am here to see if there has been any news from my town. So far, my studies have brought no new information to light."] = "Estoy aquí para ver si ha habido alguna noticia de mi pueblo. Hasta ahora, mis estudios no han sacado a la luz ninguna información nueva.",
        ["*After Promising Sample:*"] = "*Después de una muestra prometedora:*",
        ["Varrock Museum contains information which I have been investigating. I have returned here to collect any messages from my town."] = "El Museo Varrock contiene información que he estado investigando. He vuelto aquí para recoger cualquier mensaje de mi pueblo.",
        ["*After Miracle Material:*"] = "*Después del material milagroso:*",
        ["Time is running out for my town. We do not have long."] = "El tiempo se acaba para mi ciudad. No nos queda mucho tiempo.",
        ["*After Strange Properties:*"] = "*Después de Propiedades extrañas:*",
        ["This new mineral has bought us a chance. Let us hope that it has come to us in time to save my town."] = "Este nuevo mineral nos ha dado una oportunidad. Esperemos que nos haya llegado a tiempo para salvar mi pueblo.",
        ["*After Foundations:*"] = "*Después de las bases:*",
        ["I have come seeking further aid and information. Mining has not been going as smoothly as we hoped."] = "He venido buscando más ayuda e información. Mining no ha ido tan bien como esperábamos.",
        ["*After Reinforcement*"] = "*Después del refuerzo*",
        ["Thank you for arranging help for me with the creatures. With the aid of the team, I was able to acquire more of the mineral."] = "Gracias por conseguir ayuda para mí con las criaturas. Con la ayuda del equipo, pude adquirir más mineral.",
        ["*After Once More into the Breach*"] = "*Después de una vez más en la brecha*",
        ["There is something more to these creatures. It is a shame we have discovered them under these circumstances."] = "Hay algo más en estas criaturas. Es una pena que los hayamos descubierto en estas circunstancias.",
        ["*Recipe Number 132: Fresh Idea*"] = "*Receta número 132: idea fresca*",
        ["I still cannot believe that we managed to make a deal with the creatures. However, it has allowed them and my town to survive."] = "Todavía no puedo creer que hayamos logrado hacer un trato con las criaturas. Sin embargo, les ha permitido a ellos y a mi pueblo sobrevivir.",
        ["I wonder if you could help me?"] = "Me pregunto si podrías ayudarme.",
        ["If you ever need help, do not hesitate to ask."] = "Si alguna vez necesitas ayuda, no dudes en preguntar.",
        ["*Voyage screen opens*"] = "*Se abre la pantalla de viaje*",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["*With the Missionary not unlocked:*"] = "*Con the Missionary no desbloqueado:*",
        ["I prefer to work with people who can talk about things other than what they found in their boots in the morning, or other such nonsense."] = "Prefiero trabajar con personas que pueden hablar de otras cosas además de lo que encontraron en sus botas por la mañana u otras tonterías por el estilo.",
        ["Unlock the Missionary (90 Prayer required) to unlock additional joint voyages."] = "Desbloquea the Missionary (se requieren 90 Prayer) para desbloquear viajes conjuntos adicionales.",
        ["*With the Missionary unlocked and not present:*"] = "*Con the Missionary desbloqueado y no presente:*",
        ["I would love to have a conversation about something other than killing things or boats."] = "Me encantaría tener una conversación sobre algo más que matar cosas o barcos.",
        ["If both the Missionary and Architect are in port at the same time, additional joint voyages will be made available."] = "Si tanto the Missionary como Architect están en el puerto al mismo tiempo, estarán disponibles viajes conjuntos adicionales.",
        ["*With the Missionary unlocked and present:*"] = "*Con the Missionary desbloqueado y presente:*",
        ["How's the life of an architect?"] = "¿Cómo es la vida de un arquitecto?",
        ["An architect has to consider both function and aesthetics: we have to balance strength with beauty; form with function. Each building is a new puzzle."] = "Un arquitecto debe considerar tanto la función como la estética: tenemos que equilibrar la fuerza con la belleza; forma con función. Cada edificio es un nuevo rompecabezas.",
        ["[View previous cutscenes]"] = "[Ver escenas anteriores]",
        ["Meet the Architect"] = "Conoce a the Architect",
        ["Research Continues"] = "La investigación continúa",
        ["Promising Sample"] = "Muestra prometedora",
        ["Miracle Material"] = "Material milagroso",
        ["More"] = "Más",
        ["Strange Properties"] = "Propiedades extrañas",
        ["Foundations"] = "Cimentaciones",
        ["Reinforcement"] = "Refuerzo",
        ["One More into the Breach"] = "Uno más en la brecha",
        ["Recipe Number 132: Fresh Idea"] = "Receta número 132: nueva idea",
        ["Leave me be. You have nothing of interest to me."] = "Déjame en paz. No tienes nada de interés para mí.",
        ["Drink clouds the mind, barmaid. I am not interested."] = "La bebida nubla la mente, camarera. No estoy interesado.",
        ["Apologies, visitor from the west, but I'm a little busy. Please, enjoy your stay on Waiko, and don't mind the earthquakes."] = "Disculpas, visitante del oeste, pero estoy un poco ocupada. Por favor, disfrute su estadía en Waiko y no se preocupe por los terremotos.",
        ["Earthquakes?"] = "¿Terremotos?",
        ["We've been lucky of late, but they can be quite frequent. Nothing to worry about, though, don't let it ruin your holiday."] = "Últimamente hemos tenido suerte, pero pueden ser bastante frecuentes. No hay de qué preocuparse, no dejes que eso arruine tus vacaciones.",
        ["Hello, Lidylla!"] = "¡Hola, Lidylla!",
        ["Oh, you gave me a start! I had my nose in my work."] = "¡Oh, me diste un sobresalto! Tenía mis narices en mi trabajo.",
        ["Hello, Portmaster. You are here visiting Waiko. Why are you here visiting Waiko? It's odd seeing you outside of your port."] = "Hola, Capitán de Puerto. Estás aquí visitando Waiko. ¿Por qué estás aquí visitando Waiko? Es extraño verte fuera de tu puerto.",
        ["How are the quakes here these days?"] = "¿Cómo son los terremotos aquí estos días?",
        ["Still frequent and, despite my best efforts, still damaging."] = "Sigue siendo frecuente y, a pesar de mis mejores esfuerzos, sigue siendo perjudicial.",
        ["Can I help at all?"] = "¿Puedo ayudar en algo?",
        ["Perhaps you could, just not yet. I'm working on a plan as we speak, but it's not quite ready yet. Once it is, I think you would be a capable pair of hands to see it put into action!"] = "Quizás puedas, pero todavía no. Estoy trabajando en un plan mientras hablamos, pero aún no está listo. Una vez que lo esté, ¡creo que serían un par de manos capaces para verlo puesto en acción!",
    },
    ["The Archivist"] = {
        ["Urm... hello?"] = "Urm... ¿hola?",
        ["Greetings automaton. I appear to be in a state of disrepair."] = "Saludos autómata. Parezco estar en mal estado.",
        ["WARNING: Core memories missing!"] = "ADVERTENCIA: ¡Faltan recuerdos centrales!",
        ["Automaton, you must help fix this. Do not neglect you duties."] = "Autómata, debes ayudar a solucionar este problema. No descuides tus deberes.",
        ["Make some space and return to me."] = "Haz un poco de espacio y regresa a mí.",
        ["[The Archivist hands you two jars: one empty, and one full.]"] = "[The Archivist te entrega dos frascos: uno vacío y otro lleno.]",
        ["Routine one: I have given you a full jar. Deposit it at the far side of this hall."] = "Rutina uno: Te he dado un frasco lleno. Deposítalo al otro lado de esta sala.",
        ["Routine two: I have given you an empty jar. Fill it with energy from the scattered memories in the hall. Once full - well, see routine one."] = "Rutina dos: Te he dado un frasco vacío. Llénalo con energía de los recuerdos dispersos por el pasillo. Una vez lleno, bueno, vea la rutina uno.",
        ["You can find more jars in the room to the east of here."] = "Puedes encontrar más frascos en la habitación al este de aquí.",
        ["[A memory-storage bot jumps into your backpack. This bot will automatically look to recover data when harvesting from Lustrous memories within the Hall of Memories.]"] = "[Un robot de almacenamiento de memoria ingresa a tu backpack. Este robot buscará automáticamente recuperar datos al recolectar recuerdos de Lustrous dentro del Salón de los Recuerdos.]",
        ["Additional subroutine: Take this memory-bot with you, and it will gradually recover a core memory as you work, like human urns. I have five memory-bots for you to complete."] = "Subrutina adicional: lleva este robot de memoria contigo y gradualmente recuperará una memoria central a medida que trabajas, como las urnas humanas. Tengo cinco robots de memoria para que los completes.",
        ["Once a memory bot has completed its job, it will have fully recovered a core memory.<br><br>Each recovered core memory unlocks a bonus effect related to Divination."] = "Una vez que un robot de memoria haya completado su trabajo, habrá recuperado completamente una memoria central.<br><br>Cada memoria central recuperada desbloquea un efecto adicional relacionado con Divination.",
        ["Greetings automaton. What can I do for you?"] = "Saludos autómata. ¿Qué puedo hacer por ti?",
        ["*(If the fully charged Aagi memory-storage bot is in your inventory:)*"] = "*(Si el robot de almacenamiento de memoria Aagi completamente cargado está en tu inventario:)*",
        ["How's the little memory-storage bot doing?"] = "¿Cómo le va al pequeño robot de almacenamiento de memoria?",
        ["As a reward for completing the recovery progress, you receive 10,000 Divination XP."] = "Como recompensa por completar el progreso de recuperación, recibirás 10,000 Divination XP.",
        ["You will now benefit from the following: Extra passive effect from the Memorial to Guthix fountain of energy."] = "Ahora te beneficiarás de lo siguiente: Efecto pasivo adicional de la fuente de energía Memorial a Guthix.",
        ["You will now benefit from the following:<br /><br />Extra passive effect from the Memorial to Guthix fountain of energy."] = "Ahora te beneficiarás de lo siguiente:<br /><br />Efecto pasivo adicional de la fuente de energía Memorial to Guthix.",
        ["Excellent work Automaton, the recovery process looks to be complete, however there are still other core memories that need recovering."] = "Excelente trabajo Automaton, el proceso de recuperación parece estar completo, sin embargo, todavía hay otros recuerdos centrales que necesitan recuperarse.",
        ["*(If the player is below level 80 Divination:)*"] = "*(Si el player está por debajo del nivel 80 Divination:)*",
        ["You need Divination level 80 for the next memory-storage bot."] = "Necesitas Divination nivel 80 para el próximo robot de almacenamiento de memoria.",
        ["You do not appear to be experienced enough yet to take on another memory-storage bot."] = "Parece que aún no tienes suficiente experiencia para enfrentarte a otro robot de almacenamiento de memoria.",
        ["A memory-storage bot jumps into your backpack.<br /><br />This bot will automatically look to recover data when harvesting from {{Colour|#DF50B5|Brilliant}} memories within the Hall of Memories."] = "Un robot de almacenamiento de memoria salta a tu backpack.<br /><br />. Este robot buscará automáticamente recuperar datos al recolectar de {{Colour|#DF50B5|Brilliant}} recuerdos dentro del Salón de los Recuerdos.",
        ["*(If the fully charged Seren memory-storage bot is in your inventory:)*"] = "*(Si el robot de almacenamiento de memoria Seren completamente cargado está en tu inventario:)*",
        ["As a reward for completing the recovery progress, you receive 20,000 Divination XP."] = "Como recompensa por completar el progreso de recuperación, recibirás 20 000 Divination XP.",
        ["You will now benefit from the following: Increased memory strand gain whilst in the Hall of Memories."] = "Ahora se beneficiará de lo siguiente: Mayor ganancia de memoria mientras esté en el Salón de los Recuerdos.",
        ["You will now benefit from the following:<br /><br />Increased memory strand gain whilst in the Hall of Memories."] = "Ahora se beneficiará de lo siguiente: <br /><br /> Mayor ganancia de memoria mientras esté en el Salón de los Recuerdos.",
        ["*(If the player is below level 85 Divination:)*"] = "*(Si el player está por debajo del nivel 85 Divination:)*",
        ["You need Divination level 85 for the next memory-storage bot."] = "Necesitas Divination nivel 85 para el próximo robot de almacenamiento de memoria.",
        ["A memory-storage bot jumps into your backpack.<br /><br />This bot will automatically look to recover data when harvesting from {{Colour|#1A2E5D|Radiant}} memories within the Hall of Memories."] = "Un robot de almacenamiento de memoria salta a tu backpack.<br /><br />. Este robot buscará automáticamente recuperar datos cuando recopile recuerdos de {{Colour|#1A2E5D|Radiant}} dentro del Salón de los Recuerdos.",
        ["*(If the fully charged Juna memory-storage bot is in your inventory:)*"] = "*(Si el robot de almacenamiento de memoria Juna completamente cargado está en tu inventario:)*",
        ["As a reward for completing the recovery progress, you receive 30,000 Divination XP."] = "Como recompensa por completar el progreso de recuperación, recibirás 30 000 Divination XP.",
        ["You will now benefit from the following: Able to create three divine locations per day."] = "Ahora te beneficiarás de lo siguiente: Podrás crear tres ubicaciones divinas por día.",
        ["You will now benefit from the following:<br /><br />Able to create three divine locations per day."] = "Ahora te beneficiarás de lo siguiente:<br /><br />Podrás crear tres ubicaciones divinas por día.",
        ["*(If the player is below level 90 Divination:)*"] = "*(Si el player está por debajo del nivel 90 Divination:)*",
        ["You need Divination level 90 for the next memory-storage bot."] = "Necesitas Divination nivel 90 para el próximo robot de almacenamiento de memoria.",
        ["A memory-storage bot jumps into your backpack.<br /><br />This bot will automatically look to recover data when harvesting from Luminous memories within the Hall of Memories."] = "Un robot de almacenamiento de memoria ingresa a su backpack.<br /><br />. Este robot buscará automáticamente recuperar datos cuando recolecte recuerdos luminosos dentro del Salón de los Recuerdos.",
        ["*(If the fully charged Sword of Edicts memory-storage bot is in your inventory:)*"] = "*(Si el robot de almacenamiento de memoria Sword of Edicts completamente cargado está en tu inventario:)*",
        ["As a reward for completing the recovery progress, you receive 40,000 Divination XP."] = "Como recompensa por completar el progreso de recuperación, recibirás 40 000 Divination XP.",
        ["You will now benefit from the following: Increased memory gain when harvesting from faded memories."] = "Ahora se beneficiará de lo siguiente: Mayor ganancia de memoria al recolectar recuerdos desvaídos.",
        ["You will now benefit from the following:<br /><br />Increased memory gain when harvesting from faded memories."] = "Ahora se beneficiará de lo siguiente:<br /><br />Mayor ganancia de memoria al recolectar recuerdos desvaídos.",
        ["*(If the player is below level 95 Divination:)*"] = "*(Si el player está por debajo del nivel 95 Divination:)*",
        ["You need Divination level 95 for the next memory-storage bot."] = "Necesitas Divination nivel 95 para el próximo robot de almacenamiento de memoria.",
        ["A memory-storage bot jumps into your backpack.<br /><br />This bot will automatically look to recover data when harvesting from {{Colour|#5C16D9|Incandescent}} memories within the Hall of Memories."] = "Un robot de almacenamiento de memoria salta a tu backpack.<br /><br />. Este robot buscará automáticamente recuperar datos al recolectar de {{Colour|#5C16D9|Incandescente}} recuerdos dentro del Salón de los Recuerdos.",
        ["*(If the fully charged Cres memory-storage bot is in your inventory:)*"] = "*(Si el bot de almacenamiento de memoria Cres completamente cargado está en tu inventario:)*",
        ["{Ttact|removes=memory-storage bot (Cres)}}"] = "{Ttact|removes=bot de almacenamiento de memoria (Cres)}}",
        ["You will now benefit from the following:<br /><br />Increased energy gain when converting memories."] = "Ahora se beneficiará de lo siguiente:<br /><br />Mayor ganancia de energía al convertir recuerdos.",
        ["Excellent work Automaton, the recovery process looks to be complete. We could always do with some backups."] = "Excelente trabajo Automaton, el proceso de recuperación parece estar completo. Siempre nos vendrían bien algunas copias de seguridad.",
        ["A memory-storage bot jumps into your backpack. This bot will automatically look to recover data when harvesting from various memories within the Hall of Memories."] = "Un robot de almacenamiento de memoria ingresa a tu backpack. Este robot buscará automáticamente recuperar datos al recolectar de varios recuerdos dentro del Salón de los Recuerdos.",
        ["*(If the fully charged generic memory-storage bot is in your inventory:)*"] = "*(Si el robot genérico de almacenamiento de memoria completamente cargado está en tu inventario:)*",
        ["Select an Option"] = "Selecciona una opción",
        ["About those core memories.."] = "Sobre esos recuerdos centrales...",
        ["About those core memories..."] = "Acerca de esos recuerdos centrales...",
        ["[Lustrous] memories within the Hall of Memories.}}"] = "Recuerdos [Lustrous] dentro del Salón de los Recuerdos.}}",
        ["*(If the Seren memory-storage bot was lost:)*"] = "*(Si se perdió el bot de almacenamiento de memoria Seren:)*",
        ["A memory-storage bot jumps into your backpack."] = "Un robot de almacenamiento de memoria ingresa a tu backpack.",
        ["This bot will automatically look to recover data when harvesting from {{Colour|#DF50B5|Brilliant}} memories within the Hall of Memories."] = "Este robot buscará automáticamente recuperar datos al recolectar recuerdos de {{Colour|#DF50B5|Brilliant}} dentro del Salón de los Recuerdos.",
        ["*(If the Juna memory-storage bot was lost:)*"] = "*(Si se perdió el bot de almacenamiento de memoria Juna:)*",
        ["This bot will automatically look to recover data when harvesting from {{Colour|#1A2E5D|Radiant}} memories within the Hall of Memories."] = "Este bot buscará automáticamente recuperar datos al recolectar de {{Colour|#1A2E5D|Radiant}} recuerdos dentro del Salón de los Recuerdos.",
        ["*(If the Sword of Edicts memory-storage bot was lost:)*"] = "*(Si el robot de almacenamiento de memoria Sword of Edicts se perdió:)*",
        ["This bot will automatically look to recover data when harvesting from {{Colour|#D58A16|Luminous}} memories within the Hall of Memories."] = "Este bot buscará automáticamente recuperar datos al recolectar de {{Colour|#D58A16|Luminous}} recuerdos dentro del Salón de los Recuerdos.",
        ["*(If the Cres memory-storage bot was lost:)*"] = "*(Si el bot de almacenamiento de memoria Cres se perdió:)*",
        ["This bot will automatically look to recover data when harvesting from {{Colour|#5C16D9|Incandescent}} memories within the Hall of Memories."] = "Este robot buscará automáticamente recuperar datos al recolectar de {{Colour|#5C16D9|Incandescent}} recuerdos dentro del Salón de los Recuerdos.",
        ["*(If the regular memory-storage bot isn't carried:)*"] = "*(Si no se lleva el robot de almacenamiento de memoria normal:)*",
        ["All core memory data has been recovered. I have archived the information safely and securely. We could do with some back-ups, though."] = "Se han recuperado todos los datos de la memoria central. He archivado la información de forma segura. Aunque nos vendrían bien algunos refuerzos.",
        ["*(If the player owns the bot:)*"] = "*(Si el player es propietario del bot:)*",
        ["How do you expect me to analyse the recovery process if you don't have the bot with you?"] = "¿Cómo esperas que analice el proceso de recuperación si no tienes el bot contigo?",
        ["*(If the player has lost the bot:)*"] = "*(Si el player ha perdido el bot:)*",
        ["*(Without space in backpack:)*"] = "*(Sin espacio en backpack :)*",
        ["*(With space in backpack:)*"] = "*(Con espacio en backpack:)*",
        ["This bot will automatically look to recover data when harvesting from various memories within the Hall of Memories."] = "Este robot buscará automáticamente recuperar datos al recolectar de varios recuerdos dentro del Salón de los Recuerdos.",
        ["*(With all core memory-storage bots handed in:)*"] = "*(Con todos los robots de almacenamiento de memoria principales entregados :)*",
        ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
        ["*(With a partially charged memory-storage bot:)*"] = "*(Con un robot de almacenamiento de memoria parcialmente cargado:)*",
        ["The recovery process is not yet complete. GO!"] = "El proceso de recuperación aún no está completo. ¡IR!",
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["Why do ask a question that you already know?"] = "¿Por qué hacer una pregunta que ya sabes?",
        ["We are here to preserve Guthix's deepest memories. We are the archivists of his most important knowledge."] = "Estamos aquí para preservar los recuerdos más profundos de Guthix. Somos los archiveros de sus conocimientos más importantes.",
        ["Anything I can do around here?"] = "¿Hay algo que pueda hacer por aquí?",
        ["Automaton, are you malfunctioning? Everything must stay contained within this hall."] = "Autómata, ¿estás funcionando mal? Todo debe permanecer contenido dentro de esta sala.",
        ["The memories must be stored in the jars. Those can be found in the storage room to the east of here."] = "Los recuerdos deben guardarse en los frascos. Estos se pueden encontrar en el almacén al este de aquí.",
        ["Once contained, the full jars should be deposited on the far side of this hall."] = "Una vez contenidos, los frascos llenos deben depositarse en el otro lado de esta sala.",
        ["The butterflies carry a blessing of recollection. This blessing will recall memory shards on occasion."] = "Las mariposas llevan la bendición del recuerdo. Esta bendición recordará fragmentos de recuerdos en ocasiones.",
        ["There are remnants of memories left that should also be contained, but as they have faded they aren't a priority."] = "Quedan restos de recuerdos que también deberían contenerse, pero como se han desvanecido no son una prioridad.",
        ["The chamber can be unpredictable at times, so you must be ready, should anything happen."] = "La cámara puede ser impredecible a veces, por lo que debes estar preparado en caso de que suceda algo.",
        ["Oh right! Yeah I remember now."] = "¡Ah, claro! Sí, ahora lo recuerdo.",
        ["Good. You're not malfunctioning after all."] = "Bien. Después de todo, no estás funcionando mal.",
        ["Nothing, thanks."] = "Nada, gracias.",
        ["In time, you might come to see my choice to die as a selfish act, but I am decided. I have prepared for this for centuries, ever since you visited me and I became aware of my fate. But if the mortals are not ready now, they never shall be. Maintaining the Edicts has taken too much of a toll. And I cannot stall things forever. I am so very tired. I will leave you with a fighting chance, a glimmer of hope, but you will have to find your own way, World Guardian. Use the power I shall bestow upon you, the knowledge in these caches and the guidance of my guardians. If you should fail, then at least the afterlife should welcome the fallen for a time, until that too fails. When I see you at my end, I shall tell you I wish to be with my wife and daughter in death. However, the truth is that I gave up my right to that a long time ago - unwittingly, but unequivocally. And though I know I shall never see my Aagi or Fraji again, I have lived long enough without them. In this place, I shall leave my strongest memories of them. Perhaps they too can help you in some way. I have knowingly left you with a great burden, World Guardian. I hope you can find it in your heart to forgive me."] = "Con el tiempo, es posible que llegues a ver mi decisión de morir como un acto egoísta, pero estoy decidido. Me he preparado para esto durante siglos, desde que me visitaste y tomé conciencia de mi destino. Pero si los mortales no están preparados ahora, nunca lo estarán. Mantener los Edictos ha cobrado demasiado precio. Y no puedo detener las cosas para siempre. Estoy muy cansada. Te dejaré una oportunidad de luchar, un rayo de esperanza, pero tendrás que encontrar tu propio camino, Guardián Mundial. Usa el poder que te otorgaré, el conocimiento de estos escondites y la guía de mis guardianes. Si fallas, entonces al menos la otra vida debería dar la bienvenida a los caídos por un tiempo, hasta que eso también falle. Cuando te vea al final, te diré que deseo estar con mi esposa y mi hija en la muerte. Sin embargo, la verdad es que hace mucho tiempo que renuncié a ese derecho, de forma involuntaria pero inequívoca. Y aunque sé que nunca volveré a ver a mi Aagi o a mi Fraji, ya he vivido bastante sin ellos. En este lugar dejaré mis recuerdos más fuertes de ellos. Quizás ellos también puedan ayudarte de alguna manera. A sabiendas te he dejado con una gran carga, Guardián Mundial. Espero que puedas encontrar en tu corazón la capacidad de perdonarme.",
        ["I loved her, even though I knew it was a lie. Not real love. Not the love I felt for Fraji. But love all the same. Something. Is it wrong to have latched on to that? To that strange power she possessed? Not to fight it, but to know it for what it is and accept it all the same? An illusion of connection. A facsimile of my heart in exchange for all of hers? Because I know she loved me. Genuine, true, beautiful love. The love that only the eternal can know, a love spanned the rise and fall of empires. A beautiful lie. But I liked the lie. It was better than the loneliness of the truth and, really, could I ever find something better? So I lied to her. I kept lying to her. For centuries I whispered sweet promises I never really meant and spoke of eternities together, even though I knew our time was finite. Then the time came when I had to cast them all out and on the day I was grateful that it was a lie. I let me turn cold to her suffering, turn away from her misery. I cast her out and thought that would be the end of it. She chose another option. A way to be with all the people she loved. Even me. It really was a beautiful lie."] = "La amaba, aunque sabía que era mentira. No es amor verdadero. No el amor que sentía por Fraji. Pero ama de todos modos. Algo. ¿Está mal haberse aferrado a eso? ¿A ese extraño poder que poseía? ¿No luchar contra ello, sino conocerlo tal como es y aceptarlo de todos modos? Una ilusión de conexión. ¿Un facsímil de mi corazón a cambio de todo el de ella? Porque sé que ella me amaba. Amor genuino, verdadero y hermoso. El amor que sólo lo eterno puede conocer, un amor que abarcó el ascenso y la caída de los imperios. Una hermosa mentira. Pero me gustó la mentira. Era mejor que la soledad de la verdad y, de verdad, ¿podría alguna vez encontrar algo mejor? Entonces le mentí. Seguí mintiéndole. Durante siglos susurré dulces promesas que nunca quise decir y hablé de eternidades juntos, aunque sabía que nuestro tiempo era finito. Luego llegó el momento en que tuve que echarlos a todos y ese día agradecí que fuera mentira. Me dejé volverme frío ante su sufrimiento, alejarme de su miseria. La eché y pensé que ese sería el final. Ella eligió otra opción. Una forma de estar con todas las personas que amaba. Incluso yo. Realmente fue una hermosa mentira.",
        ["I am sorry Juna. I have lied to you. I have been your idol, your god, your father. But I am the reason you are alone. It was a choice you see. It had to be one world or another and I chose the other world. Numbers. Pure numbers. There were more of them, then there were of you. As cold a reason for genocide as any other. So, I placed the lure on your world, a fountain of delicious anima for the blind beast to sniff out. She destroyed your world, it was my fault. Another world lived because of that sacrifice, cold comfort though that may be. I wanted to save more of you. So I grabbed two eggs, you and your sister. I thought that perhaps if I could save a family it would be my absolution. I would have saved more, but the beast was on your world so fast, faster than I had dared think possible. So I saved you and your sister. Two eggs. The last of their kind. I thought I could save you. I thought all you needed was me to look after you, but only you hatched. Only your egg survived. I couldn't bear the shame of you knowing. So I hid your sister. Buried her lifeless egg where no one will ever find it. And I never told you about her. Each time we meet I yearn to ask for your forgiveness. But then I see the look in your eyes. I see the standard to which you hold me. The hope, the faith, the love you have for me and my courage crumbles. I am so proud of you Juna. You are like a daughter to me, I hope you know that. And if you find this message, I pray that one day you can forgive me."] = "Lo siento Juna. Te he mentido. He sido tu ídolo, tu dios, tu padre. Pero yo soy la razón por la que estás solo. Fue una elección, ya ves. Tenía que ser un mundo u otro y elegí el otro mundo. Números. Números puros. Había más de ellos que tú. Un motivo de genocidio tan frío como cualquier otro. Entonces, coloqué el señuelo en tu mundo, una fuente de deliciosa ánima para que la bestia ciega la olfatee. Ella destruyó tu mundo, fue mi culpa. Otro mundo vivió gracias a ese sacrificio, por muy frío que sea ese consuelo. Quería salvar más de ti. Así que cogí dos huevos, tú y tu hermana. Pensé que tal vez si podía salvar a una familia sería mi absolución. Habría ahorrado más, pero the beast llegó a tu mundo tan rápido, más rápido de lo que me había atrevido a creer posible. Entonces te salvé a ti y a tu hermana. Dos huevos. El último de su tipo. Pensé que podría salvarte. Pensé que todo lo que necesitabas era que yo te cuidara, pero solo tú naciste. Sólo tu óvulo sobrevivió. No podría soportar la vergüenza de que lo supieras. Entonces escondí a tu hermana. Enterró su huevo sin vida donde nadie podrá encontrarlo jamás. Y nunca te hablé de ella. Cada vez que nos encontramos anhelo pedirte perdón. Pero luego veo la mirada en tus ojos. Veo el estándar al que me sujetas. La esperanza, la fe, el amor que me tienes y mi coraje se desmorona. Estoy muy orgulloso de ti Juna. Eres como una hija para mí, espero que lo sepas. Y si encuentras este mensaje, rezo para que algún día puedas perdonarme.",
        ["Enough! My intention to be forgotten is futile if other gods fill the void in the hearts of mortals. This is not the fault of gods, but the folly of mortals to be meek and unquestioning. While I spend all my will stalling the inevitable end of mortality, while I wasted my time protecting them from inevitable destruction, they instead dash their own lives on the altar of worship. Such futility - it must stop! Mortal life is brief enough as is. It should not be wasted in servitude to power, in worship of false idols, in the hopes of a reward beyond death. When will they learn that life itself is the reward? It should be treated as such, spent in joy and discovery, in time with loved ones, in the betterment of self... The petty tribal rivalries of so-called gods are nothing but a distraction, and one I must try to remove. I shall evict the gods and their influence from this world, even though maintaining a barrier to keep them out will split my focus. As a result, I shall not be able to delay the inevitable for anywhere near as long as I had hoped. The elders will wake anew. But better for mortals to realise their end is nigh and start living their lives, fighting for it themselves, than me mollycoddling them and gifting them limitless time in which to act as sheep. They are blinded to this truth of this reality by their own folly. If allowing their end to come sooner will force them to open their eyes, then so be it."] = "¡Ya basta! Mi intención de ser olvidado es inútil si otros dioses llenan el vacío en los corazones de los mortales. Esto no es culpa de los dioses, sino la locura de los mortales por ser mansos e incondicionales. Mientras gasto toda mi voluntad en detener el inevitable fin de la mortalidad, mientras perdí mi tiempo protegiéndolos de la destrucción inevitable, ellos arrojan sus propias vidas en el altar de la adoración. ¡Qué inutilidad... debe parar! La vida mortal es bastante breve tal como es. No debe desperdiciarse en servidumbre al poder, en adoración de ídolos falsos, con la esperanza de una recompensa más allá de la muerte. ¿Cuándo aprenderán que la vida misma es la recompensa? Debería tratarse como tal, dedicarse a la alegría y al descubrimiento, al tiempo con los seres queridos, al mejoramiento personal... Las pequeñas rivalidades tribales de los llamados dioses no son más que una distracción, y debo tratar de eliminarla. Expulsaré a los dioses y su influencia de este mundo, aunque mantener una barrera para mantenerlos alejados dividirá mi atención. Como resultado, no podré retrasar lo inevitable tanto tiempo como esperaba. Los mayores despertarán de nuevo. Pero es mejor que los mortales se den cuenta de que su fin está cerca y comiencen a vivir sus vidas, luchando por ellas mismas, que que yo los mime y les regale tiempo ilimitado para actuar como ovejas. Están cegados a esta verdad de esta realidad por su propia locura. Si permitir que su fin llegue antes los obligará a abrir los ojos, que así sea.",
        ["How do you choose who to sacrifice? The caching of my knowledge is a task of great importance to the future survival of existence. But the being I select to fulfill this task is doomed. I know they must sacrifice all to complete their work - their humanity, their will, their peace beyond death. I know already when and how they will fall into oblivion...and yet there is no other way. The forbidden secrets of this universe and beyond must be recorded while I still live, so that they can be metered out only when the time is right. The Great Revision. The Broken Needle. The Shadow Breach. If that knowledge is lost, all things shall end. Not just life. Not just the universe. Everything. Time and space, and life and death... I suppose death is the fairest way to choose. I shall request Harold to deliver the next suitable candidate to me, instead of to the Underworld. They will have no choice but to become one of my guardians, and to perform this task for me...for everyone."] = "¿Cómo eliges a quién sacrificar? El almacenamiento en caché de mis conocimientos es una tarea de gran importancia para la futura supervivencia de la existencia. Pero el ser que selecciono para cumplir esta tarea está condenado. Sé que deben sacrificarlo todo para completar su trabajo: su humanidad, su voluntad, su paz más allá de la muerte. Ya sé cuándo y cómo caerán en el olvido... y sin embargo no hay otra manera. Los secretos prohibidos de este universo y más allá deben ser registrados mientras todavía viva, para que puedan ser dosificados sólo cuando sea el momento adecuado. La gran revisión. La aguja rota. La Brecha de las Sombras. Si ese conocimiento se pierde, todo terminará. No sólo la vida. No sólo el universo. Todo. Tiempo y espacio, vida y muerte... Supongo que la muerte es la forma más justa de elegir. Le pediré a Harold que me entregue el próximo candidato adecuado a mí, en lugar de al Inframundo. No tendrán más remedio que convertirse en uno de mis guardianes y realizar esta tarea por mí... por todos.",
        ["The Archivist:WARNING: Core memory fragment released, data must be contained."] = "The Archivist:ADVERTENCIA: Se liberó un fragmento de memoria central; los datos deben estar contenidos.",
        ["*(If the fragment is caught:)*"] = "*(Si el fragmento es atrapado:)*",
        ["The Archivist:Core memory fragment contained, issue resolved."] = "The Archivist: Fragmento de memoria central contenido, problema resuelto.",
        ["The Archivist:WARNING: All plinths emanating excessive amounts of energy! Core memory playback initiated, please stand by..."] = "The Archivist:ADVERTENCIA: ¡Todos los pedestales emanan cantidades excesivas de energía! Se inició la reproducción de la memoria central, espere...",
        ["The Archivist:WARNING: Core memory playback active, data must be preserved."] = "The Archivist:ADVERTENCIA: Reproducción de la memoria central activa, los datos deben conservarse.",
        ["The Archivist:UPDATE: Core memory playback ended."] = "The Archivist:ACTUALIZACIÓN: La reproducción de la memoria central finalizó.",
        ["The Archivist:WARNING! WARNING! Knowledge overflow inbound. Data must be contained!"] = "The Archivist: ¡ADVERTENCIA! ¡ADVERTENCIA! El conocimiento se desborda hacia el interior. ¡Los datos deben estar contenidos!",
        ["*(The following line may appear multiple or zero times:)*"] = "*(La siguiente línea puede aparecer varias o ninguna vez:)*",
        ["The Archivist:WARNING: Further knowledge overflow waves detected."] = "The Archivist: ADVERTENCIA: Se detectaron ondas de desbordamiento de conocimientos adicionales.",
        ["The Archivist:UPDATE: Final knowledge overflow wave complete. Data is being contained."] = "The Archivist:ACTUALIZACIÓN: Ola final de desbordamiento de conocimientos completa. Los datos están siendo contenidos.",
        ["The Archivist:WARNING: Unstable craters observed, intruders entering Guthixian caches! Automaton, I can send you there."] = "The Archivist: ADVERTENCIA: Se observan cráteres inestables, ¡intrusos ingresan a los escondites de Guthixian! Autómata, puedo enviarte allí.",
    },
    ["The Assassin"] = {
        ["What do you want?"] = "¿Qué quieres?",
        ["How are things going with you, Ling?"] = "¿Cómo te va, Ling?",
        ["I'm investigating that group of slavers who've been operating in the Arc region. They must learn that they cannot just take what they want, not if they want to keep their heads. Your port is full of idle talk. It is the perfect place to glean information."] = "Estoy investigando ese grupo de esclavistas que han estado operando en la región de Arc. Deben aprender que no pueden simplemente tomar lo que quieren, no si quieren conservar la cabeza. Tu puerto está lleno de charlas ociosas. Es el lugar perfecto para obtener información.",
        ["I'd rather not be hiding in taverns, but ever since that Death Lotus assassin spotted me I have had to keep a low profile."] = "Preferiría no esconderme en tabernas, pero desde que el asesino del Loto de la Muerte me vio, he tenido que mantener un perfil bajo.",
        ["I'm just taking a break from interrogating Bak, that boorish Death Lotus assassin we captured. Nothing like interrogation to build up a thirst."] = "Estoy tomando un descanso del interrogatorio a Bak, ese grosero asesino del Loto de la Muerte que capturamos. Nada como un interrogatorio para tener sed.",
        ["Kirau is still looking for Baby Tooth's location.  The Death Lotus leader is a man difficult to track down.  Luckily for me, Kirau is excellent at what he does."] = "Kirau todavía está buscando la ubicación de Baby Tooth.  El líder de Death Lotus es un hombre difícil de localizar.  Por suerte para mí, Kirau es excelente en lo que hace.",
        ["How do you think things are going?  Kirau's betrayal has left me stung.  But I will have my revenge.  He will die with my hands about his throat.  I've returned here to see what information I can gather, someone must know where Kirau is hiding."] = "¿Cómo crees que van las cosas?  La traición de Kirau me ha dejado dolido.  Pero tendré mi venganza.  Morirá con mis manos alrededor de su garganta.  He regresado aquí para ver qué información puedo reunir, alguien debe saber dónde se esconde Kirau.",
        ["I'm still basking in my newfound freedom. With the Death Lotus in ruins I can live my life as I wish. I have you to thank for that."] = "Todavía estoy disfrutando de mi nueva libertad. Con el Loto de la Muerte en ruinas puedo vivir mi vida como deseo. Tengo que agradecerte por eso.",
        ["I am anxious to continue with our campaign against Quin. I cannot wait to see what you have planned next."] = "Estoy ansioso por continuar con nuestra campaña contra Quin. No puedo esperar a ver qué tienes planeado a continuación.",
        ["I can scarcely believe Kirau's family forgave me. With their support, we will kill Quin - believe me."] = "No puedo creer que la familia de Kirau me haya perdonado. Con su apoyo, mataremos a Quin, créanme.",
        ["One day, I hope to set up a guild of assassins to rival the Death Lotus. For now, I think there's a lot to be learned from watching you in action."] = "Algún día espero crear un gremio de asesinos que pueda rivalizar con el Loto de la Muerte. Por ahora, creo que hay mucho que aprender al verte en acción.",
        ["I'm in need of someone with your skills..."] = "Necesito a alguien con tus habilidades...",
        ["Certainly. I would never turn down a chance to practice my skills."] = "Por supuesto. Nunca rechazaría la oportunidad de practicar mis habilidades.",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["If you could find a suitable partner - someone who's used to the shadows - I'd consider working with them."] = "Si pudieras encontrar un socio adecuado, alguien que esté acostumbrado a las sombras, consideraría trabajar con él.",
        ["Unlock the Convict (90 Thieving required) to unlock additional joint voyages."] = "Desbloquea the Convict (se requieren 90 Thieving) para desbloquear viajes conjuntos adicionales.",
        ["I'd consider working with that convict who frequents your bar. We practice similar crafts."] = "Consideraría trabajar con ese preso que frecuenta tu bar. Practicamos manualidades similares.",
        ["If both the Convict and Assassin are in port at the same time, additional joint voyages will be made available."] = "Si tanto the Convict como Assassin están en el puerto al mismo tiempo, estarán disponibles viajes conjuntos adicionales.",
        ["I suppose I could do a job with that convict over there. He could watch my back."] = "Supongo que podría hacer un trabajo con ese convicto de allí. Podría cuidarme la espalda.",
        ["Convict? Watch YOUR back? I've never been so insulted."] = "¿Convicto? ¿Cuida TU espalda? Nunca me había sentido tan insultado.",
        ["How's the life of an assassin?"] = "¿Cómo es la vida de un asesino?",
        ["Not too different from yours, I'd imagine. We are both skilled killers, are we not? You know what a heavy burden that can be, but by only killing the deserving... Well, that can help."] = "No muy diferente del tuyo, me imagino. Ambos somos asesinos hábiles, ¿no? Sabes lo pesada que puede ser esa carga, pero matar sólo a los que lo merecen... Bueno, eso puede ayudar.",
        ["[View Previous Cutscenes]"] = "[Ver escenas anteriores]",
        ["I'm fine for drinks."] = "Estoy bien para tomar unas copas.",
        ["I can't say I trust you, old man."] = "No puedo decir que confíe en ti, old man.",
        ["Hmm, you are a skilled assassin, I can tell. I am in need of someone such as you, but first I must know that I can trust you."] = "Hmm, eres un hábil asesino, lo noto. Necesito a alguien como tú, pero primero debo saber que puedo confiar en ti.",
        ["To get contracts from Ling, you must first complete the 'Meet the Assassin' Ports voyage."] = "Para obtener contracts de Ling, primero debe completar el viaje por los puertos 'Conozca the Assassin'.",
        ["Hello, Little Khan. Do you seek a Death Lotus Slayer contract?"] = "Hola, pequeño Khan. ¿Buscas un contrato Death Lotus Slayer?",
        ["Talk about slayer contracts?"] = "¿Hablar del asesino contracts?",
        ["Yes."] = "Sí.",
    },
    ["The Barmaid"] = {
        ["Hello there, love. Alright?"] = "Hola, amor. ¿Está bien?",
        ["Select an option:"] = "Selecciona una opción",
        ["How are things going, Surula?"] = "¿Cómo van las cosas, Surula?",
        ["Oh, I can't complain, Portmaster. The adventurers and captains who turn up here every day keep my busy. Mind you, John was here last night. Drunk of course. Shouting something about sailing one of the ships eastwards. Bless him. I'm glad you're here. We've needed someone to sort this place out for a long time. For the past few years its felt like we've been trapped in cobwebs and shadows. With you here, it feels light again."] = "Oh, no me puedo quejar, capitán de puerto. Los aventureros y capitanes que aparecen aquí todos los días me mantienen ocupado. Eso sí, John estuvo aquí anoche. Borracho por supuesto. Gritando algo sobre navegar uno de los barcos hacia el este. Bendito sea. Me alegro que estés aquí. Hace tiempo que necesitábamos que alguien arreglara este lugar. Durante los últimos años hemos sentido como si hubiéramos estado atrapados en telarañas y sombras. Contigo aquí, se siente ligero otra vez.",
        ["Could I ask a personal question?"] = "¿Puedo hacer una pregunta personal?",
        ["You want to know about the tentacles, right?"] = "Quieres saber sobre los tentáculos, ¿verdad?",
        ["Er - yes."] = "Er, sí.",
        ["Oh, dont blush, little octopus. You see there's an afflication in the east, no one knows the cause of it, but some of us are born with gills, tentacles, even fins. One poor man had flippers; meant he couldn't wear shoes. You'd reckon looking like this we'd have some special powers, like that siren sulking around the docks, but you'd be wrong. I can swim better than most, sure, but that's about it. Of course, there's many folks who are distrustful of us. They call us sea orphans, which says a lot. And some are more than just distrustful. The Purists in the Scythe region hate us with a real passion. They spread lies about us, beat us up, kill us when they get the chance, scare mothers into drowning us at birth. No one does much about them. Cruel folks, them Purists. Ah...sorry, love. You don't want to hear me prattle on."] = "Oh, no te sonrojes, pulpito. Verá, hay una aflicción en el este, nadie sabe la causa, pero algunos de nosotros nacemos con branquias, tentáculos e incluso aletas. Un hombre pobre tenía aletas; significaba que no podía usar zapatos. Pensarías que con esta apariencia tendríamos algunos poderes especiales, como esa sirena enfurruñada en los muelles, pero estarías equivocado. Puedo nadar mejor que la mayoría, claro, pero eso es todo. Por supuesto, hay mucha gente que desconfía de nosotros. Nos llaman huérfanos del mar, lo cual dice mucho. Y algunos son más que simplemente desconfiados. Los puristas de la región de Scythe nos odian con verdadera pasión. Difunden mentiras sobre nosotros, nos golpean, nos matan cuando tienen la oportunidad, asustan a las madres para que nos ahoguen al nacer. Nadie hace mucho por ellos. Gente cruel, esos puristas. Ah... lo siento, amor. No querrás oírme hablar más.",
        ["Got any gossip?"] = "¿Tienes algún chisme?",
        ["There's nothing doing the rounds at the moment, love, but I'll keep my tentacles to the ground."] = "No hay nada circulando en este momento, amor, pero mantendré mis tentáculos en el suelo.",
        ["Speak to the barmaid on Thursday for new gossip."] = "Habla con the barmaid el jueves para conocer nuevos chismes.",
        ["Got word of a special little something your crews might find appealing, if you're up for it."] = "Me enteré de algo especial que a tus equipos les podría resultar atractivo, si te apetece.",
        ["Replace your third listed mission with the Barmaid's Tip?"] = "¿Reemplazar la tercera misión de la lista con el consejo de the Barmaid?",
        ["Yes."] = "Sí.",
        ["Oh, you're gonna love this!"] = "¡Oh, esto te va a encantar!",
        ["Hope that tip worked out well for you, my love."] = "Espero que ese consejo te haya funcionado bien, mi amor.",
        ["Any chance of a beer?"] = "¿Alguna posibilidad de una cerveza?",
        ["One coin has been removed from your money pouch."] = "Se ha retirado una moneda de su bolsa de dinero.",
        ["There you go, my little barnacle, nice and frothy."] = "Ahí lo tienes, mi pequeño percebe, agradable y espumoso.",
        ["[You buy a poorly poured beer, missing most of its head.]"] = "[Compras una cerveza mal servida a la que le falta la mayor parte de la espuma.]",
        ["Poor little octopus. You don't have even the coin to buy a beer. Times must be tough around here."] = "Pobre pulpito. No tienes ni siquiera la moneda para comprar una cerveza. Deben ser tiempos difíciles por aquí.",
        ["I better be going. Things to do."] = "Será mejor que me vaya. Cosas que hacer.",
        ["You take care, now."] = "Ahora cuídate tú.",
        ["Rumour has it that Surula the barmaid has some juicy gossip for you."] = "Se rumorea que Surula the barmaid tiene algunos chismes jugosos para ti.",
    },
    ["The Beast"] = {
        ["Hello cat."] = "Hola gato.",
        ["Friendly aren't you?"] = "Amable, ¿no?",
    },
    ["The Biologist"] = {
        ["Select an option"] = "Seleccione una opción",
        ["How are you, Bethan?"] = "¿Cómo estás, Bethan?",
        ["*(Before Documentary Evidence:)*"] = "*(Antes de la evidencia documental:)*",
        ["Well, I'm very interested in this race of sea orphans. Of course I've met the one downstairs, but she was most unwilling to help. She seemed entirely resistant to my prodding and my attempts to measure her head. She was most rude about it. No, I need to see them in their natural habitat - there's a great number of them on Hyu-Ji. Once I've got funding from the museum, we'll set sail."] = "Bueno, estoy muy interesado en esta raza de huérfanos del mar. Por supuesto que conocí a la de abajo, pero ella no estaba muy dispuesta a ayudar. Parecía completamente resistente a mis insistencias y a mis intentos de medir su cabeza. Ella fue muy grosera al respecto. No, necesito verlos en su hábitat natural; hay un gran número de ellos en Hyu-Ji. Una vez que tenga financiación del museo, zarparemos.",
        ["*(After Documentary Evidence:)*"] = "*(Después de la evidencia documental:)*",
        ["Gah! It's most frustrating. I just need to get amongst these sea orphans. Science cannot be practised from afar! But don't you worry - I have a plan."] = "¡Ah! Es muy frustrante. Sólo necesito estar entre estos huérfanos del mar. ¡La ciencia no se puede practicar desde lejos! Pero no te preocupes, tengo un plan.",
        ["*(After Specimens In The Wild:)*"] = "*(Después de especímenes en la naturaleza:)*",
        ["I can't remember when I last felt so invigorated. It's like I've been dipped in essence of torstol. Now that I have my lab, and access to my delightfully poisonous Finia, the science will flow!"] = "No recuerdo cuándo fue la última vez que me sentí tan vigorizado. Es como si me hubieran sumergido en esencia de torstol. Ahora que tengo mi laboratorio y acceso a mi deliciosamente venenosa Finia, ¡la ciencia fluirá!",
        ["*(After The Scientific Method:)*"] = "*(Después del método científico:)*",
        ["Oh the science is advancing nicely. Finia is going to be my shining case-study. I can barely wait."] = "Oh, la ciencia avanza muy bien. Finia será mi brillante caso de estudio. Apenas puedo esperar.",
        ["*(After The Act Of Observing:)*"] = "*(Después del acto de observar:)*",
        ["I'm investigating the break-in at my lab. The more I look at the evidence, the more I'm convinced it was an inside job."] = "Estoy investigando el robo en mi laboratorio. Cuanto más miro las pruebas, más me convenzo de que fue un trabajo interno.",
        ["*(After People are the Deadliest Disease:)*"] = "*(Después de que las personas son la enfermedad más mortal :)*",
        ["Very well! There's not a day that goes by without the sea orphans doing something to amaze me. They're truly a fascinating people."] = "¡Muy bien! No pasa un día sin que los huérfanos del mar hagan algo que me sorprenda. Son realmente un pueblo fascinante.",
        ["*(After Hull Down On The Horizon:)*"] = "*(Después de Hull Down On The Horizon:)*",
        ["Well, I can't believe these scoundrels have joined forces to lay siege to Hyu-Ji. It's almost like they don't care how scientifically significant the sea orphans are!"] = "Bueno, no puedo creer que estos sinvergüenzas hayan unido fuerzas para sitiar Hyu-Ji. ¡Es casi como si no les importara la importancia científica que tienen los huérfanos del mar!",
        ["*(After A Concerted Effort:)*"] = "*(Después de un esfuerzo concertado:)*",
        ["I'm ready for the attack! Ooo, I'll cook up something that'll torch even the most water-logged boat."] = "¡Estoy listo para el ataque! Ooo, cocinaré algo que incendiará incluso el barco más anegado.",
        ["*(After The Defiance of Hyu-Ji:)*"] = "*(Después del desafío de Hyu-Ji :)*",
        ["I've been pondering what I should do next. The lab on Hyu-Ji is producing fascinating results, but the sea orphans are more than capable of running it. For now, I'll continue with our expeditions. I hope you have a good one lined up!"] = "He estado reflexionando sobre qué debería hacer a continuación. El laboratorio de Hyu-Ji está produciendo resultados fascinantes, pero los huérfanos del mar son más que capaces de ejecutarlo. Por ahora continuaré con nuestras expediciones. ¡Espero que tengas uno bueno preparado!",
        ["I could use your help on an expedition."] = "Me vendría bien tu ayuda en una expedición.",
        ["Certainly, certainly! I'll just grab my apparatus and we'll be off."] = "¡Por supuesto, por supuesto! Cogeré mi aparato y nos iremos.",
        ["*(Voyage list interface opens.)*"] = "*(Se abre la interfaz de lista de viajes.)*",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["*(If The Whaler has not been unlocked:)*"] = "*(Si The Whaler no ha sido desbloqueado:)*",
        ["*(If The Whaler has been unlocked but is not present:)*"] = "*(Si The Whaler ha sido desbloqueado pero no está presente:)*",
        ["Well, I've noticed a whaler who drinks in here from time to time - Hubbub, I think he's called. He seems a little dim, but he's certainly good with nature."] = "Bueno, he notado que un ballenero bebe aquí de vez en cuando. Alboroto, creo que se llama. Parece un poco tonto, pero ciertamente es bueno con la naturaleza.",
        ["If both the Whaler and Biologist are in port at the same time, additional joint voyages will be made available."] = "Si tanto the Whaler como Biologist están en puerto al mismo tiempo, se pondrán a disposición viajes conjuntos adicionales.",
        ["*(If The Whaler has been unlocked and he is present:)*"] = "*(Si The Whaler ha sido desbloqueado y está presente:)*",
        ["Ah - hmm. Well, Hubbub over here could do with some educating. The poor man thinks a whale is a fish. But his heart's in the right place. I'd love to have him join me on my exploits."] = "Ah, mmm. Bueno, a Hubbub por aquí le vendría bien un poco de educación. El pobre piensa que una ballena es un pez. Pero su corazón está en el lugar correcto. Me encantaría que se uniera a mí en mis hazañas.",
        ["Don't worry, portmaster. I'll make sure she doesn't get stuck in a swamp."] = "No te preocupes, capitán de puerto. Me aseguraré de que no se quede atrapada en un pantano.",
        ["How's the life of a biologist?"] = "¿Cómo es la vida de un biólogo?",
        ["Oh, it's thrilling, but you're no stranger to the pursuit of science yourself, are you? Your knowledge of herbs is world-renowned. I've rather been hoping that you'd publish a book with your findings."] = "Oh, es emocionante, pero tú mismo no eres ajeno a la búsqueda de la ciencia, ¿verdad? Tu conocimiento de las hierbas es mundialmente reconocido. Más bien esperaba que publicaras un libro con tus hallazgos.",
        ["[View Previous Cutscenes]"] = "[Ver escenas anteriores]",
        ["*(If the Biologist was not the first adventurer unlocked by the player and the player has not completed any other voyages than \"Meet the Biologist\":)*"] = "*(Si the Biologist no fue el primer aventurero desbloqueado por el player y el player no ha completado ningún otro viaje además de \"Conoce a the Biologist\":)*",
        ["Which story cutscene would you like to see?"] = "¿Qué escena de la historia te gustaría ver?",
        ["*(Each dialogue option is unlocked after successfully completing the relevant voyage:)*"] = "*(Cada opción de diálogo se desbloquea después de completar con éxito el viaje correspondiente :)*",
        ["*(If the Biologist was not the first adventurer unlocked by the player:)*"] = "*(Si the Biologist no fue el primer aventurero desbloqueado por el player:)*",
        ["Meet the Biologist"] = "Conoce a the Biologist",
        ["You're about to watch 'Meet the Biologist'.{{anchor|meet-the-biologist}}"] = "Estás a punto de ver 'Conoce a the Biologist'.{{anchor|meet-the-biologist}}",
        ["Documentary Evidence"] = "Prueba documental",
        ["You're about to watch 'Documentary Evidence'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Prueba Documental'. ¿Quieres ver el principio o el final?",
        ["Beginning."] = "Comienzo.",
        ["End."] = "Fin.",
        ["Specimens In The Wild"] = "Especímenes en la naturaleza",
        ["You're about to watch 'Specimens In The Wild'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Especímenes en la naturaleza'. ¿Quieres ver el principio o el final?",
        ["The Scientific Method"] = "El método científico",
        ["You're about to watch 'The Scientific Method'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'El método científico'. ¿Quieres ver el principio o el final?",
        ["More"] = "Más",
        ["The Act Of Observing"] = "El acto de observar",
        ["You're about to watch 'The Act Of Observing'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'El acto de observar'. ¿Quieres ver el principio o el final?",
        ["People are the Deadliest Disease"] = "Las personas son la enfermedad más mortal",
        ["You're about to watch 'People are the Deadliest Disease'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Las personas son la enfermedad más mortal'. ¿Quieres ver el principio o el final?",
        ["Hull Down On The Horizon"] = "Casco abajo en el horizonte",
        ["You're about to watch 'Hull Down On The Horizon'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Hull Down On The Horizon'. ¿Quieres ver el principio o el final?",
        ["A Concerted Effort"] = "Un esfuerzo concertado",
        ["You're about to watch 'A Concerted Effort'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Un esfuerzo concertado'. ¿Quieres ver el principio o el final?",
        ["The Defiance of Hyu-Ji"] = "El desafío de Hyu-Ji",
        ["You're about to watch 'The Defiance of Hyu-Ji'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'El desafío de Hyu-Ji'. ¿Quieres ver el principio o el final?",
        ["Ah, no, thanks. I'm not a big drinker."] = "Ah, no, gracias. No soy un gran bebedor.",
        ["After those 'heat proof' lamps I bought from you exploded, I'd really rather we didn't speak."] = "Después de que explotaran esas lámparas 'resistentes al calor' que te compré, preferiría no hablar.",
        ["In The Biologist dialogue, she referred to the hostage Finia joining her captor, Blazing Lanterns, as an example of \"Daemonheim Syndrome\". This draws in parallel with the real-life Stockholm syndrome, where the hostage develops a psychological bond with the captor during captivity."] = "En el diálogo de The Biologist, se refirió a la rehén Finia que se unió a su captor, Blazing Lanterns, como un ejemplo del \"síndrome de Daemonheim\". Esto tiene un paralelo con el síndrome de Estocolmo de la vida real, donde el rehén desarrolla un vínculo psicológico con el captor durante el cautiverio.",
    },
    ["The Black Marketeer"] = {
        ["When you have less to do, we should talk business."] = "Cuando tengas menos que hacer, deberíamos hablar de negocios.",
        ["** **Why hello, Portmaster."] = "** **Hola, Portmaster.",
        ["Select an Option"] = "Seleccione una opción",
        ["I'd like to purchase some goods."] = "Me gustaría comprar algunos productos.",
        ["Certainly, Portmaster. No questions asked."] = "Por supuesto, Capitán de Puerto. No se hicieron preguntas.",
        ["*Black Market opens up*"] = "*Se abre el mercado negro*",
        ["Tell me about your stock."] = "Cuéntame sobre tus acciones.",
        ["I get a variety of goods from the Wushanko Isles. Goods that have fallen off the back of ships, that others have misplaced, that my contacts have picked up. I can't guarantee what goods I'll bring here each day. These goods move quickly, my prices are so reasonable. I'll bring you bamboo from the Arc region and Skull is overflowing with gunpowder. I'll source mountains of slate from the Hook region and the Scythe is ripe with cherrywood. I'll sell you jade enough to build a palace, directly from the Bowl. My contacts will even travel to the Pincers to bring you back steel that does not rust. But only if you can pay the price."] = "Recibo una variedad de productos de las islas Wushanko. Bienes que se han caído de la parte trasera de los barcos, que otros han extraviado, que mis contactos han recogido. No puedo garantizar qué productos traeré aquí cada día. Estos productos se mueven rápidamente, mis precios son muy razonables. Te traeré bambú de la región de Arc y Skull está repleto de pólvora. Conseguiré montañas de pizarra de la región de Hook y la Scythe está llena de madera de cerezo. Te venderé suficiente jade para construir un palacio, directamente desde el Cuenco. Mis contactos incluso viajarán a Las Pinzas para traeros acero que no se oxida. Pero sólo si puedes pagar el precio.",
        ["What's your price?"] = "¿Cuál es tu precio?",
        ["Western coin. I only accept western coin."] = "Moneda occidental. Sólo acepto monedas occidentales.",
        ["Why do you do what you do?"] = "¿Por qué haces lo que haces?",
        ["Well, if we are to work together, portmaster, I should secure your trust. Despite the trade I practise, I'm not a dishonest man. The truth is almost always preferable to a lie. I once lived in New Heritage - one of the largest isles in the Pincer region. I was a well-off merchant. I had a wife and two little girls. Slaved rarely ventured to the Pincer Region. The khans there are powerful - they have vast armies, soothsayers and ships. The exiles and eastern slavers know better than to try their luck. But a ship of slavers did arrive. Slavers from the west - who knows why they were so far out to sea, when few westerners even dared travel past the Arc. I watched them pull my wife and my girls onto their ship. I could do nothing. I was just a merchant, and definitely no fighter. Months passed. I was sure they were dead. I was...preparing...to join them. Then, I got a letter. A letter from their kidnappers. They were demanding coin in exchange for my family. Western coin. A lot of western coin. I shut up shop immediately and set sail for the west with all my goods. I travelled only with my captain: Lily. The oceans only know how we made the journey. I sold everything I had to raise the coin and left the money where they wanted it. A few days later, I got another letter...asking for more coin. And so this pattern has gone on for years. I pay their ransom and they send another letter, but what else can I do?"] = "Bueno, si vamos a trabajar juntos, capitán de puerto, debo asegurarme de su confianza. A pesar del oficio que ejerzo, no soy un hombre deshonesto. Casi siempre es preferible la verdad a la mentira. Una vez viví en New Heritage, una de las islas más grandes de la región de Pincer. Yo era un comerciante acomodado. Tenía esposa y dos niñas. Los esclavos rara vez se aventuraban a la región de Pincer. Los khans allí son poderosos: tienen vastos ejércitos, adivinos y barcos. Los exiliados y los esclavistas orientales saben que no deben probar suerte. Pero sí llegó un barco de traficantes de esclavos. Esclavistas del oeste... quién sabe por qué estaban tan lejos del mar, cuando pocos occidentales se atrevían siquiera a cruzar el Arco. Los vi subir a mi esposa y a mis hijas a su barco. No pude hacer nada. Yo era sólo un comerciante y definitivamente no un luchador. Pasaron los meses. Estaba seguro de que estaban muertos. Estaba... preparándome... para unirme a ellos. Entonces recibí una carta. Una carta de sus secuestradores. Exigían monedas a cambio de mi familia. Moneda occidental. Mucha moneda occidental. Cerré la tienda inmediatamente y zarpé hacia el oeste con todas mis mercancías. Viajé sólo con mi capitana: Lily. Sólo los océanos saben cómo hicimos el viaje. Vendí todo lo que tenía para recaudar la moneda y dejé el dinero donde lo querían. Unos días después, recibí otra carta... pidiendo más monedas. Y este patrón ha continuado durante años. Pago su rescate y me envían otra carta, pero ¿qué más puedo hacer?",
        ["Have you considered that your family might be..."] = "¿Has considerado que tu familia podría ser...?",
        ["But how could I? Considering that would mean losing everything."] = "¿Pero cómo podría? Considerar eso significaría perderlo todo.",
        ["Who brings you these goods?"] = "¿Quién te trae estos productos?",
        ["I work with a group of exiles: the Blazing Lantern clan. They are sailors who operate in the Wushanko Islands but who have rejected the rule of khans. A westerner might call them pirates, but that would be a generalisation. The khans who rule the Wushanko Islands are chosen, mostly, for their skills on a ship. Some men an women don't believe that's a just enough reason to rule. If your island is ruled by a cruel khan, the others won't intervene. They'll let him operate as he wishes, unless he engages in open warfare. Only then will the other khans step in...and then the ocean boils."] = "Trabajo con un grupo de exiliados: el clan Blazing Lantern. Son marineros que operan en las islas Wushanko pero que han rechazado el gobierno de los khans. Un occidental podría llamarlos piratas, pero eso sería una generalización. Los khans que gobiernan las islas Wushanko son elegidos, principalmente, por sus habilidades a bordo de un barco. Algunos hombres y mujeres no creen que esa sea una razón suficiente para gobernar. Si tu isla está gobernada por un khan cruel, los demás no intervendrán. Le dejarán actuar como quiera, a menos que se involucre en una guerra abierta. Sólo entonces intervendrán los otros khans... y entonces el océano hierve.",
        ["I'd better be going, things to do."] = "Será mejor que me vaya, cosas que hacer.",
        ["We'll talk soon, Portmaster."] = "Hablaremos pronto, Capitán de Puerto.",
        ["*Before completing the tutorial:*{{anchor|tutorial-view-goods}}"] = "*Antes de completar el tutorial:*{{anchor|tutorial-view-goods}}",
        ["The Black Marketeer has no goods for sale at the moment. Check back once you have completed the Port tutorial."] = "The Black Marketeer no tiene productos a la venta en este momento. Vuelva a consultar una vez que haya completado el tutorial de Puerto.",
        ["*Before completing the tutorial:*"] = "*Antes de completar el tutorial:*",
    },
    ["The Chef"] = {
        ["Woah! Don't sneak up on me like that!"] = "¡Guau! ¡No me acerques así!",
        ["How are you doing, Carlos?"] = "¿Cómo estás, Carlos?",
        ["*Before Perfect Flavour*"] = "*Antes del Sabor Perfecto*",
        ["I would go and explore more of the port, but I am already in my apron."] = "Iría a explorar más el puerto, pero ya estoy en mi delantal.",
        ["*After Perfect Flavour*"] = "*Después del sabor perfecto*",
        ["I wonder if someone around here will let me use them as a taste tester. I'm almost certain I won't poison them."] = "Me pregunto si alguien por aquí me dejará usarlos como probador de sabor. Estoy casi seguro de que no los envenenaré.",
        ["*After Toxins*"] = "*Después de las toxinas*",
        ["Barrel here, barrel there. I'd better label them. Don't want to cook the wrong stuff!"] = "Barril aquí, barril allá. Será mejor que los etiquete. ¡No quieras cocinar lo incorrecto!",
        ["*After Boiling Over*"] = "*Después de hervir*",
        ["I'm glad the villagers are okay. I would hate to have made them all ill. Still a bit of a mystery, though!"] = "Me alegro de que los aldeanos estén bien. Odiaría haberlos enfermado a todos. ¡Sin embargo, todavía es un poco misterioso!",
        ["*After To The Ship*"] = "*Después del barco*",
        ["Just the thought of what happened to those poor hunters...  Sends shivers down my spine!"] = "Sólo pensar en lo que les pasó a esos pobres cazadores... ¡Me provoca escalofríos!",
        ["*After Barrels of Mystery*"] = "*Después de Barriles de Misterio*",
        ["I need to master the spoon-lasso-trap. It worked flawlessly against that cactus I tested it on!"] = "Necesito dominar la trampa del lazo-cuchara. ¡Funcionó perfectamente contra ese cactus en el que lo probé!",
        ["*After Reinforcement*"] = "*Después del refuerzo*",
        ["First I was determined to cook the creature, but I changed my mind after seeing that goop!"] = "Primero estaba decidido a cocinar la criatura, ¡pero cambié de opinión después de ver esa sustancia pegajosa!",
        ["*After Once More Into the Breach*"] = "*Después de una vez más en la brecha*",
        ["Next time I am out at the mine, I bet I can find some nice fungi to cook up. I tried some...didn't make me feel funny or anything."] = "La próxima vez que vaya a la mina, apuesto a que puedo encontrar unos buenos hongos para cocinar. Probé algunos... no me hizo sentir raro ni nada por el estilo.",
        ["*After Recipe Number 132: Fresh Idea*"] = "*Después de la receta número 132: idea nueva*",
        ["I wonder if I can cook those rocks. If the creatures can eat them, why can't I?"] = "Me pregunto si puedo cocinar esas piedras. Si las criaturas pueden comerlos, ¿por qué yo no?",
        ["I could use your help."] = "Me vendría bien tu ayuda.",
        ["You need something sliced, diced and cooked? I'm on my way!"] = "¿Necesitas algo cortado en rodajas, en cubitos y cocido? ¡Estoy en camino!",
        ["*Voyage screen opens*"] = "*Se abre la pantalla de viaje*",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["*Without the Biologist unlocked*"] = "*Sin the Biologist desbloqueado*",
        ["I like to work with people who study nature and can point me at the tastiest stuff."] = "Me gusta trabajar con personas que estudian la naturaleza y pueden indicarme las cosas más sabrosas.",
        ["Unlock the Biologist (90 Herblore required) to unlock additional joint voyages."] = "Desbloquea the Biologist (se requieren 90 Herblore) para desbloquear viajes conjuntos adicionales.",
        ["*With the Biologist unlocked and not present*"] = "*Con the Biologist desbloqueado y no presente*",
        ["I need to absorb information about herbs and such. There's a biologist around here who might just have what I need."] = "Necesito absorber información sobre hierbas y cosas así. Hay un biólogo por aquí que podría tener lo que necesito.",
        ["If the Biologist and Chef are in port at the same time, additional joint voyages will be made available."] = "Si the Biologist y Chef están en el puerto al mismo tiempo, estarán disponibles viajes conjuntos adicionales.",
        ["*With the Biologist unlocked and present*"] = "*Con the Biologist desbloqueado y presente*",
        ["*missing*"] = "*desaparecido*",
        ["Do you like cooking, Carlos?"] = "¿Te gusta cocinar, Carlos?",
        ["I love to cook. You get to work with a big pot and stir things in without being accused of witchcraft and cursing people!"] = "Me encanta cocinar. ¡Puedes trabajar con una olla grande y revolver cosas sin que te acusen de brujería ni de maldecir a la gente!",
        ["I have to go."] = "Me tengo que ir.",
        ["Oh, I'll see you around port then. Farewell!"] = "Oh, entonces te veré en el puerto. ¡Despedida!",
        ["[View previous cutscenes]"] = "[Ver escenas anteriores]",
        ["*replay voyages below*"] = "*reproduce viajes a continuación*",
        ["Do you deal in spices? I could do with something with a bit more POW!"] = "¿Tratas con especias? ¡Me vendría bien algo con un poco más de POW!",
        ["Thanks for the offer, but my alcohol goes in the sauce for that extra kick."] = "Gracias por la oferta, pero mi alcohol va en la salsa para darle un toque extra.",
        ["Greetings adventurer! Carlos. Carlos Napp - that's my name - cooking's my game! Haha!"] = "¡Saludos aventurero! Carlos. Carlos Napp, ese es mi nombre, ¡cocinar es mi juego! ¡Ja ja!",
        ["What are you doing here?"] = "¿Qué haces aquí?",
        ["I've recently been exploring the Eastern lands - very easterny, I have to say..."] = "Recientemente estuve explorando las tierras orientales, muy orientales, debo decir...",
        ["Right..."] = "Cierto...",
        ["Rumours had it of a fantastically large lobster around these parts. I naturally rushed to see what the fuss was about."] = "Se rumoreaba que había una langosta increíblemente grande por estos lares. Naturalmente, me apresuré a ver a qué se debía tanto alboroto.",
        ["Oh, you mean Clawdia?"] = "Oh, ¿te refieres a Clawdia?",
        ["Yes, Clawdia was it's name! A friend of mine called Shuma came along. He's a great whaler! Wait, no... his name's Hubbub.. he's hunting something called Shuma. A whale. Wait, is that right? Come on Carlos, keep it together!"] = "Sí, ¡Clawdia era su nombre! Vino un amigo mío llamado Shuma. ¡Es un gran ballenero! Espera, no... su nombre es Hubbub... está cazando algo llamado Shuma. Una ballena. Espera, ¿es así? ¡Vamos Carlos, manten la calma!",
        ["What did Hubbub find here?"] = "¿Qué encontró Hubbub aquí?",
        ["You know Hubbub? No way - me too! He just left after helping me find a claw of a giant lobster called Clawdia! I cooked it up right away. Care to try a piece?"] = "¿Conoces Hubbub? De ninguna manera, ¡yo también! ¡Se fue después de ayudarme a encontrar una pinza de langosta gigante llamada Clawdia! Lo cociné de inmediato. ¿Te importaría probar una pieza?",
        ["Sure, I'll try anything once."] = "Claro, intentaré cualquier cosa una vez.",
        ["There you go, enjoy!"] = "Ahí lo tienes, ¡disfrútalo!",
        ["How was the lobster?"] = "¿Cómo estuvo la langosta?",
        ["It was erm... delicious."] = "Estaba mmm... delicioso.",
        ["Well, I think it needed more heat!"] = "Bueno, ¡creo que necesitaba más calor!",
    },
    ["The Convict"] = {
        ["A pleasure, as always."] = "Un placer, como siempre.",
        ["Select an option"] = "Seleccione una opción",
        ["And how are you?"] = "¿Y tú cómo estás?",
        ["*(Before A Place Called Respite:)*"] = "*(Antes de un lugar llamado respiro:)*",
        ["I'm good. I'm just keeping my ear to the ground. Hope to hear of a safe place where I can lie low."] = "Estoy bien. Sólo mantengo mi oído en el suelo. Espero oír hablar de un lugar seguro donde pueda pasar desapercibido.",
        ["*(After A Place Called Respite:)*"] = "*(Después de un lugar llamado respiro:)*",
        ["Don't look at me like that."] = "No me mires así.",
        ["You've been lying to me, 'Marcus'."] = "Me has estado mintiendo, 'Marcus'.",
        ["I can scarcely forgive myself for doing so, we must discuss it at length, soon - when we're both less busy."] = "No puedo perdonarme por hacerlo, debemos discutirlo extensamente pronto, cuando ambos estemos menos ocupados.",
        ["*(After Return Mail:)*"] = "*(Después del correo de devolución:)*",
        ["Oh, please don't take my blackmailing to heart. Let's put this White Knight business behind us. They're dead now, that's all that matters. We're still friends. I'm... useful to you."] = "Oh, por favor, no te tomes en serio mi chantaje. Dejemos atrás este asunto de los Caballeros Blancos. Ya están muertos, eso es lo único que importa. Todavía somos amigos. Soy... útil para ti.",
        ["*(After A Thief in the Night:)*"] = "*(Después de Un ladrón en la noche :)*",
        ["I've been thinking on a plan to help the sea orphans. I know that their khan is responsible for the kidnappings, but how to prove it? How can I expose him?"] = "He estado pensando en un plan para ayudar a los huérfanos del mar. Sé que su khan es el responsable de los secuestros, pero ¿cómo demostrarlo? ¿Cómo puedo exponerlo?",
        ["*(After Do Unto Others:)*"] = "*(Después de hacer a los demás:)*",
        ["Oh good, good. Everything is going just swimmingly in Hyu-Ji. We drink, dine, duel. The sea orphans are rather wonderful. I only come here to nurse my hangovers."] = "Oh, bien, bien. Todo va a las mil maravillas en Hyu-Ji. Bebemos, cenamos, nos batimos en duelo. Los huérfanos del mar son bastante maravillosos. Sólo vengo aquí para curar mis resacas.",
        ["*(After Hail To The Khan:)*"] = "*(Después de Saludo al Khan:)*",
        ["I know we've had our differences, what with all the blackmail and lying, but I don't hold it against you."] = "Sé que hemos tenido nuestras diferencias, con todo el chantaje y las mentiras, pero no te lo reprocho.",
        ["How good of you."] = "Qué bien de tu parte.",
        ["Life is good. I'm a khan, which grants me power and status, and I can get my more subversive kicks from working with you."] = "La vida es buena. Soy un khan, lo que me otorga poder y estatus, y puedo disfrutar de momentos más subversivos trabajando contigo.",
        ["*(After Hull Down On The Horizon:)*"] = "*(Después de Hull Down On The Horizon:)*",
        ["I know they're our enemies but I must admire their plan."] = "Sé que son nuestros enemigos, pero debo admirar su plan.",
        ["The Purists joining forces with pirates and soothsayers... Why, it's a potent force."] = "Los puristas uniendo fuerzas con piratas y adivinos... Vaya, es una fuerza potente.",
        ["I wouldn't admit it to the others but I'm not convinced Hyu-Ji could survive such an attack."] = "No lo admitiría ante los demás, pero no estoy convencido de que Hyu-Ji pueda sobrevivir a tal ataque.",
        ["*(After A Concerted Effort:)*"] = "*(Después de un esfuerzo concertado:)*",
        ["Even with Bethan's chemicals and Tomlin's... attributes, we're going to be hard-pressed to win the fight against the Purists and Co."] = "Incluso con los químicos de Bethan y los atributos de Tomlin... vamos a tener dificultades para ganar la lucha contra los puristas y compañía.",
        ["I'm almost... nervous."] = "Estoy casi... nervioso.",
        ["*(After The Defiance of Hyu-Ji:)*"] = "*(Después del desafío de Hyu-Ji :)*",
        ["Oh, life is very sweet. My advisors are practically running Hyu-Ji!"] = "Oh, la vida es muy dulce. ¡Mis asesores prácticamente están ejecutando Hyu-Ji!",
        ["Apart from the occasional portrait opportunity and the odd signing of legal documents, I live a rather stress-free life, thank Saradomin."] = "Aparte de la oportunidad ocasional de hacer retratos y la extraña firma de documentos legales, vivo una vida bastante libre de estrés, gracias a Saradomin.",
        ["Oh dear, it seems Tomlin is rubbing off on me. Well, thank whoever for our little escapades."] = "Dios mío, parece que Tomlin se me está contagiando. Bueno, gracias a quien sea por nuestras pequeñas escapadas.",
        ["Otherwise all this excess and decadence would get a trifle boring."] = "De lo contrario, todo este exceso y decadencia se volvería un poco aburrido.",
        ["I've got a job that needs doing, a job that requires your skills."] = "Tengo un trabajo que necesito hacer, un trabajo que requiere tus habilidades.",
        ["My skills? Oh, it must be a devious job - very devious."] = "¿Mis habilidades? Oh, debe ser un trabajo tortuoso... muy tortuoso.",
        ["*(Voyage list interface opens.)*"] = "*(Se abre la interfaz de lista de viajes.)*",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["*(If The Assassin has not been unlocked:)*"] = "*(Si The Assassin no ha sido desbloqueado:)*",
        ["If you could find someone light on their feet, clever and fast, I'd consider working with them."] = "Si pudieras encontrar a alguien ligero, inteligente y rápido, consideraría trabajar con él.",
        ["Unlock the Assassin (90 Slayer required) to unlock additional joint voyages."] = "Desbloquea the Assassin (se requieren 90 Slayer) para desbloquear viajes conjuntos adicionales.",
        ["*(If The Assassin has been unlocked but is not present:)*"] = "*(Si The Assassin ha sido desbloqueado pero no está presente:)*",
        ["Well I normally work alone, but that assassin who drops in from time to time would certainly complement my skill set."] = "Bueno, normalmente trabajo solo, pero ese asesino que aparece de vez en cuando ciertamente complementaría mis habilidades.",
        ["If both the Assassin and Convict are in port at the same time, additional joint voyages will be made available."] = "Si tanto the Assassin como Convict están en puerto al mismo tiempo, estarán disponibles viajes conjuntos adicionales.",
        ["*(If The Assassin has been unlocked and she is present:)*"] = "*(Si The Assassin ha sido desbloqueado y ella está presente:)*",
        ["Oh, I'd be happy to worth with Ling. It's always nice to have an assassin lurking in the rafters, just in case something goes wrong."] = "Oh, me encantaría poder hablar con Ling. Siempre es bueno tener un asesino acechando entre las vigas, en caso de que algo salga mal.",
        ["Sounds like I'll end up doing all the work, then. Very well, let's do it."] = "Parece que entonces terminaré haciendo todo el trabajo. Muy bien, hagámoslo.",
        ["How's the life of an escaped convict?"] = "¿Cómo es la vida de un preso fugitivo?",
        ["Oh, we're all on the run from something. The lives that you and I live can't be so different. From what I've heard, you're possibly a better thief than I."] = "Oh, todos estamos huyendo de algo. Las vidas que vivimos tú y yo no pueden ser tan diferentes. Por lo que he oído, posiblemente seas mejor ladrón que yo.",
        ["[View Previous Cutscenes]"] = "[Ver escenas anteriores]",
        ["*(If the Convict was not the first adventurer unlocked by the player and the player has not completed any other voyages than \"Meet the Convict\":)*"] = "*(Si the Convict no fue el primer aventurero desbloqueado por el player y el player no ha completado ningún otro viaje además de \"Conoce a the Convict\":)*",
        ["Which story cutscene would you like to see?"] = "¿Qué escena de la historia te gustaría ver?",
        ["*(Each dialogue option is unlocked after successfully completing the relevant voyage:)*"] = "*(Cada opción de diálogo se desbloquea después de completar con éxito el viaje correspondiente :)*",
        ["*(If the Convict was not the first adventurer unlocked by the player:)*"] = "*(Si the Convict no fue el primer aventurero desbloqueado por el player:)*",
        ["Meet the Convict"] = "Conoce a the Convict",
        ["You're about to watch 'Meet the Convict'.{{anchor|meet-the-convict}}"] = "Estás a punto de ver 'Conoce a the Convict'.{{anchor|meet-the-convict}}",
        ["A Place Called Respite"] = "Un lugar llamado respiro",
        ["You're about to watch 'A Place Called Respite'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Un lugar llamado respiro'. ¿Quieres ver el principio o el final?",
        ["Beginning."] = "Comienzo.",
        ["End."] = "Fin.",
        ["Return Mail"] = "Devolución de correo",
        ["You're about to watch 'Return Mail'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Devolución de correo'. ¿Quieres ver el principio o el final?",
        ["A Thief in the Night"] = "Un ladrón en la noche",
        ["You're about to watch 'A Thief in the Night'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Un ladrón en la noche'. ¿Quieres ver el principio o el final?",
        ["More"] = "Más",
        ["Do Unto Others"] = "Hacer a los demás",
        ["You're about to watch 'Do Unto Others'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Hacer a los demás'. ¿Quieres ver el principio o el final?",
        ["Hail To The Khan"] = "Saludo al Khan",
        ["You're about to watch 'Hail To The Khan'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Hail To The Khan'. ¿Quieres ver el principio o el final?",
        ["Hull Down On The Horizon"] = "Casco abajo en el horizonte",
        ["You're about to watch 'Hull Down On The Horizon'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Hull Down On The Horizon'. ¿Quieres ver el principio o el final?",
        ["A Concerted Effort"] = "Un esfuerzo concertado",
        ["You're about to watch 'A Concerted Effort'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Un esfuerzo concertado'. ¿Quieres ver el principio o el final?",
        ["The Defiance of Hyu-Ji"] = "El desafío de Hyu-Ji",
        ["You're about to watch 'The Defiance of Hyu-Ji'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'El desafío de Hyu-Ji'. ¿Quieres ver el principio o el final?",
        ["Perhaps I'll have one later."] = "Quizás tenga uno más tarde.",
