        ["Hmmm, is it... [Name]?"] = "Hmmm, ¿es... [Name]?",
        ["*(If a wrong name was selected:)*"] = "*(Si se seleccionó un nombre incorrecto:)*",
        ["[Name]? Don't be ridiculous!"] = "[Name]? ¡No seas ridículo!",
        ["*(If the correct name was selected:)*"] = "*(Si se seleccionó el nombre correcto:)*",
        ["*(On first time:)*"] = "*(La primera vez :)*",
        ["Yes! Well done."] = "¡Sí! Bien hecho.",
        ["colour=#00ff00{{Colour|#ffffff|.}}}}"] = "color=#00ff00{{Colour|#ffffff|.}}}}",
        ["*(On subsequent times:)*"] = "*(En tiempos posteriores:)*",
        ["Amazing, you've guessed it again!"] = "¡Increíble, lo has adivinado otra vez!",
    },
    ["The Kendal"] = {
        ["*(Appears randomly at the start:)*"] = "*(Aparece aleatoriamente al principio:)*",
        ["That guy is so creepy..."] = "Ese tipo es tan espeluznante...",
        ["You mean Pete?"] = "¿Te refieres a Pete?",
        ["He hasn't stopped dancing since I got here, day or night. It's enough to ruin my appetite."] = "No ha dejado de bailar desde que llegué aquí, ni de día ni de noche. Es suficiente para arruinarme el apetito.",
