    ["The Lady of the Lake"] = {
        ["Good day to you, [sir/madam]."] = "Buenos días, [sir/madam].",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["Sir Kay said you'd reward me."] = "Sir Kay dijo que me recompensarías.",
        ["Indeed, I hear that you have earned his trust. You shall be rewarded handsomely!"] = "De hecho, he oído que te has ganado su confianza. ¡Serás recompensado generosamente!",
        ["[The Lady of the Lake reaches out and touches the blade Excalibur which seems to vibrate with new power.]"] = "[The Lady of the Lake extiende la mano y toca la espada Excalibur que parece vibrar con nuevo poder.]",
        ["What does that do then?"] = "¿Qué hace eso entonces?",
        ["The enhanced Excalibur is wielded in your left hand, not your right, and its blade is far more powerful."] = "La Excalibur mejorada se empuña con la mano izquierda, no con la derecha, y su espada es mucho más poderosa.",
        ["Thanks!"] = "¡Gracias!",
        ["Can you enchant Excalibur for me, please?"] = "¿Puedes encantar Excalibur por mí, por favor?",
        ["Who are you?"] = "¿Quién eres?",
        ["I am the Lady of the Lake."] = "Soy the Lady of the Lake.",
        ["I seek the sword Excalibur."] = "Busco la espada Excalibur.",
        ["I recall you have already proven yourself to be worthy of wielding it. I shall return it to you if you can prove yourself to still be worthy."] = "Recuerdo que ya has demostrado que eres digno de empuñarlo. Te lo devolveré si puedes demostrar que aún eres digno.",
        ["And how can I do that?"] = "¿Y cómo puedo hacer eso?",
        ["Why, by proving yourself to be above material goods."] = "Bueno, demostrando que estás por encima de los bienes materiales.",
        ["... And how can I do that?"] = "... ¿Y cómo puedo hacer eso?",
        ["500 coins ought to do it."] = "500 coins deberían ser suficientes.",
        ["Okay, here you go."] = "Bien, aquí tienes.",
        ["Thanks for the cash! I'm saving up for a new dress."] = "¡Gracias por el dinero! Estoy ahorrando para un vestido nuevo.",
        ["Which version of Excalibur would you like back?"] = "¿Qué versión de Excalibur te gustaría recuperar?",
        ["Excalibur - the original."] = "Excalibur - el original.",
        ["[The Lady of the Lake hands you Excalibur.]"] = "[The Lady of the Lake te entrega Excalibur.]",
        ["Enhanced Excalibur."] = "Excalibur mejorada.",
        ["[The Lady of the Lake hands you the enhanced version of Excalibur.]"] = "[The Lady of the Lake te entrega la versión mejorada de Excalibur.]",
        ["500 coins? No thanks!"] = "¿500 coins? ¡No, gracias!",
        ["Your materialistic attitude saddens me."] = "Tu actitud materialista me entristece.",
        ["Good day."] = "Buenos días.",
        ["You're going to drop it if I try to hand it to you while your inventory's full!"] = "¡Lo dejarás caer si intento entregártelo mientras tu inventario está lleno!",
        ["Pay 500 coins for Excalibur?"] = "¿Pagar 500 coins por Excalibur?",
        ["Buy Excalibur."] = "Compra Excalibur.",
        ["Cancel."] = "Cancelar.",
    },
    ["The Magister"] = {
        ["*Note: This line is not guaranteed each encounter*"] = "*Nota: Esta línea no está garantizada en cada encuentro*",
        ["*If the player is within melee-distance of the Magister:*"] = "*Si el player está dentro de una distancia cuerpo a cuerpo de the Magister:*",
        ["*If the player is outside of melee-distance of the Magister:*"] = "*Si el player está fuera de la distancia cuerpo a cuerpo de the Magister:*",
    },
    ["The Memory"] = {
        ["Oh! Hello, World Guardian."] = "¡Oh! Hola, Guardián Mundial.",
        ["Select an option"] = "Seleccione una opción",
        ["*(Before Qualia of Life:)*"] = "*(Antes de Qualia de Vida:)*",
        ["How are you today, [Aagi/Kami]?"] = "¿Cómo estás hoy, [Aagi/Kami]?",
        ["*(Before False Memories:)*"] = "*(Antes de los falsos recuerdos:)*",
        ["I'm settling in okay, thank you. I still don't feel completely safe, though."] = "Me estoy adaptando bien, gracias. Aunque todavía no me siento completamente seguro.",
        ["*(After False Memories:)*"] = "*(Después de falsos recuerdos :)*",
        ["I'm still having bad dreams about divination craters, but I do trust you. I'm just glad I don't sleepwalk."] = "Sigo teniendo pesadillas sobre cráteres de adivinación, pero confío en ti. Me alegro de no caminar sonámbulo.",
        ["*(After Qualia of Life:)*"] = "*(Después de Qualia de Vida :)*",
        ["How are you today, Kami?"] = "¿Cómo estás hoy, Kami?",
        ["I've been having dreams about Genma. He feels strong...I wish I were as strong as him."] = "He estado soñando con Genma. Se siente fuerte... Ojalá fuera tan fuerte como él.",
        ["Not that I even know what he looks like - my mind makes things up when I dream. He might not even be a he!"] = "Ni siquiera sé cómo es; mi mente toma decisiones cuando sueño. ¡Puede que ni siquiera sea un él!",
        ["*(After Go With the Flow:)*"] = "*(Después de Seguir la corriente:)*",
        ["I had a dream about Kakashi chasing me... Well, it was a nightmare really. But I know you won't let him take me."] = "Soñé que Kakashi me perseguía... Bueno, realmente fue una pesadilla. Pero sé que no dejarás que me lleve.",
        ["*(After Mind over Matter:)*"] = "*(Después de la mente sobre la materia:)*",
        ["I had another dream about Kakashi, but this time, HE was being chased by Bandos! Ha!"] = "Tuve otro sueño sobre Kakashi, pero esta vez, ¡ÉL estaba siendo perseguido por Bandos! ¡Ja!",
        ["*(After Remember the Dead:)*"] = "*(Después de Recuerda a los muertos:)*",
        ["Now, when I sleep, I can sense the sea creatures. They talk to me. I don't think they're dreams."] = "Ahora, cuando duermo, puedo sentir las criaturas marinas. Me hablan. No creo que sean sueños.",
        ["*(After Lament of the Sea:)*"] = "*(Después del Lamento del Mar :)*",
        ["The sea creatures are crying out, mourning those that Kakashi has murdered. They're so sad - we have to stop him!"] = "Las criaturas marinas están llorando, llorando a aquellos que Kakashi ha asesinado. ¡Están tan tristes que tenemos que detenerlo!",
        ["*(After Gu: Masters of the Magic Mountain:)*"] = "*(Después de Gu: Maestros de la montaña Magic :)*",
        ["I'm scared for you, World Guardian. I don't know if Kakashi's weapon would even hurt you...but I don't want you to die."] = "Tengo miedo por ti, Guardián Mundial. No sé si el arma de Kakashi te haría daño... pero no quiero que mueras.",
        ["*(After Guardians of the World:)*"] = "*(Después de Guardianes del Mundo:)*",
        ["Kami-shima is so beautiful; I hope the island will let you visit some day. I'll show you my pet shi cub - she's so cute! I named her Fraji, in honour of Aagi's mother."] = "Kami-shima es tan hermosa; Espero que la isla te permita visitarla algún día. Te mostraré mi cachorro shi mascota: ¡es tan linda! La llamé Fraji, en honor a la madre de Aagi.",
        ["*(If The Memory has clue voyages available:)*"] = "*(Si The Memory tiene viajes de pistas disponibles:)*",
        ["About your voyages..."] = "Sobre tus viajes...",
        ["I trust you. If you think there's something I can help with, I'll do it!"] = "Confío en ti. Si crees que hay algo en lo que puedo ayudar, ¡lo haré!",
        ["About clue voyages..."] = "Acerca de los viajes de pistas...",
        ["View all voyages..."] = "Ver todos los viajes...",
        ["*(Voyage list interface opens.)*"] = "*(Se abre la interfaz de lista de viajes.)*",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["*(If The Occultist has not been unlocked:)*"] = "*(Si The Occultist no ha sido desbloqueado:)*",
        ["I'd like to learn more about runecrafting. I think it might make me closer to my dad."] = "Me gustaría aprender más sobre la creación de runas. Creo que podría acercarme más a mi papá.",
        ["Unlock the Occultist (90 Runecrafting required) to unlock additional joint voyages."] = "Desbloquea the Occultist (se requieren 90 Runecrafting) para desbloquear viajes conjuntos adicionales.",
        ["*(If The Occultist has been unlocked but is not present:)*"] = "*(Si The Occultist ha sido desbloqueado pero no está presente:)*",
        ["I'd like to learn more about runecrafting. I think it might make me closer to my dad. There's that occultist lady..."] = "Me gustaría aprender más sobre la creación de runas. Creo que podría acercarme más a mi papá. Está esa dama ocultista...",
        ["If both the Memory and Occultist are in port at the same time, additional joint voyages will be made available."] = "Si tanto the Memory como Occultist están en el puerto al mismo tiempo, estarán disponibles viajes conjuntos adicionales.",
        ["*(If The Occultist has been unlocked and she is present:)*"] = "*(Si The Occultist ha sido desbloqueado y ella está presente:)*",
        ["Um, I'm not sure she's a good role model for you, [Aagi/Kami]..."] = "Um, no estoy seguro de que ella sea un buen modelo a seguir para ti, [Aagi/Kami]...",
        ["I'm not a child. I'll be okay with her, honest!"] = "No soy un niño. ¡Estaré bien con ella, sinceramente!",
        ["Have any memories to share?"] = "¿Tienes algún recuerdo para compartir?",
        ["*(Before Remember the Dead:)*"] = "*(Antes de recordar a los muertos:)*",
        ["Maybe...but none I want to share just yet."] = "Tal vez... pero ninguno que quiera compartir todavía.",
        ["Oh! Maybe... I don't really know what I know, until I know it, you know?"] = "¡Oh! Quizás... realmente no sé lo que sé, hasta que lo sé, ¿sabes?",
        ["I don't follow..."] = "No te sigo...",
        ["I'm literally made of memories, but you have to ask me something before I know if I know the answer or not, you see? So ask me!"] = "Estoy literalmente hecho de recuerdos, pero tienes que preguntarme algo antes de saber si sé la respuesta o no, ¿ves? ¡Entonces pregúntame!",
        ["What would you like to ask Kami?"] = "¿Qué te gustaría preguntarle a Kami?",
        ["Do you know what you are?"] = "¿Sabes lo que eres?",
        ["Technically, I'm Guthix's manifested memories of his daughter Aagi... ...but I think I'm really an entity created by the planet's Anima Mundi. When I was formed, that's all I was, but now I've become my own person, with my own experiences and memories, and that's made me sort of...more 'real' somehow. I still don't quite understand that part. A lot of my emotions are really how Guthix felt, and it's sometimes difficult to separate out my own feelings. I get sad a lot even when I've no reason to be...but then I just remember my experiences in Wushanko and with you and I'm happy again."] = "Técnicamente, soy los recuerdos manifestados de Guthix sobre su hija Aagi... ...pero creo que en realidad soy una entidad creada por el Anima Mundi del planeta. Cuando me formé, eso era todo lo que era, pero ahora me he convertido en mi propia persona, con mis propias experiencias y recuerdos, y eso me ha hecho de alguna manera... más \"real\" de alguna manera. Todavía no entiendo bien esa parte. Muchas de mis emociones son realmente como se sentía Guthix y, a veces, es difícil separar mis propios sentimientos. Me pongo triste mucho incluso cuando no tengo motivos para estarlo... pero luego solo recuerdo mis experiencias en Wushanko y contigo y soy feliz de nuevo.",
        ["What do you remember of Aagi?"] = "¿Qué recuerdas de Aagi?",
        ["It was just her and Guthix most of the time - they lost her mum when Aagi was quite young. Aagi has very few memories of her mum, but I can see a lot of Guthix's memories of his wife. When I feel Guthix's grief, I try to remember how happy Aagi was - it helps. Oh, and Aagi really did love butterflies. But me - Kami - I much prefer birds!"] = "Eran solo ella y Guthix la mayor parte del tiempo; perdieron a su madre cuando Aagi era muy joven. Aagi tiene muy pocos recuerdos de su madre, pero puedo ver muchos de los recuerdos que Guthix tiene de su esposa. Cuando siento el dolor de Guthix, trato de recordar lo feliz que estaba Aagi; eso ayuda. Ah, y a Aagi realmente le encantaban las mariposas. Pero yo, Kami, ¡prefiero los pájaros!",
        ["What do you remember of Guthix?"] = "¿Qué recuerdas de Guthix?",
        ["Well, I'm mostly memories of Guthix's daughter, so I sort of just remember him as my dad, and how he was as a father. He raised me mostly by himself, and he was a great dad! I loved him very much and...I miss him. But then I also have some of Guthix's other memories, so I know how sad he was. Lonely too. And here's the strangest part - I also kind of remember making you the World Guardian. That's weird, right? Those memories were how I knew to look for you, that I could trust you to help me."] = "Bueno, en su mayoría son recuerdos de la hija de Guthix, así que simplemente lo recuerdo como mi padre y cómo era como padre. ¡Me crió solo y fue un gran padre! Lo amaba mucho y... lo extraño. Pero también tengo otros recuerdos de Guthix, así que sé lo triste que estaba. Solitario también. Y aquí está la parte más extraña: también recuerdo haberte convertido en el Guardián del Mundo. Eso es raro, ¿verdad? Esos recuerdos fueron como supe buscarte, que podía confiar en ti para que me ayudaras.",
        ["Do you know what Divination is?"] = "¿Sabes qué es Divination?",
        ["Hey, I know as much as you do. In fact, you probably know more! I'm just happy you didn't harvest my energy and throw me in a crater, or transmute me into something else! I think part of it is returning some of the energy that Guthix used back to the world - sort of healing it a bit. But it's also energy that can change things, and become things...things like me, or the sea creatures!"] = "Oye, sé tanto como tú. De hecho, ¡probablemente sepas más! ¡Estoy feliz de que no hayas cosechado mi energía y me hayas arrojado a un cráter, o me hayas transmutado en otra cosa! Creo que parte de esto es devolver al mundo parte de la energía que Guthix usó, como curarlo un poco. Pero también es energía que puede cambiar cosas y convertirse en cosas... ¡cosas como yo o las criaturas marinas!",
        ["I have so many questions! But..."] = "¡Tengo tantas preguntas! Pero...",
        ["I know...but I can't answer EVERYTHING! That'd be cheating! But I don't know why he made you World Guardian. I don't know much about him after he left Naragun. I don't know ANYTHING about Seren other than her name...and that she's really pretty! And I DEFINITELY don't know the secrets of the universe! If I did, I'd tell you - honest!"] = "Lo sé... ¡pero no puedo responder TODO! ¡Eso sería hacer trampa! Pero no sé por qué te nombró Guardián Mundial. No sé mucho sobre él después de que dejó Naragun. No sé NADA sobre Seren más que su nombre... ¡y que es realmente bonita! ¡Y DEFINITIVAMENTE no conozco los secretos del universo! Si lo hiciera, te lo diría: ¡honesto!",
        ["[View previous cutscenes]"] = "[Ver escenas anteriores]",
        ["*(If the Memory was not the first adventurer unlocked by the player and the player has not completed any other voyages than \"Meet the Memory\":)*"] = "*(Si the Memory no fue el primer aventurero desbloqueado por el player y el player no ha completado ningún otro viaje además de \"Conoce a the Memory\":)*",
        ["Which story cutscene would you like to see?"] = "¿Qué escena de la historia te gustaría ver?",
        ["*(Each dialogue option is unlocked after successfully completing the relevant voyage:)*"] = "*(Cada opción de diálogo se desbloquea después de completar con éxito el viaje correspondiente :)*",
        ["*(If the Memory was not the first adventurer unlocked by the player:)*"] = "*(Si the Memory no fue el primer aventurero desbloqueado por el player:)*",
        ["Meet the Memory"] = "Conoce a the Memory",
        ["You're about to watch 'Meet the Memory'.{{anchor|meet-the-memory}}"] = "Estás a punto de ver 'Conoce a the Memory'.{{anchor|meet-the-memory}}",
        ["False Memories"] = "falsos recuerdos",
        ["You're about to watch 'False Memories'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Falsos Recuerdos'. ¿Quieres ver el principio o el final?",
        ["Beginning."] = "Comienzo.",
        ["End."] = "Fin.",
        ["Qualia of Life"] = "Qualia de vida",
        ["You're about to watch 'Qualia of Life'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Qualia of Life'. ¿Quieres ver el principio o el final?",
        ["Go With the Flow"] = "Ir con la corriente",
        ["You're about to watch 'Go With the Flow'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Go With the Flow'. ¿Quieres ver el principio o el final?",
        ["More"] = "Más",
        ["Mind over Matter"] = "Mente sobre materia",
        ["You're about to watch 'Mind over Matter'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'La mente sobre la materia'. ¿Quieres ver el principio o el final?",
        ["Remember the Dead"] = "recuerda a los muertos",
        ["You're about to watch 'Remember the Dead'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Recuerda a los muertos'. ¿Quieres ver el principio o el final?",
        ["Lament of the Sea"] = "Lamento del mar",
        ["You're about to watch 'Lament of the Sea'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Lamento del Mar'. ¿Quieres ver el principio o el final?",
        ["Gu: Masters of the Magic Mountain"] = "Gu: Maestros de la montaña Magic",
        ["You're about to watch 'Gu: Masters of the Magic Mountain'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Gu: Maestros de la montaña Magic'. ¿Quieres ver el principio o el final?",
        ["Guardians of the World"] = "Guardianes del mundo",
        ["You're about to watch 'Guardians of the World'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Guardianes del Mundo'. ¿Quieres ver el principio o el final?",
        ["*(Dialogue from the \"Clue focus\" option on The Whaler. When one of the islands is successfully searched, it disappears from the dialogue options.)*"] = "*(Diálogo desde la opción \"Enfoque de pista\" en The Whaler. Cuando una de las islas se busca con éxito, desaparece de las opciones de diálogo).*",
        ["Aagi is exploring The Arc to jog her memory about...something she can't quite remember."] = "Aagi está explorando The Arc para refrescar su memoria sobre... algo que no puede recordar del todo.",
        ["The next island Aagi is planning to search is: [Island picked]"] = "La próxima isla que Aagi planea buscar es: [Island picked]",
        ["*In the first part of clues*"] = "*En la primera parte de pistas*",
        ["Suggest an island to search?"] = "¿Sugerir una isla para buscar?",
        ["Goshima"] = "goshima",
        ["Leave them to it!"] = "¡Déjalos ahí!",
        ["*On first success*"] = "*En el primer éxito*",
        ["The memory has recalled one piece of memory from her travels, the existance of the Island of Regret."] = "The memory ha recordado un recuerdo de sus viajes, la existencia de la Isla del Pesar.",
        ["[The Memory did not find what she was looking for at the island she visited.]"] = "[The Memory no encontró lo que buscaba en la isla que visitó.]",
        ["Kami has rediscovered The Island of Regret, and will offer to take your captains there!"] = "¡Kami ha redescubierto la Isla del Pesar y se ofrecerá a llevar a tus capitanes allí!",
        ["Um, I think I might be too young for beer. <sub>Unknown how triggered; presumably before Qualia of Life</sub>"] = "Um, creo que quizás sea demasiado joven para la cerveza. <sub>Se desconoce cómo se activó; presumiblemente antes de Qualia de Life</sub>",
        ["Eww, no thanks. Beer is gross. <sub>Unknown how triggered; presumably after Qualia of Life</sub>"] = "Vaya, no gracias. La cerveza es asquerosa. <sub>Se desconoce cómo se activó; presumiblemente después de Qualia de Life</sub>",
        ["Oh! No, thank you."] = "¡Oh! No, gracias.",
    },
    ["The Mighty Zoltan"] = {
        ["*(If the Zoltan pet is following you:)*"] = "*(Si la mascota Zoltan te sigue:)*",
        ["I remember when I used to be like your pet; happy and carefree."] = "Recuerdo cuando solía ser como tu mascota; feliz y despreocupada.",
        ["Actually, wait, no I don't."] = "En realidad, espera, no, no lo hago.",
        ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
        ["What does this machine do?"] = "¿Qué hace esta máquina?",
        ["Do not address The Mighty Zoltan as a machine!"] = "¡No trates a The Mighty Zoltan como una máquina!",
        ["What should I call you then?"] = "¿Cómo debería llamarte entonces?",
        ["The Mighty Zoltan works well, I find."] = "Creo que The Mighty Zoltan funciona bien.",
        ["Ok, Mighty Zoltan, what do you do?"] = "Ok, Poderoso Zoltan, ¿qué haces?",
        ["I can tell your fortune!"] = "¡Puedo adivinar tu fortuna!",
        ["*(One of the following occurs, then continues below:)*"] = "*(Ocurre uno de los siguientes y luego continúa a continuación:)*",
        ["What, so I can find out if I'm destined to be happy?"] = "¿Qué? ¿Para saber si estoy destinado a ser feliz?",
        ["What, so I can find out if I'm destined to be powerful?"] = "¿Qué? ¿Para saber si estoy destinado a ser poderoso?",
        ["What, so I can find out if I'm destined to be rich?"] = "¿Qué? ¿Para saber si estoy destinado a ser rico?",
        ["What, so I can find out if I'm destined to be the ruler of all?"] = "¿Qué, para poder saber si estoy destinado a ser el gobernante de todo?",
        ["What, so I can find out if I'm destined to find love?"] = "¿Qué, para poder saber si estoy destinado a encontrar el amor?",
        ["Not really."] = "Realmente no.",
        ["But that's a fortune, right?"] = "Pero eso es una fortuna, ¿verdad?",
        ["Well, yes, I did used to give out fortunes like that but something happened."] = "Bueno, sí, solía repartir fortunas así pero algo pasó.",
        ["Oh?"] = "¿Ah?",
        ["They all come out quite sad now. I'm not sure what caused it. The longer I am here, the worse they seem to get."] = "Todos salen bastante tristes ahora. No estoy seguro de qué lo causó. Cuanto más tiempo estoy aquí, peor parecen ponerse.",
        ["But the people who get the fortunes seem to be happy with the Divination reward that goes with it, so they don't seem to mind too much."] = "Pero las personas que obtienen las fortunas parecen estar contentas con la recompensa Divination que las acompaña, por lo que no parece importarles demasiado.",
        ["Doesn't it bring you down, though?"] = "¿No te deprime?",
        ["It's hard to get any more down than I am."] = "Es difícil deprimirse más que yo.",
        ["Would you like a mis-fortune?"] = "¿Quieres una desgracia?",
        ["Yes."] = "Sí.",
        ["*(If confirmation prompt isn't toggled off (and in 2017 enough tokens are owned):)*"] = "*(Si el mensaje de confirmación no está desactivado (y en 2017 se poseen suficientes tokens):)*",
        ["This activity gives Divination XP and costs ten tokens. Are you sure you want to continue?"] = "Esta actividad otorga XP a Divination y cuesta diez tokens. ¿Estás seguro de que quieres continuar?",
        ["Get a mis-fortune?"] = "¿Tienes una desgracia?",
        ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
        ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
        ["*(If the confirmation prompt is toggled off (and in 2017 enough tokens are owned):)*"] = "*(Si el mensaje de confirmación está desactivado (y en 2017 se poseen suficientes tokens):)*",
        ["*(Only in 2017:)*"] = "*(Solo en 2017 :)*",
        ["*(If not enough tokens are owned:)*"] = "*(Si no tienes suficientes tokens:)*",
        ["You do not have enough fayre tokens to play on this machine. You need 10 tokens."] = "No tienes suficientes fichas de Fayre para jugar en esta máquina. Necesitas 10 fichas.",
        ["You can get more fayre tokens and tickets from the stall by the Bucking Baroo."] = "Puede obtener más fichas y boletos de Fayre en el puesto junto al Bucking Baroo.",
        ["The machine whirrs..."] = "La máquina zumba...",
        ["The machine wobbles a bit..."] = "La máquina se tambalea un poco...",
        ["A strange strangled noise comes from the machine..."] = "Un extraño ruido ahogado proviene de la máquina...",
        ["More whirring sounds come from the machine."] = "Más zumbidos provienen de la máquina.",
        ["A single, lonely, horn blares in fanfare."] = "Un único y solitario cuerno resuena con fanfarria.",
        ["A fortune is spat out of the machine."] = "Una fortuna sale disparada de la máquina.",
        ["*(If confirmation prompt hasn't been toggled off (and in 2017 enough tokens are owned):)*"] = "*(Si el mensaje de confirmación no se ha desactivado (y en 2017 se poseen suficientes tokens):)*",
        ["Your inattentiveness to The Mighty Zoltan has disappointed him further."] = "Tu falta de atención hacia The Mighty Zoltan lo ha decepcionado aún más.",
    },
    ["The Missionary"] = {
        ["Good day. May the light of Saradomin guide you."] = "Buenos días. Que la luz de Saradomin te guíe.",
        ["How are things, Tomlin?"] = "¿Cómo van las cosas, Tomlin?",
        ["*Before Go Among the Heathens:*"] = "*Antes de ir entre los paganos:*",
        ["I am thinking on where I should build my church. Saradomin will guide me."] = "Estoy pensando en dónde debería construir mi iglesia. Saradomin me guiará.",
        ["*After Go Among the Heathens:*"] = "*Después de Ir entre los paganos:*",
        ["Hyu-Ji will be my bastion of hope in these godforsaken isles. These sea orphans will be my flock. Yes, everything is coming together."] = "Hyu-Ji será mi bastión de esperanza en estas islas olvidadas de Dios. Estos huérfanos del mar serán mi rebaño. Sí, todo está encajando.",
        ["*After Spreading the Word:*"] = "*Después de correr la voz:*",
        ["Damn the forces of Zamorak! Intervening in my plans, spreading lies to my sea orphans... I will not fade from the light. I will build my church!"] = "¡Malditas sean las fuerzas de Zamorak! Interviniendo en mis planes, difundiendo mentiras a mis huérfanos del mar... No me desvaneceré de la luz. ¡Construiré mi iglesia!",
        ["*After Voices Raised in Lamentation:*"] = "*Después de las voces alzadas en lamentación:*",
        ["I have been questioning some of my actions of late. We should talk soon, when my head is clearer."] = "Últimamente he estado cuestionando algunas de mis acciones. Deberíamos hablar pronto, cuando tenga la cabeza más clara.",
        ["*After The Belly Of the Whale:*"] = "*Después del vientre del Whale:*",
        ["My pilgrimage could not have gone better. Armed with the knowledge of the Zamorakian plot, I shall defend the sea orphans from their evil. Praise to Saradomin."] = "Mi peregrinación no podría haber ido mejor. Armado con el conocimiento del complot zamorakiano, defenderé a los huérfanos del mar de su maldad. Alabanza a Saradomin.",
        ["*After God's Grace Upon You:*"] = "*Después de la gracia de Dios sobre ti:*",
        ["My congregation is growing by the week. Many sea orphans have taken Saradomin into their hearts. Achieving this with words, rather than a mace, is certainly novel."] = "Mi congregación crece semana a semana. Muchos huérfanos del mar han tomado a Saradomin en sus corazones. Lograr esto con palabras, en lugar de con una maza, es ciertamente novedoso.",
        ["*After Hull Down On The Horizon:*"] = "*Después de hundirse en el horizonte:*",
        ["Damn those purists! Damn those pirates! Damn those practitioners of black magic and their plots! And the enemies of Saradomin gathered in the shadows, but Saradomin's light exposed their schemes and they suffered a great and terrible vengeance."] = "¡Malditos puristas! ¡Malditos sean esos piratas! ¡Malditos sean los practicantes de magia negra y sus complots! Y los enemigos de Saradomin se reunieron en las sombras, pero la luz de Saradomin expuso sus planes y sufrieron una gran y terrible venganza.",
        ["*After A Concerted Effort:*"] = "*Después de un esfuerzo concertado:*",
        ["I would defend Hyu-Ji with my last gasp, but it won't come to that. When those Purists and pirates arrive, we'll have Saradomin's gaze upon us. They will burn in his light!"] = "Defendería a Hyu-Ji con mi último suspiro, pero no llegaré a eso. Cuando lleguen esos puristas y piratas, tendremos la mirada de Saradomin sobre nosotros. ¡Arderán en su luz!",
        ["*After The Defiance of Hyu-Ji:*"] = "*Después del desafío de Hyu-Ji:*",
        ["Hyu-Ji has always persisted against the forces of evil. I must now consider what to do with my own life. Saradomin has always guided me, but my place is not with the altar."] = "Hyu-Ji siempre ha persistido contra las fuerzas del mal. Ahora debo considerar qué hacer con mi propia vida. Saradomin siempre me ha guiado, pero mi lugar no está en el altar.",
        ["I need something done, Tomlin."] = "Necesito hacer algo, Tomlin.",
        ["Certainly, I'm the man to get it done."] = "Ciertamente, soy el hombre indicado para hacerlo.",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["*Without the Occultist unlocked:*"] = "*Sin the Occultist desbloqueado:*",
        ["I'd work with another practitioner of magic. Find me someone suitable and we shall form a unit of strength and power."] = "Trabajaría con otro practicante de magia. Búscame a alguien adecuado y formaremos una unidad de fuerza y ​​poder.",
        ["*With the Occultist unlocked and not present:*"] = "*Con the Occultist desbloqueado y no presente:*",
        ["There's an occultist who frequents this den of vice who I could work with. While we aren't natural allies, she does have an appreciation for high magic. She could be of use in my endeavours."] = "Hay un ocultista que frecuenta esta guarida de vicio con quien podría trabajar. Si bien no somos aliados naturales, ella aprecia la alta magia. Ella podría ser útil en mis esfuerzos.",
        ["If both the Occultist and Missionary are in port at the same time, additional joint voyages will be made available."] = "Si tanto the Occultist como Missionary están en el puerto al mismo tiempo, estarán disponibles viajes conjuntos adicionales.",
        ["*With the Occultist unlocked and in port:*"] = "*Con the Occultist desbloqueado y en puerto:*",
        ["I suppose I could work with that pedlar of black magic, Zu Zu I think she's called. But do not mistake this as acceptance of that witch's ways, she's still a heretic, and still deserving of Saradomin's wrath. And the way she looks at me is most... insalubrious."] = "Supongo que podría trabajar con ese vendedor ambulante de magia negra, creo que se llama Zu Zu. Pero no confundas esto con la aceptación de los métodos de esa bruja, ella sigue siendo una hereje y aún merece la ira de Saradomin. Y la forma en que me mira es de lo más... insalubre.",
        ["But he's happy to work with me? How enlightened. Come on handsome, let's be off. Mmm, you don't mind walking in front, do you?"] = "¿Pero está feliz de trabajar conmigo? Qué iluminado. Vamos guapo, vámonos. Mmm, no te importa caminar delante, ¿verdad?",
        ["*Voyage screen opens*"] = "*Se abre la pantalla de viaje*",
        ["How's the life of a missionary?"] = "¿Cómo es la vida de un misionero?",
        ["Our lives are not that dissimilar. We are both devout followers of the gods, although I'm not sure we follow the same one."] = "Nuestras vidas no son tan diferentes. Ambos somos devotos seguidores de los dioses, aunque no estoy seguro de que sigamos al mismo.",
        ["Whatever your faith, I can't help but admire your devotion. Your dedication to prayer and worship is inspiring."] = "Cualquiera que sea tu fe, no puedo evitar admirar tu devoción. Su dedicación a la oración y la adoración es inspiradora.",
        ["[View Previous Cutscenes]"] = "[Ver escenas anteriores]",
        ["*Replays dialogues below*"] = "*Reproduce los diálogos a continuación*",
        ["When I want another drink, I'll command it."] = "Cuando quiera otro trago, lo ordenaré.",
        ["I know you're a man of corruption and vice. Leave me be."] = "Sé que eres un hombre corrupto y vicioso. Déjame en paz.",
    },
    ["The Monkey's Aunt"] = {
        ["Ook! Ah Uh Ah! Ook Ook! Ah!"] = "¡Ok! ¡Ah, ah, ah! ¡Ok, ok! ¡Ah!",
        ["You cannot understand what she is saying."] = "No puedes entender lo que está diciendo.",
        ["Hello! What's a monkey like you doing here?"] = "¡Hola! ¿Qué hace aquí un mono como tú?",
        ["I'm just passing through actually."] = "En realidad, estoy de paso.",
        ["Fair enough then."] = "Entonces es justo.",
    },
    ["The Monkey's Uncle"] = {
        ["Ook! Ah Uh Ah! Ook Ook! Ah!"] = "¡Ok! ¡Ah, ah, ah! ¡Ok, ok! ¡Ah!",
        ["You cannot understand what he is saying."] = "No puedes entender lo que está diciendo.",
        ["What are you doing in my house?"] = "¿Qué haces en mi casa?",
        ["I'm just passing through!"] = "¡Estoy de paso!",
        ["Well I don't give a monkey's uncle!"] = "¡Bueno, me importa un comino!",
    },
    ["The Navigator"] = {
        ["Ahem. We should talk when you're less busy."] = "Ejem. Deberíamos hablar cuando estés menos ocupado.",
        ["Ahem, Portmaster, there's a lot we need to discuss."] = "Ejem, capitán de puerto, hay muchas cosas que debemos discutir.",
        ["*So what exactly do you do here?*"] = "*Entonces, ¿qué haces exactamente aquí?*",
        ["Ahem. As the port's navigator, it is my job to chart the Wushanko isles as you explore them"] = "Ejem. Como navegante del puerto, mi trabajo es trazar un mapa de las islas Wushanko mientras las exploras.",
        ["*The Navigator will find 15 voyage prospects and 15 potential crew members for you daily.*"] = "*The Navigator encontrará diariamente 15 perspectivas de viaje y 15 miembros potenciales de tripulación para usted.*",
        ["I also collect information to provide you with summaries of what's going on in the isels. That way you can make prudent decisions on where to send your ships. As you explore the islands you can instruct me to focus on specific regions. Ahem. And I'll try to find voyages for you there."] = "También recopilo información para brindarte resúmenes de lo que sucede en las islas. De esa manera podrás tomar decisiones prudentes sobre dónde enviar tus barcos. Mientras exploras las islas, puedes indicarme que me concentre en regiones específicas. Ejem. E intentaré encontrar viajes para ti allí.",
        ["*Open the 'Voyages' interface to see potential voyages. If you've unlocked multiple regions you can choose to focus on a specific region by speaking with the navigator or opening the 'Port Management' interface.*"] = "*Abra la interfaz 'Viajes' para ver viajes potenciales. Si ha desbloqueado varias regiones, puede optar por centrarse en una región específica hablando con the navigator o abriendo la interfaz 'Administración de puertos'.*",
        ["Ahem. I have a keen interest in documenting the forgotten scrolls. They are essentially blueprints for powerful sets of armour, ancient scrimshaws and even recipes. How exactly, one, makes these artefacts has been all but lost, the only record is on the forgotten scrolls. From what I gathered these scrolls are in pieces and were scattered across the breadth of the Wushanko Isles, a long time ago. It's almost like someone didn't want them found. Let me know which scroll we should track down. I'll make sure I document what we discover."] = "Ejem. Tengo un gran interés en documentar los pergaminos olvidados. Son esencialmente planos para poderosas armaduras, antiguos scrimshaws e incluso recetas. Se ha perdido casi por completo cómo se fabrican exactamente estos artefactos; el único registro está en los pergaminos olvidados. Por lo que he recopilado, estos pergaminos están en pedazos y fueron esparcidos a lo largo de las islas Wushanko, hace mucho tiempo. Es casi como si alguien no quisiera que los encontraran. Déjame saber qué pergamino debemos localizar. Me aseguraré de documentar lo que descubramos.",
        ["*You can see what Forgotten Scrolls you've unlocked by opening the 'Port Management' interface. There you can also choose which scroll to search for next.*"] = "*Puedes ver qué Pergaminos olvidados has desbloqueado abriendo la interfaz 'Administración de puertos'. Allí también puedes elegir qué desplazamiento buscar a continuación.*",
        ["Ahem. Just consider me a tool, Portmaster."] = "Ejem. Considérame una herramienta, Portmaster.",
        ["*Discuss Forgotten Scrolls*"] = "*Discutir pergaminos olvidados*",
        ["Certainly. I've got a record of the forgotten scrolls we've found - and the one we're searching for - here. One moment, Portmaster."] = "Por supuesto. Tengo un registro de los pergaminos olvidados que encontramos y el que estamos buscando aquí. Un momento, capitán de puerto.",
        ["*Manage ports options pop up.*"] = "*Aparecen las opciones de administración de puertos.*",
        ["*Discuss our focus in the East.*"] = "*Discute nuestro enfoque en el Este.*",
        ["What region would you like me to focus my efforts on, Portmaster? I can't promise I'll only bring you information from there, to do so would be to close our mings and ears to opportunities. But I'll certainly focus my energies there."] = "¿En qué región te gustaría que centrara mis esfuerzos, Portmaster? No puedo prometer que solo les traeré información desde allí, hacerlo sería cerrar nuestros ojos y oídos a las oportunidades. Pero ciertamente concentraré mis energías allí.",
        ["*What's your story?*"] = "*¿Cuál es tu historia?*",
        ["There's not much to tell, Portmaster. I came from Varrock, originally. I've got a keen interest in cartography and was eager to explore the Wushanko Isles. Unfortunately, the sea monsters that were terrorising the East until very recently made finding a vessel that would take me very, um, difficult. I settled for exploring some of the waters around Mos'Le Harmless, but that's where I discovered my terrible sea sickness. A few buckets of vomit into our journey and they brought me back to shore. Ahem. I'd heard that this port did a good trade with the East twenty odd years ago, so I came here to see if the owner had any old maps I could study. Then you showed up. I know I'm not a leader of men like you, but the fact that - under your command - men are exploring the East, and that I'm part of it... well, that's all I could hope for."] = "No hay mucho que contar, Capitán de Puerto. Yo vengo de Varrock, originalmente. Tengo un gran interés en la cartografía y estaba ansioso por explorar las islas Wushanko. Desafortunadamente, los monstruos marinos que aterrorizaban el Este hasta hace muy poco hicieron que encontrar un barco que me llevara fuera muy difícil. Me conformé con explorar algunas de las aguas alrededor de Mos'Le Harmless, pero ahí fue donde descubrí mi terrible mareo. Unos cuantos cubos de vómito en nuestro viaje y me trajeron de regreso a la orilla. Ejem. Escuché que este puerto hizo un buen comercio con el Este hace veinte años, así que vine aquí para ver si el propietario tenía algún mapa antiguo que pudiera estudiar. Entonces apareciste. Sé que no soy un líder de hombres como usted, pero el hecho de que, bajo su mando, los hombres estén explorando el Este, y que yo sea parte de ello... bueno, eso es todo lo que podía esperar.",
        ["*I should be going.*"] = "*Debería irme.*",
        ["Ahem. Goodbye, Portmaster."] = "Ejem. Adiós, capitán de puerto.",
        ["*Before unlocking the Skull region:*"] = "*Antes de desbloquear la región Skull:*",
        ["The Port Management screen is not available until you have discovered the Skull region."] = "La pantalla de administración de puertos no está disponible hasta que haya descubierto la región Skull.",
        ["*Before completing the tutorial:*"] = "*Antes de completar el tutorial:*",
        ["You can claim a logbook once the tutorial is complete."] = "Puede reclamar un libro de registro una vez que se complete el tutorial.",
    },
    ["The Occultist"] = {
        ["Ecstatic to see you again, darling."] = "Estoy encantado de verte de nuevo, cariño.",
        ["How are things?"] = "¿Cómo van las cosas?",
        ["*Before The Brain:*"] = "*Antes del cerebro:*",
        ["Oh, I'm just thinking about death, about you and about that delicious smell of onion soup that hangs about this place."] = "Oh, solo estoy pensando en la muerte, en ti y en ese delicioso olor a sopa de cebolla que flota en este lugar.",
        ["*After The Brain:*"] = "*Después del cerebro:*",
        ["Well, I'm dreadfully pleased that we got the brain, of course. We should start searching for the body; soon, when I can muster up the energy."] = "Bueno, estoy tremendamente contento de que tengamos el cerebro, por supuesto. Deberíamos empezar a buscar el cuerpo; pronto, cuando pueda reunir energías.",
        ["*After The Body:*"] = "*Después del cuerpo:*",
        ["Could you imagine a simple life? A life where one isn't chased by narwhals while attempting rituals. Sounds dreadfully dull, doesn't it?"] = "¿Te imaginas una vida sencilla? Una vida en la que uno no sea perseguido por narvales mientras intenta realizar rituales. Suena tremendamente aburrido, ¿no?",
        ["*After The Blood:*"] = "*Después de la sangre:*",
        ["Well I simply can't wait for my date with Oroshu, the old perv. I've sent him a letter, so now we just have to wait."] = "Bueno, simplemente no puedo esperar a mi cita con Oroshu, el viejo pervertido. Le envié una carta, así que ahora sólo tenemos que esperar.",
        ["*After A Date with Oroshu:*"] = "*Después de una cita con Oroshu:*",
        ["I am a little anxious. Whilst I'm desperate to perform the ritual, it will change everything... I'll let you know as soon as it's done."] = "Estoy un poco ansioso. Aunque estoy desesperado por realizar el ritual, cambiará todo... Te lo haré saber tan pronto como esté hecho.",
        ["*After The Loophole:*"] = "*Después de la laguna jurídica:*",
        ["You've certainly given me a new lease of life, unless Quin rears her pretty little head again."] = "Ciertamente me has dado una nueva vida, a menos que Quin vuelva a levantar su bonita cabecita.",
        ["*After Meet the Partner - Again*"] = "*Después de conocer a the Partner - Otra vez*",
        ["I hoped Quin would redeem herself; we were very close once. I mean before she turned all crazy and everything."] = "Esperaba que Quin se redimiera; Estuvimos muy unidos una vez. Quiero decir, antes de que se volviera loca y todo eso.",
        ["I'm glad we were the ones to do it, the ones to kill her. With a deaf whale of all things. It's your unpredictability that I've come to love."] = "Me alegro de que fuéramos nosotros quienes lo hiciéramos, quienes la matáramos. Con una ballena sorda de todas las cosas. Es tu imprevisibilidad lo que he llegado a amar.",
        ["*After In Memory of Kirau*"] = "*Después En Memoria de Kirau*",
        ["I'm so glad that assassin girl, Ling, made peace with Kirau's family."] = "Me alegro mucho de que la asesina, Ling, haya hecho las paces con la familia de Kirau.",
        ["*After Assault on Paradise*"] = "*Después del asalto al paraíso*",
        ["Dreadfully happy! Now that Quin is dead, I truly am free. I'll miss her, of course, but that's a small price for an eternity of bliss."] = "¡Terriblemente feliz! Ahora que Quin está muerto, soy realmente libre. La extrañaré, por supuesto, pero es un pequeño precio por una eternidad de felicidad.",
        ["I wonder if you could help me."] = "Me pregunto si podrías ayudarme.",
        ["I am yours for eternity."] = "Soy tuyo por la eternidad.",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["*Without the Missionary unlocked:*"] = "*Sin the Missionary desbloqueado:*",
        ["**The Occultist::** I'm always eager to work closely with others. But I'd need someone with knowledge of old magic for us to come together as one."] = "**The Occultist::** Siempre estoy dispuesto a trabajar en estrecha colaboración con los demás. Pero necesitaría a alguien con conocimientos de magia antigua para que nos unamos como uno solo.",
        ["*With the Missionary unlocked and not present:*"] = "*Con the Missionary desbloqueado y no presente:*",
        ["Well - I've clapped eyes on a ravishing hunk of a cleric; a missionary, I believe. He's often here, nursing a pint and smouldering away in the corner."] = "Bueno, he visto a un clérigo deslumbrante; un misionero, creo. A menudo está aquí, bebiendo una pinta y ardiendo en un rincón.",
        ["I don't know much about your gods and their magic, but with our knowledge pooled, Tomlin and I would be unstoppable."] = "No sé mucho sobre tus dioses y su magia, pero con nuestro conocimiento combinado, Tomlin y yo seríamos imparables.",
        ["If both the Missionary and Occultist are in port at the same time, additional joint voyages will be made available."] = "Si tanto the Missionary como Occultist están en el puerto al mismo tiempo, estarán disponibles viajes conjuntos adicionales.",
        ["*With the Missionary unlocked and in port:*"] = "*Con the Missionary desbloqueado y en puerto:*",
        ["**The Occultist::** I'd be delighted to work with Tomlin. Having a big gruff man of god around would certainly liven things up."] = "**The Occultist::** Estaría encantado de trabajar con Tomlin. Tener a un hombre de Dios grande y brusco cerca sin duda animaría las cosas.",
        ["**The Missionary::** Hrmph. Very well - we shall work together on this."] = "**The Missionary::** Hmph. Muy bien, trabajaremos juntos en esto.",
        ["**The Missionary::** As long as she keeps her HANDS to herself!"] = "**The Missionary::** ¡Siempre y cuando mantenga sus MANOS para sí misma!",
        ["*(The Voyage List screen opens.)*"] = "*(Se abre la pantalla Lista de viajes.)*",
        ["How's the life of the occultist?"] = "¿Cómo es la vida de the occultist?",
        ["A blood ritual here. Fighting demons there. Oh, it can be SO dreary."] = "Aquí hay un ritual de sangre. Luchando contra demonios allí. Oh, puede ser TAN triste.",
        ["But don't play coy, I've heard you're no strange to the arcane arts yourself. Your knowledge of runes is second to none."] = "Pero no seas tímido, he oído que no eres ajeno a las artes arcanas. Tu conocimiento de las runas es insuperable.",
        ["[View Previous Cutscenes]"] = "[Ver escenas anteriores]",
        ["Meet the Occultist <sub>*Only if she was not your first adventurer.*</sub>"] = "Conoce a the Occultist <sub>*Solo si no fue tu primera aventurera.*</sub>",
        ["The Brain"] = "El cerebro",
        ["The Body"] = "El cuerpo",
        ["The Blood"] = "la sangre",
        ["More"] = "Más",
        ["A Date with Oroshu"] = "Una cita con Oroshu",
        ["The Loophole"] = "La escapatoria",
        ["Meet the partner - Again"] = "Conoce a the partner - Otra vez",
        ["In Memory of Kirau"] = "En memoria de Kirau",
        ["Assault on Paradise"] = "Asalto al paraíso",
        ["Another drink? How delightful, but I mustn't. I simply shouldn't."] = "¿Otro trago? Qué delicia, pero no debo hacerlo. Simplemente no debería.",
        ["Oh, get away from me, you repulsive little man."] = "Oh, aléjate de mí, hombrecito repulsivo.",
    },
    ["The Partner"] = {
        ["Hello there. I'm looking for a partner; someone to help me run this place."] = "Hola. Busco pareja; Alguien que me ayude a administrar este lugar.",
        ["Erm. And I'm sorry to say you just don't have the skills I'm looking for."] = "Erm. Y lamento decirte que simplemente no tienes las habilidades que estoy buscando.",
        ["You require at least level 90 in either Agility, Construction, Cooking, Divination, Dungeoneering, Fishing, Herblore, Hunter, Prayer, Runecrafting, Slayer or Thieving to start a port."] = "Necesita al menos el nivel 90 en Agility, Construction, Cooking, Divination, Dungeoneering, Fishing, Herblore, Hunter, Prayer, Runecrafting, Slayer o Thieving para iniciar un puerto.",
        ["Hello there!"] = "¡Hola!",
        ["Select an Option"] = "Selecciona una opción",
        ["So what work do you actually do here?"] = "Entonces, ¿qué trabajo haces realmente aquí?",
        ["Ah - well. Let's not skirt around the wreck here, partner. I'm an old man. I'm not young or fit like your good self."] = "Ah, bueno. No demos vueltas alrededor del naufragio, compañero. Soy un old man. No soy joven ni estoy en forma como tú.",
        ["No, I'd only get in the way if I was out there trying to manage this place with you."] = "No, solo estorbaría si estuviera ahí afuera tratando de administrar este lugar contigo.",
        ["To be honest, I'm not sure if I ever was that capable. Even in the glory days I reckon I was just in the right place at the right time."] = "Para ser honesto, no estoy seguro de haber sido tan capaz. Incluso en los días de gloria, creo que estuve en el lugar correcto en el momento correcto.",
        ["The old port just seemed to run herself."] = "El antiguo puerto parecía funcionar solo.",
        ["These days I reckon it's best if I remain a silent partner."] = "Hoy en día creo que es mejor si sigo siendo un socio silencioso.",
        ["I'll keep an eye of Duncan, here, and make sure he doesn't cause any mischief. That's almost a full-time job on its own."] = "Estaré atento a Duncan y me aseguraré de que no cause ningún daño. Eso es casi un trabajo de tiempo completo por sí solo.",
        ["How did the port end up in disrepair?"] = "¿Cómo acabó el puerto en mal estado?",
        ["You think I frittered my money away, right? Spent all my dosh on good livin' and bad choices?"] = "Crees que desperdicié mi dinero, ¿verdad? ¿Gasté todo mi dinero en buena vida y malas decisiones?",
        ["Well, I can't claim to be the most savvy businessman, but believe it or not, it wasn't all my fault."] = "Bueno, no puedo pretender ser el hombre de negocios más inteligente, pero lo creas o no, no fue todo culpa mía.",
        ["This port always traded with the east, ever since I founded it. We didn't send ships out to the east, the merchants travelled here."] = "Este puerto siempre comerció con el este, desde que lo fundé. No enviamos barcos al este, los mercaderes viajaban hasta aquí.",
        ["And the things they brought here. I made a fortune. Richest man for miles."] = "Y las cosas que trajeron aquí. Hice una fortuna. El hombre más rico en millas.",
        ["And then suddenly they just stopped coming. This must have been twenty years back. So I did some investigating, sent out ships of my own. Only a few made it back."] = "Y de repente dejaron de venir. Esto debe haber sido hace veinte años. Así que investigué un poco y envié mis propias naves. Sólo unos pocos lograron regresar.",
        ["What happened?"] = "¿Qué pasó?",
        ["Well, they came back with stories of huge sea monsters; hydras, huge flying turtles, whales the size of islands that ate only men's skulls. The beasts had started targeting ships, as if they were instructed."] = "Bueno, volvieron con historias de enormes monstruos marinos; hidras, enormes tortugas voladoras, ballenas del tamaño de islas que sólo comían cráneos de hombres. Las bestias habían comenzado a apuntar a los barcos, como si hubieran recibido instrucciones.",
        ["Turns out it was a seasinger called Quin. Seasingers have the power to control the oceans - and those that in it - through song."] = "Resulta que era un cantante marino llamado Quin. Los cantores marinos tienen el poder de controlar los océanos, y los que se encuentran en ellos, a través del canto.",
        ["But they need to be close. Now, somehow Quin had found a way to control the monsters all at once from afar."] = "Pero necesitan estar cerca. Ahora, de alguna manera Quin había encontrado una manera de controlar a todos los monstruos a la vez desde lejos.",
        ["She held the east to ransom. She wanted them to worship her like a goddess, of course those Easterners don't believe in gods so they weren't going for it."] = "Ella retuvo el este para pedir rescate. Ella quería que la adoraran como a una diosa, por supuesto, esos orientales no creen en dioses, así que no lo aceptaron.",
        ["With no one coming from the east, my port just... fell apart. What could I do?"] = "Sin nadie viniendo del este, mi puerto simplemente... se vino abajo. ¿Qué podría hacer?",
        ["Work to do, must be going."] = "Trabajo por hacer, debe estar en marcha.",
        ["Of course, of course."] = "Por supuesto, por supuesto.",
    },
    ["The Postcat"] = {
        ["You pet The Postcat, and take a copy of their pawprint."] = "Acaricias a The Postcat y tomas una copia de su huella.",
        ["You have found The Postcat."] = "Has encontrado The Postcat.",
        ["[You have discovered a new cat!]"] = "[¡Has descubierto un nuevo gato!]",
        ["[You quickly note it down in your logbook.<br><br>'The Postcat']"] = "[Lo anotas rápidamente en tu cuaderno de bitácora.<br><br>'The Postcat']",
        ["Meow, meow meow."] = "Miau, miau, miau.",
        ["Hello there, and what's your name?"] = "Hola, ¿y cómo te llamas?",
        ["Err...Player?"] = "Err... ¿Player?",
        ["Sorry, I don't have any post for you here."] = "Lo siento, no tengo ninguna publicación para ti aquí.",
        ["Say, you couldn't do an old cat a favour? I seem to have misplaced my pet human somewhere along my route today."] = "Oye, ¿no podrías hacerle un favor a un gato viejo? Parece que hoy perdí a mi mascota humana en algún lugar de mi ruta.",
        ["Oh, really?"] = "Oh, ¿en serio?",
        ["Yes, she's wearing black and white and responds to the name Jess. Let her know to meet me in Pollnivneach this evening if you see her, thanks!"] = "Sí, viste de blanco y negro y responde al nombre Jess. Dile que se reunirá conmigo en Pollnivneach esta noche si la ves, ¡gracias!",
    },
    ["The Raptor"] = {
        ["I want to fight."] = "Quiero pelear.",
        ["**Head Mystic** Welcome, my...child. Praise the Holy Ones for bringing you here."] = "**Head Mystic** Bienvenido, mi... niño. Alabado sea los Santos por traerte aquí.",
        ["The Holy Ones. Tell me about them."] = "Los Santos. Cuéntame sobre ellos.",
        ["**Head Mystic** The Holy Ones! They are the most blessed of all the gods' creatures."] = "**Head Mystic** ¡Los Santos! Son las más benditas de todas las criaturas de los dioses.",
        ["**Head Mystic** Long ago, they served their gods in the glorious wars. Even now, when their bodies are gone, they faithfully continue the fight."] = "**Head Mystic** Hace mucho tiempo, sirvieron a sus dioses en las guerras gloriosas. Incluso ahora, cuando sus cuerpos han desaparecido, continúan fielmente la lucha.",
        ["Huh huh. Sound like my kind of people."] = "Ajá. Suena como mi tipo de gente.",
        ["**Head Mystic** We are working to restore the Holy Ones' bodies. Would you help us fight for the sacred clay that we need?"] = "**Head Mystic** Estamos trabajando para restaurar los cuerpos de los Santos. ¿Nos ayudarías a luchar por el barro sagrado que necesitamos?",
        ["Yes!"] = "¡Sí!",
        ["**Head Mystic** First, you must free yourself of all worldly attachments before you can walk the path between worlds."] = "**Head Mystic** Primero, debes liberarte de todos los apegos mundanos antes de poder recorrer el camino entre mundos.",
        ["No. Not taking off armour. Not taking off helmet."] = "No. No quitarme la armadura. No quitarse el casco.",
        ["**Head Mystic** You can make yourself a new helmet from sacred clay once you get to-"] = "**Head Mystic** Puedes hacerte un casco nuevo con arcilla sagrada una vez que llegues a-",
        ["No! Not taking off helmet!"] = "¡No! ¡Sin quitarse el casco!",
        ["Keep your Holy Ones! Keep your magic clay! I am the Raptor! No one sees my face."] = "¡Mantén a tus Santos! ¡Conserva tu arcilla mágica! ¡Soy the Raptor! Nadie ve mi cara.",
        ["The Raptor ignores you."] = "The Raptor te ignora.",
        ["Heard you killed Nezikchened. Not impressed. Just a demon. Killed lots of demons."] = "Escuché que mataste a Nezikchened. No impresionado. Sólo un demonio. Mató a muchos demonios.",
        ["Heard you killed Pest Queen. Interesting fight. Pity I couldn't be there."] = "Escuché que mataste a Pest Queen. Interesante pelea. Lástima que no pude estar allí.",
        ["Heard you killed Elvarg. Not impressed. Just a dragon. Killed lots of dragons."] = "Escuché que mataste a Elvarg. No impresionado. Sólo un dragón. Mató a muchos dragones.",
        ["Heard you killed Balance Elemental and helped sort Lucien out. Shame you didn't take on the dragonkin."] = "Escuché que mataste a Balance Elemental y ayudaste a aclarar a Lucien. Lástima que no te hayas enfrentado a los dragonantes.",
        ["Heard you killed Nomad. Impressed. Maybe you're as good as me."] = "Escuché que mataste a Nomad. Impresionado. Quizás seas tan bueno como yo.",
        ["Heard you cleared Temple of Light. Found way to Prifddinas."] = "Escuché que limpiaste el Templo de la Luz. Camino encontrado a Prifddinas.",
        ["Heard you killed 'The Inadequacy'. Inside Cyrisus's head. Huh. Imaginary monster. Not impressed."] = "Escuché que mataste a 'The Inadequacy'. Dentro de la cabeza de Cyrisus. Eh. Monstruo imaginario. No impresionado.",
        ["Give me a task."] = "Dame una tarea.",
        ["You've done all my tasks, Raptor. There's nothing more I can teach you."] = "Has hecho todas mis tareas, Raptor. No hay nada más que pueda enseñarte.",
        ["Give me. A task."] = "Dame. Una tarea.",
        ["Look, shouldn't you do something else? You've only just finished my last task."] = "Mira, ¿no deberías hacer otra cosa? Acabas de terminar mi última tarea.",
        ["Too easy!"] = "¡Demasiado fácil!",
        ["Everything I suggest will be too easy. You could be a slayer master if you wanted to. You should be teaching me."] = "Todo lo que sugiero será demasiado fácil. Podrías ser un slayer master si quisieras. Deberías estar enseñándome.",
        ["Stand around. Huh. Not the Raptor. I fight!"] = "Quédate ahí. Eh. No the Raptor. ¡Yo peleo!",
        ["Well, alright, but there's still nothing I can-"] = "Bueno, está bien, pero todavía no hay nada que pueda-",
        ["Give. Me. A Task!"] = "Da. A mí. ¡Una tarea!",
        ["Alright! Go and kill...oh I don't know...five thousand dagannoths."] = "¡Muy bien! Ve y mata... oh, no lo sé... cinco mil dagannoths.",
        ["Dagannoths. Huh. Huh huh."] = "Dagannoths. Eh. Eh, eh.",
        ["Goodbye. See you when you're done, no doubt."] = "Adiós. Nos vemos cuando hayas terminado, sin duda.",
        ["Hello Player. Gods, I hope you never end up like that."] = "Hola Player. Dioses, espero que nunca termines así.",
        ["I have a special request for [breed]. Especially if it has the [Trait] trait!"] = "Tengo una solicitud especial para [breed]. ¡Especialmente si tiene el rasgo [Trait]!",
        ["I'm also after some Dragons, in fact I'll buy up to [number] more while I'm here."] = "También busco algunos dragones, de hecho compraré hasta [número] más mientras esté aquí.",
        ["Would you like to sell [name] for [number] beans?"] = "¿Le gustaría vender [name] por frijoles [número]?",
        ["Sell [name] for [number] beans?"] = "¿Vender [name] por frijoles [número]?",
        ["Yes."] = "Sí.",
        ["Your currency pouch is full of beans! You need to spend some beans before you can earn any more."] = "¡Tu bolsa de monedas está llena de frijoles! Necesitas gastar algunos frijoles antes de poder ganar más.",
        ["You can't hold anymore beans, I can't purchase this animal off you."] = "No puedes aguantar más frijoles, no puedo comprarte este animal.",
        ["This transaction would take you over the cap of one million beans. In doing so, you would lose out on [number] beans."] = "Esta transacción le llevaría por encima del límite de un millón de frijoles. Al hacerlo, perdería beans [número].",
        ["Complete transaction anyway?"] = "¿Completar la transacción de todos modos?",
        ["[number] beans added to your currency pouch."] = "Frijoles [número] agregados a su bolsa de divisas.",
        ["Let me check what animals I have which match your request."] = "Déjame comprobar qué animales tengo que coincidan con tu solicitud.",
        ["I've bought all the animals I need for now, catch you later!"] = "He comprado todos los animales que necesito por ahora, ¡nos vemos más tarde!",
        ["Are you sure you want me to take all the Dragons you're holding? I won't take any of your favourites."] = "¿Estás seguro de que quieres que me lleve todos los dragones que tienes? No aceptaré ninguno de tus favoritos.",
        ["Sell all of your dragons?"] = "¿Vender todos tus dragones?",
        ["Yes"] = "si",
        ["You don't have any animals to sell. Zero animals, Zero beans!"] = "No tienes animales para vender. ¡Cero animales, cero frijoles!",
        ["You've sold [number] animals for [number] total beans."] = "Has vendido animales [número] por un total de frijoles [número].",
        ["Help, or leave me alone."] = "Ayuda o déjame en paz.",
        ["Hi! What's going on here?"] = "¡Hola! ¿Qué está pasando aquí?",
        ["Well met, and welcome to War's Retreat."] = "Bien conocido y bienvenido al retiro de War.",
        ["I am known as the Raptor, and I'm here at our host's request to grant Gielinor's greatest warriors a boon."] = "Me conocen como the Raptor y estoy aquí a petición de nuestro anfitrión para otorgar una bendición a los mejores guerreros de Gielinor.",
        ["Once per day, I can grant you Raptor's Favour, which increases the chance you'll earn a fitting trophy from glorious battle."] = "Una vez al día, puedo otorgarte el Favor de Raptor, lo que aumenta las posibilidades de que ganes un trofeo adecuado en una batalla gloriosa.",
        ["[While Raptor's Favour is active, your next boss kill before daily reset (00:00 UTC) will grant you three chances to access boss-specific rare drops, rather than one.]"] = "[Mientras Raptor's Favor esté activo, tu próxima muerte de jefe antes del reinicio diario (00:00 UTC) te otorgará tres oportunidades de acceder a objetos raros específicos del jefe, en lugar de una.]",
        ["Speak to me, ask for Raptor's Favour, then step through one of these portals and enter the fray."] = "Habla conmigo, pide el favor de Raptor, luego atraviesa uno de estos portales y entra en la refriega.",
        ["Back for more?"] = "¿Has vuelto por más?",
        ["Select an option"] = "Selecciona una opción",
        ["What's this event again, and how does it work?"] = "¿Qué es este evento nuevamente y cómo funciona?",
        ["See the big fellow over by the entrance? Tall. Vacant expression. Anthropomorphic personification of mortal conflict."] = "¿Ves al tipo grande que está junto a la entrada? Alto. Expresión vacante. Personificación antropomorfa del conflicto mortal.",
        ["War? It's kind of hard to miss him."] = "¿War? Es un poco difícil extrañarlo.",
        ["We go way back. So, when he asked me to endorse his special event as a guest of honour, how could I say no?"] = "Nos remontamos a mucho tiempo atrás. Entonces, cuando me pidió que respaldara su evento especial como invitado de honor, ¿cómo podría decirle que no?",
        ["Especially when it involves killing things."] = "Especialmente cuando se trata de matar cosas.",
        ["Long story short, once per day I can grant you Raptor's Favour - a boon that increases the chance you'll pick up a fitting trophy from the body of a worthy foe."] = "En pocas palabras, una vez al día puedo otorgarte el Favor de Raptor, una bendición que aumenta las posibilidades de que recojas un trofeo adecuado del cuerpo de un enemigo digno.",
        ["What counts as a worthy foe?"] = "¿Qué se considera un enemigo digno?",
        ["Something nasty enough to be worthwhile. Stepping through one of these portals here should set you on the right path."] = "Algo lo suficientemente desagradable como para que valga la pena. Pasar por uno de estos portales aquí debería situarlo en el camino correcto.",
        ["[It can be activated once per day while the event lasts by talking to the Raptor.]"] = "[Se puede activar una vez al día mientras dure el evento hablando con the Raptor.]",
        ["Grant me Raptor's Favour!"] = "Grant ¡El favor de Raptor!",
        ["There. Now, go forth and slaughter!"] = "Ahí. ¡Ahora, adelante y mata!",
        ["[Raptor's Favour is active! Your next boss kill before daily reset (00:00 UTC) will grant you three chances to access boss-specific rare drops, rather than one.]"] = "[¡El favor del raptor está activo! La próxima muerte de tu jefe antes del reinicio diario (00:00 UTC) te otorgará tres oportunidades de acceder a objetos raros específicos del jefe, en lugar de una.]",
        ["Sorry - War's event is over."] = "Lo sentimos, el evento de War terminó.",
        ["You already have Raptor's Favour. What're you waiting for? Kill something! Something big!"] = "Ya tienes Raptor's Favor. ¿Qué estás esperando? ¡Mata algo! ¡Algo grande!",
        ["Looks like you've used up your Raptor's Favour for today."] = "Parece que has agotado tu Favor de Raptor por hoy.",
        ["[Raptor's Favour will be available again after daily reset (00:00 UTC).]"] = "[Raptor's Favor estará disponible nuevamente después del reinicio diario (00:00 UTC).]",
        ["Who are you, anyway?"] = "¿Quién eres tú, de todos modos?",
        ["I've little use for names, but some call me the Raptor. It serves well enough."] = "No me sirven mucho los nombres, pero algunos me llaman the Raptor. Sirve bastante bien.",
        ["Suffice it to say I'm a wandering warrior - always on the look-out for the next challenge."] = "Baste decir que soy un guerrero errante, siempre atento al próximo desafío.",
        ["Ideally a challenge with dripping, venomous fangs. Or razor-sharp claws that can cleave a grown man in twain! Ooh! Or paralysing spines that shoot from its-"] = "Idealmente, un desafío con colmillos venenosos y goteantes. ¡O garras afiladas que pueden partir en dos a un hombre adulto! ¡Oh! O espinas paralizantes que salen disparadas de su...",
        ["I'll...leave you to it."] = "Te... dejaré con eso.",
        ["Goodbye"] = "Adiós",
        ["Good hunting."] = "Buena caza.",
        ["Choose an option:"] = "Elige una opción:",
        ["Can we talk about assignments?"] = "¿Podemos hablar de asignaciones?",
        ["I need another assignment."] = "Necesito otra tarea.",
        ["[pic=Slayer master cape detail.png]"] = "[pic=Slayer master capa detail.png]",
        ["Change your assigned Slayer task?"] = "¿Cambiar su tarea Slayer asignada?",
        ["[number] [monsters] (default)"] = "[número] [monsters] (predeterminado)",
        ["[number] [monsters] (costs 1 Slayer token)"] = "[número] [monsters] (cuesta 1 token Slayer)",
        ["Modify your assigned Slayer task?"] = "¿Modificar su tarea Slayer asignada?",
        ["[maximal number] [monsters] (max)"] = "[maximal number] [monsters] (máx.)",
        ["Okay then, I suppose. Your new task is to kill [number] [monsters]."] = "Está bien, entonces, supongo. Tu nueva tarea es matar a [número] [monsters].",
        ["You're doing okay, I suppose. Your new task is to kill [number] [monsters]."] = "Lo estás haciendo bien, supongo. Tu nueva tarea es matar a [número] [monsters].",
        ["Select an Option"] = "Selecciona una opción",
        ["Got any tips for me?"] = "¿Tienes algún consejo para mí?",
        ["Okay, great!"] = "¡Vale, genial!",
        ["Don't fail, and don't forget to come back when you need a new assignment."] = "No falles y no olvides volver cuando necesites una nueva tarea.",
        ["No thanks. (Clear task, costs 30 Slayer points)"] = "No gracias. (Tarea clara, cuesta 30 puntos Slayer)",
        ["You're still hunting [monsters]; come back when you've finished your task."] = "Todavía estás cazando a [monsters]; Vuelve cuando hayas terminado tu tarea.",
        ["Let's talk about you."] = "Hablemos de ti.",
        ["Names do not matter. Call me the Raptor."] = "Los nombres no importan. Llámame the Raptor.",
        ["Combat is all that matters. Worth comes in battle."] = "El combate es lo único que importa. El valor viene en la batalla.",
        ["With every monster I slay, I grow stronger."] = "Con cada monstruo que mato, me hago más fuerte.",
        ["Can we talk about changing your task length?"] = "¿Podemos hablar de cambiar la duración de tu tarea?",
        ["Choose your task length:"] = "Elija la duración de su tarea:",
        ["Default"] = "Predeterminado",
        ["[Slayer tasks from the Raptor will now be the default length.]"] = "[Las tareas Slayer de the Raptor ahora tendrán la duración predeterminada.]",
        ["Short"] = "corto",
        ["[You will now receive shorter slayer tasks from the Raptor.]"] = "[Ahora recibirás tareas de asesino más cortas de the Raptor.]",
        ["Long"] = "largo",
        ["[You will now receive longer slayer tasks from the Raptor.]"] = "[Ahora recibirás tareas de asesino más largas de the Raptor.]",
        ["cond=Only before completing A Place For My Heads:"] = "cond=Solo antes de completar A Place For My Heads:",
        ["Can you talk to me a bit more about the trophy rewards?"] = "¿Puedes hablarme un poco más sobre las recompensas de trofeos?",
        ["Trophies enhance your Slayer skill. They have benefits that will assist you while you complete my tasks."] = "Los trofeos mejoran tu habilidad Slayer. Tienen beneficios que te ayudarán mientras completas mis tareas.",
        ["Each time you return to me after completing one of my challenges, I will grant you a new trophy to place in your guardhouse providing you are strong enough."] = "Cada vez que regreses a mí después de completar uno de mis desafíos, te otorgaré un nuevo trofeo para que lo coloques en tu caseta de vigilancia, siempre que seas lo suficientemente fuerte.",
        ["[You will receive a new hotspot reward from the Raptor after completing his Slayer tasks at 30, 50, and 90 Slayer.]"] = "[Recibirás una nueva recompensa de punto de acceso de the Raptor después de completar sus tareas de Slayer en 30, 50 y 90 Slayer.]",
        ["Do you have any rewards for me?"] = "¿Tienes alguna recompensa para mí?",
        ["I'm sorry, you don't have enough space for all of your rewards. {{Sic|Come back once you've up some space.}}"] = "Lo siento, no tienes suficiente espacio para todas tus recompensas. {{Sic|Come back once you've up some space.}}",
        ["[You have received: Slayer Trophy ([Zombie/Skeleton/Phantom])]"] = "[Has recibido: Trofeo Slayer ([Zombie/Skeleton/Phantom])]",
        ["Here is your reward. If you mount it in the guardhouse, it should offer you some positive effects."] = "Aquí está tu recompensa. Si lo montas en la caseta de vigilancia, debería ofrecerte algunos efectos positivos.",
        ["Here are all the rewards you are owed. If you mount them in the guardhouse, they should offer you some positive effects."] = "Aquí están todas las recompensas que se le deben. Si los montas en la caseta de vigilancia, deberían ofrecerte algunos efectos positivos.",
        ["You don't have any available rewards."] = "No tienes ninguna recompensa disponible.",
        ["Er...nothing..."] = "Eh... nada...",
        ["The undead in the crypts to the north will overwhelm the fort if you do nothing."] = "Los muertos vivientes en las criptas del norte arrasarán el fuerte si no haces nada.",
        ["Slay [number] of them. I will do the same, and we will meet back here."] = "Mata a [número] de ellos. Yo haré lo mismo y nos encontraremos aquí.",
        ["Stronger targets are worth multiple kills. Do you understand?"] = "Los objetivos más fuertes merecen varias muertes. ¿Lo entiendes?",
        ["Complete this task and you will earn a trophy. Trophies enhance your slayer ability."] = "Completa esta tarea y ganarás un trofeo. Los trofeos mejoran tu habilidad de asesino.",
        ["[Completing this task will award extra slayer points.]"] = "[Completar esta tarea otorgará puntos de cazador adicionales.]",
        ["Very well, I accept your challenge."] = "Muy bien, acepto tu desafío.",
        ["Good."] = "Bien.",
        ["No thanks, I'd prefer a regular assignment instead."] = "No, gracias. Preferiría una tarea normal.",
        ["You've completed your special assignment from the Raptor and receive 3000 slayer experience and 20 slayer points."] = "Has completado tu tarea especial de the Raptor y recibes 3000 experiencia de cazador y 20 puntos de cazador.",
        ["The Raptor has a new reward for you."] = "The Raptor tiene una nueva recompensa para ti.",
        ["The Raptor teaches you about Slayer."] = "The Raptor te enseña sobre Slayer.",
        ["Thanks, I'll add those to my collection."] = "Gracias, los agregaré a mi colección.",
        ["Hello? is{{Sic}} this the Raptor?"] = "¿Hola? ¿Es {{Sic}} este the Raptor?",
        ["You have no business in my head. My thoughts are my own."] = "No tienes nada que hacer en mi cabeza. Mis pensamientos son míos.",
        ["It's Player. I'm using my magic to communicate with you."] = "Soy Player. Estoy usando mi magia para comunicarme contigo.",
        ["Explain yourself."] = "Explícate.",
        ["Er...nothing."] = "Eh... nada.",
        ["Aberrant spectres are fetid, vile ghosts. The very smell of them will paralyze and harm you. I would advise using a nose peg to avoid their stink. You would do well using a ranged weapon against them."] = "Los espectros aberrantes son fantasmas fétidos y viles. El solo olor de ellos te paralizará y te hará daño. Aconsejaría utilizar una clavija en la nariz para evitar su mal olor. Harías bien en usar un arma a distancia contra ellos.",
        ["The last Abyssal demon I killed I found slashing attacks took them down effectively."] = "El último demonio abisal que maté encontré que los ataques cortantes los derribaron de manera efectiva.",
        ["Abyssal demons are nasty creatures to deal with. They teleport around to confuse and trap their prey. They can be found within the Canifis Slayer Tower or inhabiting the Senntisten Asylum."] = "Los demonios abisales son criaturas desagradables con las que lidiar. Se teletransportan para confundir y atrapar a sus presas. Se pueden encontrar dentro de la Torre Canifis Slayer o habitando el Asilo Senntisten.",
        ["The last Acheron mammoth I killed I found stabbing attacks took them down effectively."] = "El último Acheron mammoth que maté descubrí que los ataques de apuñalamiento los derribaron de manera efectiva.",
        ["Acheron mammoths are honourable and proud beasts from the frozen north that know the true worth of battle. When they charge you, ensure you get out of the way. They can be found on an iceberg that is accessible from a dock east of Rellekka."] = "Los mamuts de Acheron son bestias honorables y orgullosas del norte helado que conocen el verdadero valor de la batalla. Cuando te cobren, asegúrate de apartarte del camino. Se pueden encontrar en un iceberg al que se puede acceder desde un muelle al este de Rellekka.",
        ["The last Ankou I killed I found earth spells took them down effectively."] = "El último Ankou que maté descubrí que los hechizos de tierra los derribaron de manera efectiva.",
        ["Ankou are undead beings that can be described as neither ghost nor skeleton, but a combination of both. Not much is known about these creatures, however, they make their home in the Stronghold of Security."] = "Los ankou son seres no muertos que no pueden describirse ni como fantasmas ni como esqueletos, sino como una combinación de ambos. No se sabe mucho sobre estas criaturas, sin embargo, tienen su hogar en la Fortaleza de Seguridad.",
        ["The last Armoured phantom I killed I found crushing attacks took them down effectively."] = "El último fantasma blindado que maté encontré que los ataques aplastantes los derribaron de manera efectiva.",
        ["You can find armoured phantoms swarming inside the crypts north of Fort Forinthry. Their hateful spirits seek only violence. You'll find crush weapons effective at breaking down their ability to move."] = "Puedes encontrar fantasmas blindados pululando dentro de las criptas al norte de Fort Forinthry. Sus espíritus odiosos sólo buscan la violencia. Encontrarás que las armas aplastantes son efectivas para debilitar su capacidad de moverse.",
        ["Aviansies can be found within the God Wars Dungeon north of Trollheim. As they fly, you'll find it difficult to reach them with melee weapons, so try using ranged or magic weapons instead."] = "Los aviansies se pueden encontrar dentro del God Wars Dungeon al norte de Trollheim. Mientras vuelan, te resultará difícil alcanzarlos con armas cuerpo a cuerpo, así que intenta usar armas mágicas o a distancia.",
        ["The last Black demon I killed I found a crossbow with bolts took them down effectively."] = "El último demonio negro que maté encontré una ballesta con pernos que los derribó de manera efectiva.",
        ["Black demons are among the strongest of the Avernic demons. They can be found within the Brimhaven and Taverley dungeons. Using crossbows would be advantageous."] = "Los demonios negros se encuentran entre los demonios avernicos más fuertes. Se pueden encontrar dentro de las mazmorras Brimhaven y Taverley. Usar ballestas sería una ventaja.",
        ["The last Black dragon I killed I found a crossbow with bolts took them down effectively."] = "El último dragón negro que maté encontré una ballesta con pernos que los derribó de manera efectiva.",
        ["Black dragons are the strongest of the chromatic dragons. They can be found resting within Taverley Dungeon. Using crossbows would be advantageous."] = "Los dragones negros son los más fuertes de los dragones cromáticos. Se pueden encontrar descansando dentro de Taverley Dungeon. Usar ballestas sería una ventaja.",
        ["The last Bound skeleton I killed I found earth spells took them down effectively."] = "El último esqueleto atado que maté encontré que los hechizos de tierra los derribaron de manera efectiva.",
        ["Animated by Zemouregal, you can find bound skeletons swarming inside the crypts north of Fort Forinthry. You'll find earth magic effective at breaking down their ancient bones."] = "Animado por Zemouregal, puedes encontrar esqueletos atados pululan dentro de las criptas al norte de Fort Forinthry. Encontrarás que la magia de la tierra es eficaz para descomponer sus huesos antiguos.",
        ["The last Camel Warrior I killed I found crushing attacks took them down effectively."] = "El último guerrero Camel que maté encontré que los ataques aplastantes lo derribaron de manera efectiva.",
        ["Camel Warriors use ancient magics to attack you. They can use cowardly disorientation magic to confuse you. You can find them in the deep desert, teach them a lesson in humility."] = "Los guerreros Camel usan magia antigua para atacarte. Pueden usar magia de desorientación cobarde para confundirte. Puedes encontrarlos en lo profundo del desierto, darles una lección de humildad.",
        ["The last Dagannoth I killed I found air spells took them down effectively."] = "El último Dagannoth que maté encontré que los hechizos de aire los derribaron de manera efectiva.",
        ["Dagannoth are large, sea-dwelling creatures that are very aggressive. You'll often find them in caves near seawater."] = "Los Dagannoth son criaturas marinas grandes que son muy agresivas. A menudo los encontrarás en cuevas cerca del agua de mar.",
        ["The last Dark beast I killed I found a crossbow with bolts took them down effectively."] = "La última bestia oscura que maté encontré una ballesta con pernos que los derribó de manera efectiva.",
        ["Dark beasts are large, dog-like predators with massively muscled bodies that protect them from crushing weapons. They can be found within the Mourner tunnels."] = "Las bestias oscuras son depredadores grandes, parecidos a perros, con cuerpos enormemente musculosos que los protegen de las armas aplastantes. Se pueden encontrar dentro de los túneles Mourner.",
        ["You can find many types of demons around Gielinor, notably the abyssal demons infesting the Canifis Slayer Tower."] = "Puedes encontrar muchos tipos de demonios alrededor de Gielinor, en particular los demonios abisales que infestan la Torre Canifis Slayer.",
        ["The last Green dragon I killed I found a crossbow with bolts took them down efficiently."] = "El último dragón verde que maté encontré una ballesta con pernos que los derribó de manera eficiente.",
        ["You can find dragons through Gielinor. Many types of them can be found within Brimhaven Dungeon."] = "Puedes encontrar dragones a través de Gielinor. Se pueden encontrar muchos tipos de ellos en Brimhaven Dungeon.",
        ["The last Fetid zombie I killed I found air spells took them down effectively."] = "El último zombi fétido que maté encontré que los hechizos de aire los derribaron de manera efectiva.",
        ["These pitiful creatures have no mind of their own and seek only the flesh of their enemies. You can find fetid zombies inside the crypts north of Fort Forinthry. You'll find using magic effective against them."] = "Estas lamentables criaturas no tienen voluntad propia y sólo buscan la carne de sus enemigos. Puedes encontrar zombis fétidos dentro de las criptas al norte de Fort Forinthry. Descubrirás que usar magia es efectivo contra ellos.",
        ["The last Fire giant I killed I found water spells took them down effectively."] = "El último gigante de fuego que maté encontré que los hechizos de agua los derribaron de manera efectiva.",
        ["Like other giants, fire giants often wield large weapons. Learn to recognise what kind of weapon it is and act accordingly. They can be found in Brimhaven Dungeon. Using water spells would be advantageous."] = "Al igual que otros gigantes, los gigantes de fuego suelen empuñar armas grandes. Aprende a reconocer qué tipo de arma es y actúa en consecuencia. Se pueden encontrar en Brimhaven Dungeon. Usar hechizos de agua sería una ventaja.",
        ["The last Risen ghost I killed I found a bow and arrows took them down effectively."] = "El último fantasma resucitado que maté encontré un arco y las flechas los derribaron de manera efectiva.",
        ["You can find many types of ghosts around Gielinor, notably those flooding the crypts north of Fort Forinthry."] = "Puedes encontrar muchos tipos de fantasmas alrededor de Gielinor, en particular los que inundan las criptas al norte de Fort Forinthry.",
        ["The last Greater demon I killed I found a crossbow with bolts took them down effectively."] = "El último demonio mayor que maté encontré una ballesta con pernos que los derribó de manera efectiva.",
        ["Greater demons are relatively weak, however, you should still be careful as they can be dangerous. They can be found in Brimhaven Dungeon. Using crossbows would be advantageous."] = "Los demonios mayores son relativamente débiles, sin embargo, debes tener cuidado ya que pueden ser peligrosos. Se pueden encontrar en Brimhaven Dungeon. Usar ballestas sería una ventaja.",
        ["Green dragons are the weakest of the chromatic dragons and can be found west of the Dark Warriors Fortress. Using crossbows would be advantageous."] = "Los dragones verdes son los más débiles de los dragones cromáticos y se pueden encontrar al oeste de la Fortaleza de los Guerreros Oscuros. Usar ballestas sería una ventaja.",
        ["The last Young grotworm I killed I found a crossbow with bolts took them down effectively."] = "El último gusano joven que maté encontré una ballesta con pernos que los derribó de manera efectiva.",
        ["Grotworms have been spotted in a cave near Rimmington. They will bite and attack with some sort of acid spit."] = "Se han visto gusanos de grot en una cueva cerca de Rimmington. Morderán y atacarán con una especie de saliva ácida.",
        ["Hellhounds are Shakroth class Avernic demons, the lowest class of demons from Infernus. You can find them in Taverley Dungeon and will find slash weapons effective against them."] = "Los Hellhounds son demonios Avernic de clase Shakroth, la clase más baja de demonios de Infernus. Puedes encontrarlos en Taverley Dungeon y encontrarás armas cortantes efectivas contra ellos.",
        ["The last Kalphite Soldier I killed I found water spells took them down effectively."] = "El último soldado calfita que maté descubrí que los hechizos de agua los derribaron de manera efectiva.",
        ["Kalphites are large insectoids that live in hives under the Kharidian desert. You can find them southwest of Shantay Pass."] = "Los calfitos son grandes insectoides que viven en colmenas bajo el Kharidian desert. Puedes encontrarlos al suroeste del paso Shantay.",
        ["Lesser demons are some of the weakest of all Avernic demons. They can be found inhabiting the Karamja Dungeon. Using crossbows would be advantageous."] = "Los demonios menores son algunos de los demonios avernicos más débiles. Se pueden encontrar habitando la mazmorra Karamja. Usar ballestas sería una ventaja.",
        ["The last Wyvern I killed I found fire spells took them down effectively."] = "El último Wyvern que maté descubrí que los hechizos de fuego los derribaron de manera efectiva.",
        ["Living wyverns breathe a poison that will rapidly kill you unless you can freeze your blood using the glacial temperature of their home. But watch out; the colder you are, the harder their regular attacks will hit you. They can be found within the Asgarnia Ice Dungeon."] = "Los wyverns vivos respiran un veneno que te matará rápidamente a menos que puedas congelar tu sangre usando la temperatura glacial de su hogar. Pero cuidado; cuanto más frío tengas, más fuerte te golpearán sus ataques habituales. Se pueden encontrar dentro de la Mazmorra de Hielo de Asgarnia.",
        ["The last Ripper Demon I killed I found earth spells took them down effectively."] = "El último Demonio Destripador que maté encontré que los hechizos de tierra los derribaron de manera efectiva.",
        ["Ripper demons enjoy the bloodlust of battle, a sentiment I can agree with. They will expose your weaknesses, hitting you harder the worse your injuries are. They can be found in a fissure east of Al Kharid."] = "Los demonios destripadores disfrutan de la sed de sangre de la batalla, un sentimiento con el que estoy de acuerdo. Expondrán tus debilidades y te golpearán con más fuerza cuanto peores sean tus lesiones. Se pueden encontrar en una fisura al este de Al Kharid.",
        ["These tortured spirits have been risen from the dead by Zemouregal and are bound to his will. You can find risen ghosts inhabiting the depths within the crypts north of Fort Forinthry, waiting for Zemouregal's command. You'll find bows effective against this target."] = "Estos espíritus torturados han sido resucitados por Zemouregal y están sujetos a su voluntad. Puedes encontrar fantasmas resucitados que habitan en las profundidades de las criptas al norte de Fort Forinthry, esperando la orden de Zemouregal. Encontrarás arcos efectivos contra este objetivo.",
        ["You can find many types of skeletons around Gielinor, notably those flooding the crypts north of Fort Forinthry."] = "Puedes encontrar muchos tipos de esqueletos alrededor de Gielinor, en particular los que inundan las criptas al norte de Fort Forinthry.",
        ["You can find many types of undead around Gielinor, notably those festering inside the crypts north of Fort Forinthry."] = "Puedes encontrar muchos tipos de muertos vivientes alrededor de Gielinor, en particular los que se pudren dentro de las criptas al norte de Fort Forinthry.",
        ["Undead raised by the necromancer Zemouregal. They lurk in the crypt north of Fort Forinthry."] = "No-muerto criado por el nigromante Zemouregal. Acechan en la cripta al norte de Fort Forinthry.",
        ["You can find many types of zombies around Gielinor, notably those flooding the crypts north of Fort Forinthry."] = "Puedes encontrar muchos tipos de zombis alrededor de Gielinor, en particular los que inundan las criptas al norte de Fort Forinthry.",
    },
    ["The Sage"] = {
        ["Hello, mortal. What do you seek?"] = "Hola, mortal. ¿Qué buscas?",
        ["Select an Option"] = "Selecciona una opción",
        ["Can you tell me what is going on?"] = "¿Puedes decirme qué está pasando?",
        ["Some time ago, an ancient and powerful artefact was destroyed. The Stone of Jas."] = "Hace algún tiempo, un artefacto antiguo y poderoso fue destruido. La Piedra de Jas.",
        ["Though formless, its energies and magic endured, scattered and unseen."] = "Aunque no tiene forma, sus energías y magia perduraron, dispersas e invisibles.",
        ["Over time, that power coalesced once more into something new. Relics."] = "Con el tiempo, ese poder se fusionó una vez más en algo nuevo. Reliquias.",
        ["These Relics hold mere fragments of the Stone's former power."] = "Estas Reliquias contienen meros fragmentos del antiguo poder de la Piedra.",
        ["Yet even a fragment grants powers unlike anything you've encountered before."] = "Sin embargo, incluso un fragmento otorga poderes diferentes a todo lo que hayas encontrado antes.",
        ["Is there anything else you need from me?"] = "¿Hay algo más que necesites de mí?",
        ["You have arrived in a world thrown out of balance."] = "Has llegado a un mundo desequilibrado.",
        ["The life force of Gielinor, its anima mundi, is being torn apart by the battling forces of order and chaos."] = "La fuerza vital de Gielinor, su anima mundi, está siendo destrozada por las fuerzas del orden y el caos.",
        ["Guthix has dreamt of the terrible consequences of this conflict. His decree is this: If we wish to avoid disaster, heroes like yourself must work to heal the anima mundi, and restore the balance."] = "Guthix ha soñado con las terribles consecuencias de este conflicto. Su decreto es el siguiente: si queremos evitar el desastre, los héroes como tú deben trabajar para curar el anima mundi y restaurar el equilibrio.",
        ["As it is restored from its fragmented state, the anima mundi will transmute into Relics. A concentrated source of formidable power. Power that will be gifted to you."] = "A medida que se restablezca de su estado fragmentado, el anima mundi se transmutará en reliquias. Una fuente concentrada de poder formidable. Poder que te será regalado.",
        ["How you seek to use that power, for order or chaos, for good or ill, will be up to you."] = "La forma en que busques usar ese poder, para el orden o el caos, para bien o para mal, dependerá de ti.",
        ["Can you tell me about tasks?"] = "¿Puedes contarme sobre las tareas?",
        ["In every League, there are a number of tasks for you to complete. Each task has a level of difficulty: Easy, Medium, Hard, Elite and Master."] = "En cada liga, hay una serie de tareas que debes completar. Cada tarea tiene un nivel de dificultad: Fácil, Medio, Difícil, Élite y Maestro.",
        ["Completing tasks earns you League Points. The number of points earned is independent on the difficulty of the task."] = "Completar tareas te otorga puntos de liga. La cantidad de puntos obtenidos es independiente de la dificultad de la tarea.",
        ["What do these points do?"] = "¿Qué hacen estos puntos?",
        ["Once you have achieved a certain amount of League Points you can unlock a new Relic of mine. These are powerful artefacts to help you in this world."] = "Una vez que hayas alcanzado una cierta cantidad de puntos de liga, podrás desbloquear una nueva reliquia mía. Estos son artefactos poderosos que te ayudarán en este mundo.",
        ["League Points can also be used to buy rewards from the Leagues Reward Shop once the League ends."] = "Los puntos de liga también se pueden usar para comprar recompensas en la tienda de recompensas de ligas una vez que finaliza la liga.",
        ["[Currently you are playing on your Leagues profile. The Leagues Reward Shop can only be opened on your main profile once the League ends.]"] = "[Actualmente estás jugando en tu perfil de Ligas. La Tienda de recompensas de Ligas solo se puede abrir en tu perfil principal una vez que finaliza la Liga.]",
        ["[You can access your main profile at any time by changing to a regular world.]"] = "[Puedes acceder a tu perfil principal en cualquier momento cambiando a un mundo normal.]",
        ["[Currently you are playing on your Leagues profile. The Leagues Reward Shop can only be previewed during Leagues, and can be opened on your main profile once the League ends.]"] = "[Actualmente estás jugando en tu perfil de Ligas. La tienda de recompensas de Ligas solo se puede obtener una vista previa durante las Ligas y se puede abrir en su perfil principal una vez que finaliza la Liga.]",
        ["So how many tasks are there?"] = "Entonces, ¿cuántas tareas hay?",
        ["More than you'll be able to complete, most likely. It's up to you which ones you attempt."] = "Lo más probable es que sean más de los que podrás completar. Depende de usted cuáles intentar.",
        ["Thanks!"] = "¡Gracias!",
        ["Now, would you like to take a look at the tasks for this League?"] = "Ahora, ¿te gustaría echar un vistazo a las tareas de esta Liga?",
        ["Yes, please."] = "Sí, por favor.",
        ["Not right now."] = "No ahora mismo.",
        ["Can you tell me about relics?"] = "¿Puedes hablarme de reliquias?",
        ["Relics are powerful artefacts that grant unique abilities for the entire League."] = "Las reliquias son artefactos poderosos que otorgan habilidades únicas para toda la Liga.",
        ["You may even recognise a few from an older RuneScape."] = "Quizás incluso reconozcas algunos de un RuneScape más antiguo.",
        ["Relics are separated into tiers, where you can claim only one from each tier."] = "Las reliquias están separadas en niveles, donde solo puedes reclamar una de cada nivel.",
        ["The first Relic tier is available to everyone. The others must be unlocked with League Points."] = "El primer nivel de Reliquia está disponible para todos. Los demás deben desbloquearse con Puntos de Liga.",
        ["League Points are earned by completing tasks."] = "Los puntos de liga se obtienen al completar tareas.",
        ["Once you have selected a Relic, you choice can't be changed for the rest of the League. Make your choices carefully."] = "Una vez que hayas seleccionado una Reliquia, tu elección no se podrá cambiar durante el resto de la Liga. Haga sus elecciones con cuidado.",
        ["Now, would you like to take a look at the relics for this League?"] = "Ahora, ¿te gustaría echar un vistazo a las reliquias de esta Liga?",
        ["Can you tell me about relics and blessings?"] = "¿Puedes hablarme de reliquias y bendiciones?",
        ["Relics are powerful artefacts that grant unique abilities for the entire League. You may even recognise a few from an older RuneScape."] = "Las reliquias son artefactos poderosos que otorgan habilidades únicas para toda la Liga. Incluso puedes reconocer algunos de un RuneScape más antiguo.",
        ["Relics are separated into tiers, where you may claim only one from each tier."] = "Las reliquias están separadas en niveles, donde solo puedes reclamar una de cada nivel.",
        ["The first Relic tier is available to everyone. The others must be unlocked with League Points, which are earned by completing tasks."] = "El primer nivel de Reliquia está disponible para todos. Los demás deben desbloquearse con Puntos de Liga, que se obtienen al completar tareas.",
        ["Blessings are powers and abilities unlocked by completing special combat tasks."] = "Las bendiciones son poderes y habilidades que se desbloquean al completar tareas de combate especiales.",
        ["Each blessing is aligned with Order, Balance or Chaos. As you unlock higher tier Blessings, the gods will cast their judgement on your choices, and new God Relics will be revealed to you."] = "Cada bendición está alineada con el Orden, el Equilibrio o el Caos. A medida que desbloqueas Bendiciones de niveles superiores, los dioses juzgarán tus elecciones y se te revelarán nuevas Reliquias de Dios.",
        ["Once you have selected a Relic, your choice can't be changed for the rest of the League. Make your choices carefully."] = "Una vez que hayas seleccionado una Reliquia, tu elección no se podrá cambiar durante el resto de la Liga. Haga sus elecciones con cuidado.",
        ["You will have limited  to reset your choice of Blessings, should you wish to change your mind."] = "Tendrás un límite para restablecer tu elección de Bendiciones, en caso de que desees cambiar de opinión.",
        ["Now, would you like to take a look at the relics and blessings for this League?"] = "Ahora, ¿te gustaría echar un vistazo a las reliquias y bendiciones de esta Liga?",
        ["Select an option"] = "Selecciona una opción",
        ["Show me the Relics."] = "Muéstrame las reliquias.",
        ["Show me the Blessings."] = "Muéstrame las Bendiciones.",
        ["Do I have any items to reclaim?"] = "¿Tengo algún artículo para reclamar?",
        ["That's all for now."] = "Eso es todo por ahora.",
        ["Very well. I'll be here if you ever need to know anything more."] = "Muy bien. Estaré aquí si alguna vez necesitas saber algo más.",
        ["I am busy with the current League. I may assist you on a League world, or here once the League has concluded."] = "Estoy ocupado con la Liga actual. Puedo ayudarte en un mundo de la Liga o aquí una vez que la Liga haya concluido.",
        ["Choose an option:"] = "Elige una opción:",
        ["Can I import my League points?"] = "¿Puedo importar mis puntos de Liga?",
        ["Import from 'Player'."] = "Importar desde 'Player'.",
        ["Please wait a moment, retrieving your rewards is a delicate process."] = "Espere un momento, recuperar sus recompensas es un proceso delicado.",
        ["You have already imported all League points this account has earned."] = "Ya importaste todos los puntos de Liga que obtuvo esta cuenta.",
        ["Import from a nominated account."] = "Importar desde una cuenta designada.",
        ["The profile of '[name]' could not be loaded. Please try again later."] = "No se pudo cargar el perfil de '[name]'. Inténtelo de nuevo más tarde.",
        ["You {{Sic load the League rewards of 'Player'.|colour=#EB2F2F}}"] = "Tu {{Sic load the League rewards of 'Player'.|colour=#EB2F2F}}",
        ["Nevermind."] = "No importa.",
        ["Can I spend my League points?"] = "¿Puedo gastar mis puntos de Liga?",
        ["You have not yet imported any points. Would you like to do so before viewing the shop?"] = "Aún no has importado ningún punto. ¿Quieres hacerlo antes de visitar la tienda?",
        ["Import progress now."] = "Importa el progreso ahora.",
        ["I want to see the shop anyway."] = "Quiero ver la tienda de todos modos.",
        ["Can I change my badge?"] = "¿Puedo cambiar mi placa?",
        ["Apply 'Dragon trophy' badge."] = "Aplicar la insignia 'Trofeo Dragón'.",
        ["Badge changed to: File:Dragon trophy badge.png Player."] = "Insignia cambiada a: Archivo: Trofeo del dragón badge.png Player.",
        ["Clear badge."] = "Insignia clara.",
        ["Your badge has been cleared."] = "Su placa ha sido borrada.",
        ["I've changed my mind."] = "He cambiado de opinión.",
        ["You lack the backpack space to reclaim any items. Free up some space and only then shall I check."] = "Te falta espacio backpack para reclamar cualquier artículo. Libera algo de espacio y sólo entonces lo comprobaré.",
        ["All relic powers I have bestowed upon you remain in your possession."] = "Todos los poderes de reliquia que te he otorgado permanecen en tu poder.",
        ["You need to unlock a higher tier of relic to do this."] = "Necesitas desbloquear un nivel superior de reliquia para hacer esto.",
        ["Which would you like to switch?"] = "¿Cuál te gustaría cambiar?",
        ["Prayers."] = "Rezo.",
        ["Change from prayers to curses?"] = "¿Cambiar de oraciones a maldiciones?",
        ["Yes, replace my prayers with curses."] = "Sí, reemplaza mis oraciones con maldiciones.",
        ["[The altar fills your head with dark thoughts, purging the prayers from your memory and leaving only curses in their place.]"] = "[El altar llena tu cabeza con pensamientos oscuros, purgando las oraciones de tu memoria y dejando solo maldiciones en su lugar.]",
        ["Yes, and allow me to switch back at other altars."] = "Sí, y permítanme volver a otros altares.",
        ["Never mind."] = "No importa.",
        ["Change from curses to prayers?"] = "¿Cambiar de maldiciones a oraciones?",
        ["Yes, replace my curses with prayers."] = "Sí, reemplaza mis maldiciones con oraciones.",
        ["[The altar eases its grip on your mind. The curses slip from your memory and you recall the prayers you used to know.]"] = "[El altar alivia su control sobre tu mente. Las maldiciones se te escapan de la memoria y recuerdas las oraciones que solías saber.]",
        ["Yes, and allow me to do this at any altar."] = "Sí, y permíteme hacer esto en cualquier altar.",
        ["Spells."] = "Hechizos.",
        ["You cannot access additional spellbooks until you unlock them."] = "No puedes acceder a libros de hechizos adicionales hasta que los desbloquees.",
        ["Choose your spellbook"] = "Elige tu libro de hechizos",
        ["Normal."] = "Normalidad.",
        ["Ancient."] = "Antiguo.",
        ["Lunar."] = "lunares.",
        ["Not now. Come see me once the League has concluded."] = "Ahora no. Ven a verme una vez concluida la Liga.",
    },
    ["The Sanctum Guardian"] = {
        ["*At the start of the fight:*"] = "*Al inicio de la pelea:*",
        ["*When below 75% lifepoints:*"] = "*Cuando estés por debajo del 75 % de puntos de vida:*",
        ["*When below 25% lifepoints:*"] = "*Cuando estés por debajo del 25 % de puntos de vida:*",
        ["A fishy treat? It may pass!"] = "¿Una delicia a pescado? ¡Puede pasar!",
    },
    ["The Spirit of Accomplishment"] = {
        ["I'm not yet accomplished enough as a necromancer to buy a skillcape..."] = "Todavía no he logrado lo suficiente como nigromante para comprar un skillcape...",
        ["Buy Necromancy skillcape?"] = "¿Comprar Necromancy skillcape?",
        ["Yes."] = "Sí.",
        ["[The spirit takes your cape inversion token.]"] = "[El espíritu toma tu ficha de inversión de capa.]",
        ["Choose an option:"] = "Elige una opción:",
        ["92,000 coins? That's much too expensive."] = "¿92.000 coins? Eso es demasiado caro.",
        ["I know where to find you if I change my mind."] = "Sé dónde encontrarte si cambio de opinión.",
        ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
        ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
        ["Oh, I don't have enough coins to buy this."] = "Oh, no tengo suficiente coins para comprar esto.",
        ["Ah, I need room for both the cape and the hood."] = "Ah, necesito espacio tanto para la capa como para la capucha.",
        ["Excellent! I will wear this cape with pride."] = "¡Excelente! Usaré esta capa con orgullo.",
        ["I'd like a skillcape with the colours inverted."] = "Me gustaría un skillcape con los colores invertidos.",
    },
    ["The Spirit of Mastery"] = {
        ["I haven't mastered necromancy yet, so I can't buy a master cape..."] = "Aún no domino la nigromancia, así que no puedo comprar un master cape...",
        ["[The spirit takes your cape inversion token.]"] = "[El espíritu toma tu ficha de inversión de capa.]",
        ["Select an Option"] = "Selecciona una opción",
        ["I would like a normal master cape."] = "Me gustaría un master cape normal.",
        ["I would like an inverted master cape."] = "Me gustaría un master cape invertido.",
        ["Buy Necromancy master cape for 120,000 coins?"] = "¿Comprar Necromancy master cape por 120.000 coins?",
        ["Yes."] = "Sí.",
        ["I do not have enough room in my backpack. I should come back when I have some more."] = "No tengo suficiente espacio en mi backpack. Debería volver cuando tenga más.",
        ["You do not have enough money to purchase this cape."] = "No tienes suficiente dinero para comprar esta capa.",
    },
    ["The Tengu"] = {
        ["Haha! Hello, Portmaster!"] = "¡Jaja! ¡Hola capitán de puerto!",
        ["How goes the legend of Sojobo?"] = "¿Cómo va la leyenda de Sojobo?",
        ["*Before Tetsu-Oni*"] = "*Antes de Tetsu-Oni*",
        ["To be honest, without any demons to vanquish or ghosts to lay to rest, I get a bit bored."] = "Para ser honesto, sin demonios que vencer ni fantasmas que descansar, me aburro un poco.",
        ["(mumble)"] = "(murmullo)",
        ["Shanao says 'hello'."] = "Shanao dice \"hola\".",
        ["*After Tetsu-Oni*"] = "*Después de Tetsu Oni*",
        ["Shanao's head is still ringing from our fight with the oni, but the other oni will think twice before launching any new attacks."] = "La cabeza de Shanao todavía suena por nuestra pelea con el oni, pero los otros oni lo pensarán dos veces antes de lanzar nuevos ataques.",
        ["*After Spirits in the Sky*"] = "*Después de Espíritus en el cielo*",
        ["We're both a bit melancholy right now, in remembrance of the sky orphans."] = "Ambos estamos un poco melancólicos en este momento, en recuerdo de los huérfanos del cielo.",
        ["*After Dove from Above*"] = "*Después de Paloma desde Arriba*",
        ["Shanao is furious with thoughts of Benkei.  I've been playing some pranks to cheer him up...but it’s not working."] = "Shanao está furioso al pensar en Benkei.  Le he estado gastando algunas bromas para animarlo... pero no funciona.",
        ["*After A Cloud on the Horizon*"] = "*Después de Una nube en el horizonte*",
        ["You should hear Shanao recounting our fight with Benkei - he's not been this enthusiastic about anything in years!"] = "Deberías escuchar a Shanao contar nuestra pelea con Benkei: ¡hace años que no se muestra tan entusiasmado con nada!",
        ["*After A Bird in the Hand*"] = "*Después de Un pájaro en la mano*",
        ["I am concerned about Benkei's safety...but we must discover what Kakashi is planning."] = "Me preocupa la seguridad de Benkei... pero debemos descubrir qué está planeando Kakashi.",
        ["*After Lament of the Sea*"] = "*Después del Lamento del Mar*",
        ["I have been studying my knowledge, and consulting the Way of Gu...but I've found no mention of Kami-shima. It is most puzzling."] = "He estado estudiando mis conocimientos y consultando el Camino de Gu... pero no encontré ninguna mención de Kami-shima. Es de lo más desconcertante.",
        ["*After Gu: Masters of the Magic Mountain*"] = "*Después de Gu: Maestros de la montaña Magic*",
        ["Benkei was our nemesis for years, and a loyal servant just a handful of days. He was a villain, but we were beginning to understand the man. Is it strange that I now mourn his death?"] = "Benkei fue nuestro némesis durante años y un servidor leal solo durante unos días. Era un villano, pero estábamos empezando a entender al hombre. ¿Es extraño que ahora llore su muerte?",
        ["*After Guardians of the World*"] = "*Después de Guardianes del Mundo*",
        ["Kami-shima has brought life back to this old bird! It will sustain us for many a year to come, so the legend of Sojobo..."] = "¡Kami-shima le ha devuelto la vida a este viejo pájaro! Nos sustentará durante muchos años más, por eso la leyenda de Sojobo...",
        [" (mumble)"] = " (murmullo)",
        ["The legend of Sojobo AND Shanao continues!"] = "¡La leyenda de Sojobo Y Shanao continúa!",
        ["Also the pranks..."] = "También las bromas...",
        ["About your voyages..."] = "Sobre tus viajes...",
        ["If you ever need help, do not hesitate to ask."] = "Si alguna vez necesitas ayuda, no dudes en preguntar.",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["*With the Convict unlocked*"] = "*Con the Convict desbloqueado*",
        ["I would love to have a conversation about theft with that Convict fellow. I think I can set him back on a righteous path!"] = "Me encantaría tener una conversación sobre robo con ese tipo Convicto. ¡Creo que puedo devolverlo al camino recto!",
        ["If both the Tengu and Convict are in port at the same time, additional joint voyages will be made available."] = "Si tanto the Tengu como Convict están en puerto al mismo tiempo, estarán disponibles viajes conjuntos adicionales.",
        ["Played any good pranks lately?"] = "¿Has hecho alguna buena broma últimamente?",
        ["Haha! Of course! I've set up the perfect prank involving henna, a golem head and a parrot."] = "¡Jaja! ¡Por supuesto! He preparado la broma perfecta con henna, una cabeza de golem y un loro.",
        ["Oh, who are you pranking?"] = "Oh, ¿a quién le estás bromeando?",
        ["Oh, actually, forget I said anything... And...er...don't use your scrimshaw station for a while."] = "Oh, en realidad, olvida que dije algo... Y... eh... no uses tu estación de scrimshaw por un tiempo.",
        ["[View previous cutscenes]"] = "[Ver escenas anteriores]",
        ["Meet the Tengu"] = "Conoce a the Tengu",
        ["Tetsu-Oni"] = "Tetsu Oni",
        ["Spirits in the Sky"] = "Espíritus en el cielo",
        ["Dove from Above"] = "Paloma desde arriba",
        ["More"] = "Más",
        ["A Cloud on the Horizon"] = "Una nube en el horizonte",
        ["A Bird in the Hand"] = "Un pájaro en la mano",
        ["Lament of the Sea"] = "Lamento del mar",
        ["Shanao is cut off for tonight. He has to fly us home!"] = "Shanao está cortado por esta noche. ¡Tiene que llevarnos a casa!",
        ["I have no need of services. Take your wares elsewhere, good man!"] = "No necesito servicios. ¡Lleva tus mercancías a otra parte, buen hombre!",
        ["Looking for work? I have contracts for you to complete in this region, and I'll reward you for them."] = "¿Buscas trabajo? Tengo contracts para que los completes en esta región y te recompensaré por ello.",
        ["What are contracts?"] = "¿Qué son contracts?",
        ["Hoho! Well, from me at least, they are a form of charity. The organisation that I belong to is altruistic and charitable. We seek to make Wushanko safe for the just, to protect the innocent and smite evil in all its forms. My contracts will give focus to any that wish to lend a hand towards these goals, ridding this region of evildoers and gathering supplies for the needy. Some of my contracts require you to gather materials or fashion them into specific items. I don't require you to give me them to fulfil a contract. You may donate these supplies to those less fortunate than yourself at your convenience. There are other, more specialised, contract givers to be found in these parts, whose reasons are their own. My contracts, however, are more rewarding! Any questions?"] = "¡Hoho! Bueno, al menos para mí, son una forma de caridad. La organización a la que pertenezco es altruista y caritativa. Buscamos hacer que Wushanko sea seguro para los justos, proteger a los inocentes y acabar con el mal en todas sus formas. Mi contracts se centrará en cualquiera que desee ayudar a alcanzar estos objetivos, librando a esta región de malhechores y reuniendo suministros para los necesitados. Algunos de mis contracts requieren que recopiles materiales o los transformes en artículos específicos. No necesito que me los des para cumplir un contrato. Puede donar estos suministros a personas menos afortunadas que usted cuando le convenga. Hay otros contratistas más especializados por estos lares, cuyas razones son propias. ¡Mis contracts, sin embargo, son más gratificantes! ¿Alguna pregunta?",
        ["Tell me about contracts."] = "Háblame de contracts.",
        ["There is a limit to how many can be completed on any given day. The Way of Gu teaches us that an excess of charity often leads to a development of selfishness. Charity is for the sake of others, not for personal fulfillment. I will only offer you contracts that you are capable of completing, but should you wish a different one, then I shall do so...for a small cost of chimes. Some contracts can be completed on the various islands of this region, but you will most likely want or need to visit the uncharted islands to do the greatest amount of good. Completed contracts should be returned to me, at which point I shall reward you with a wealth of the Gu's knowledge and experience."] = "Hay un límite en cuanto a la cantidad que se puede completar en un día determinado. El Camino de Gu nos enseña que un exceso de caridad a menudo conduce a un desarrollo del egoísmo. Charity es por el bien de los demás, no por la realización personal. Sólo te ofreceré contracts que seas capaz de completar, pero si deseas uno diferente, lo haré... por un pequeño costo en campanas. Algunos contracts se pueden completar en las distintas islas de esta región, pero lo más probable es que quieras o necesites visitar las islas inexploradas para hacer el mayor bien. Deberías devolverme el contracts completo, momento en el que te recompensaré con una gran cantidad de conocimientos y experiencia de Gu.",
        ["Why do you charge me to re-roll contracts?"] = "¿Por qué me cobran por volver a lanzar contracts?",
        ["Aha! That money is collected as a charitable donation to the Gu, which we put towards spreading our creed around these islands, training new Gu recruits and such. In return, we handsomely reward you with our knowledge and experience!"] = "¡Ajá! Ese dinero se recauda como una donación caritativa a los Gu, que destinamos a difundir nuestro credo en estas islas, capacitar a nuevos reclutas Gu y demás. ¡A cambio, le recompensaremos generosamente con nuestro conocimiento y experiencia!",
        ["Can you tell me about the Gu?"] = "¿Puedes hablarme sobre el Gu?",
        ["Tell me about the Gu."] = "Háblame del Gu.",
        ["The Gu have humble origins - a group of ten like-minded individuals banded together to protect a small town from attack by a group of bird-demons. Each of the ten brought a different skill to the group, and each of them were pivotal to the success of their defence. After saving that village, the locals wished for them to remain, to live among them as saviours and friends. Thus the Gu were born. Those ten saviours became the first of the great Gu sages, each of them seeking to master their disciplines, and teaching their new neighbours of their expertise. Word spread, and many pilgrims made their way to the village to learn from these great sages. Before long, the Gu sent out envoys and started to spread their knowledge and charity beyond that village and the island it stood on. The ten Gu sages created a charter for how these envoys should conduct themselves in the world - the Way of Gu - a guiding principle for all who followed in their footsteps."] = "Los Gu tienen orígenes humildes: un grupo de diez personas con ideas afines se unieron para proteger un pequeño pueblo del ataque de un grupo de pájaros-demonio. Cada uno de los diez aportó una habilidad diferente al grupo, y cada uno de ellos fue fundamental para el éxito de su defensa. Después de salvar esa aldea, los lugareños desearon que se quedaran y vivieran entre ellos como salvadores y amigos. Así nacieron los Gu. Esos diez salvadores se convirtieron en los primeros de los grandes sabios Gu, cada uno de los cuales buscaba dominar sus disciplinas y enseñar su experiencia a sus nuevos vecinos. Se corrió la voz y muchos peregrinos se dirigieron al pueblo para aprender de estos grandes sabios. Al poco tiempo, los Gu enviaron enviados y comenzaron a difundir su conocimiento y caridad más allá de esa aldea y la isla en la que se encontraba. Los diez sabios Gu crearon una carta sobre cómo deberían comportarse estos enviados en el mundo: el Camino de Gu, un principio rector para todos los que siguieron sus pasos.",
        ["What is the Way of Gu?"] = "¿Cuál es el Camino de Gu?",
        ["The Way of Gu are the tenets by which we conduct ourselves in this world. It consists of ten ways in which one can view the world, and seek to make it a better place for all. Gu initiates must learn all of the Ten Ways at first. Once they have an understanding of them all, many will choose one particular Way to follow and find a master of that Way to teach them further. After years of study, a student can become a master, and masters that have tutored many can become grandmasters. Whenever one great sage passes from this mortal coil, the most senior grandmasters will take their place."] = "El Camino de Gu son los principios según los cuales nos comportamos en este mundo. Consta de diez formas en las que uno puede ver el mundo y tratar de convertirlo en un lugar mejor para todos. Los iniciados Gu deben aprender los Diez Caminos al principio. Una vez que los comprendan todos, muchos elegirán un Camino en particular a seguir y encontrarán un maestro de ese Camino para enseñarles más. Después de años de estudio, un estudiante puede convertirse en un maestro, y los maestros que han sido tutores de muchos pueden convertirse en grandes maestros. Cada vez que un gran sabio sale de esta espiral mortal, los grandes maestros de mayor rango ocuparán su lugar.",
        ["What are the Ten Ways?"] = "¿Cuáles son los Diez Caminos?",
        ["The Way of the Warrior is the simplest, to master the martial arts in order to protect those that cannot protect themselves. The Way of the Scholar is to learn about the world from the written and spoken word, and then to spread that knowledge to others. In contrast, the Way of the Wanderer is to learn about the world from first-hand experience, through adventure and travel. Then there are the arts, starting with the Way of the Artist, spreading joy and knowledge through artistic expression. Of a similar vein is the Way of the Musician, using music and song to remember the past and celebrate the present. Though those who do not understand it see it not as another art, there is also the Way of the Prankster. Humour is the great healer. And the last of the arts is the Way of the Orator - actors, public speakers and tellers of stories. There are also crafts, such as the Way of the Maker - makers of armour, folders of swords, builders for boats. The Way of the Gourmand is a mix of art and craft, perfecting recipes, but also helping to feed the hungry. And finally is the Way of the Spirit, experts in ghost-hunting, performers of the last rites and our healers."] = "El Camino del Guerrero es el más sencillo, dominar las artes marciales para proteger a aquellos que no pueden protegerse a sí mismos. El Camino del Erudito es aprender sobre el mundo a través de la palabra escrita y hablada, y luego difundir ese conocimiento a otros. Por el contrario, el Camino del Errante consiste en aprender sobre el mundo a partir de experiencias de primera mano, a través de aventuras y viajes. Luego están las artes, empezando por el Camino del Artista, difundiendo alegría y conocimiento a través de la expresión artística. De una línea similar es el Camino del Musician, que utiliza música y canciones para recordar el pasado y celebrar el presente. Aunque quienes no lo entienden no lo ven como un arte más, también existe el Camino del Bromista. El humor es el gran sanador. Y la última de las artes es el Camino del Orador: actores, oradores públicos y narradores de historias. También hay oficios, como el Camino del Hacedor: fabricantes de armaduras, plegadores de espadas, constructores de barcos. El Camino del Gourmand es una mezcla de arte y artesanía, que perfecciona recetas, pero también ayuda a alimentar a los hambrientos. Y finalmente está el Camino de los Spirit, expertos en caza de fantasmas, realizadores de la extremaunción y nuestros curanderos.",
        ["Phew! That's a lot to take in! Which Way do you ascribe to?"] = "¡Uf! ¡Eso es mucho para asimilar! ¿A qué camino te adscribes?",
        ["Aha, but I am unique. I am the Tengu, the embodiment of the Ten Ways, and master of all."] = "Ajá, pero soy único. Soy the Tengu, la encarnación de los Diez Caminos y el maestro de todo.",
        ["No. I'm good."] = "No, estoy bien.",
        ["*(dialogue ends)*"] = "*(termina el diálogo)*",
    },
    ["The Trader"] = {
        ["The Trader has no goods for sale at the moment. Check back once you have completed the Port tutorial."] = "The Trader no tiene productos a la venta en este momento. Vuelva a consultar una vez que haya completado el tutorial de Puerto.",
        ["Select an Option"] = "Selecciona una opción",
        ["What do you do around here?"] = "¿Qué haces por aquí?",
        ["I can trade your extra resources for some goods."] = "Puedo cambiar tus recursos adicionales por algunos bienes.",
        ["I'll change my offer now and again, so come back often."] = "Cambiaré mi oferta de vez en cuando, así que vuelve con frecuencia.",
        ["I would like to trade."] = "Me gustaría negociar.",
        ["Let's see what I have for you."] = "Veamos qué tengo para ti.",
        ["I must be going."] = "Debo irme.",
        ["If you change your mind, come back. This offer won't last forever."] = "Si cambias de opinión, vuelve. Esta oferta no durará para siempre.",
    },
    ["The Trapper"] = {
        ["Greetings! Can I help you?"] = "¡Saludos! ¿Puedo ayudarle?",
        ["How are things going, Reginald?"] = "¿Cómo van las cosas, Reginald?",
        ["*Before Tally-ho!*"] = "*¡Antes de Tally-ho!*",
        ["I hope this new hunting ground is as good as your crew made it out to be!"] = "¡Espero que este nuevo coto de caza sea tan bueno como lo hizo tu equipo!",
        ["*After Tally-ho!*"] = "*¡Después de Tally-ho!*",
        ["Hm, that chinchompa was a lively foe. Not quite as dangerous as that horned graahk I fended off with a stick, though."] = "Hm, esa chinchompa era un enemigo vivaz. Aunque no es tan peligroso como ese graahk con cuernos que rechacé con un palo.",
        ["*After My Bear Hands*"] = "*Después de Mis manos de oso*",
        ["I'd like to have another have another [sic] shot at that fearsome bear. But this vanishing creature intrigues me!"] = "Me gustaría que otro tuviera otra oportunidad [sic] contra ese temible oso. ¡Pero esta criatura que desaparece me intriga!",
        ["*After Know Thy Enemy*"] = "*Después de conocer a tu enemigo*",
        ["Deep in the snowy lands near Rellekka I once fought a sabretooth kyatt. They were difficult to spot...but were not invisible."] = "En lo profundo de las tierras nevadas cerca de Rellekka, una vez luché contra un kyatt dientes de sable. Eran difíciles de detectar... pero no eran invisibles.",
        ["*After Warfare Is Based on Deception*"] = "*Después de la guerra se basa en el engaño*",
        ["I hope you're not going to slow me down with nannies next time I go out!"] = "¡Espero que no me frenes con las niñeras la próxima vez que salga!",
        ["*After Theories Abound*"] = "*Después de que abundan las teorías*",
        ["I have returned! I needed to restock supplies and enjoy the hospitality of your fabulous bar!"] = "¡He regresado! ¡Necesitaba reponer suministros y disfrutar de la hospitalidad de su fabuloso bar!",
        ["*After Reinforcement*"] = "*Después del refuerzo*",
        ["Those miners are having a hard time out there! I showed them the move I used to arm wrestle a bear. For self-defence, of course."] = "¡Esos mineros lo están pasando mal! Les mostré el movimiento que usaba para luchar contra un oso. Por supuesto, en defensa propia.",
        ["*After Once More Into the Breach & Recipe Number 132: Fresh Idea*"] = "*Después de Una vez más en la brecha y la receta número 132: nueva idea*",
        ["I was wondering if these creatures are too much for me to handle. Then I remembered that I'm Reginald Wellington-Smythe!"] = "Me preguntaba si estas criaturas son demasiado para mí. ¡Entonces recordé que soy Reginald Wellington-Smythe!",
        ["I'm in need of someone with your skills."] = "Necesito a alguien con tus habilidades.",
        ["Tally ho! What are we waiting for? Let's get to it!"] = "¡Cuenta hola! ¿Qué estamos esperando? ¡Vamos a ello!",
        ["*Voyage screen opens*"] = "*Se abre la pantalla de viaje*",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["*Without the Assassin unlocked*"] = "*Sin the Assassin desbloqueado*",
        ["I'd work with someone who does all that being stealthy stuff. I hear some people swear by it out east."] = "Trabajaría con alguien que haga todo eso de ser sigiloso. He oído que algunas personas lo confían en él en el este.",
        ["*With the Assassin unlocked and not present*"] = "*Con the Assassin desbloqueado y no presente*",
        ["I could work with that assassin woman. I might learn a trick or two about stealth - maybe I can pick something up!"] = "Podría trabajar con esa mujer asesina. Quizás aprenda uno o dos trucos sobre el sigilo... ¡tal vez pueda aprender algo!",
        ["If both the Trapper and Assassin are in port at the same time, additional joint voyages will be made available."] = "Si tanto the Trapper como Assassin están en el puerto al mismo tiempo, estarán disponibles viajes conjuntos adicionales.",
        ["How is the hunting going?"] = "¿Cómo va la caza?",
        ["Mother loves the trophies I send her. If I accidently have fun wrestling a mountain lion to the ground, then all the better!"] = "A mamá le encantan los trofeos que le envío. Si accidentalmente me divierto tirando a un puma al suelo, ¡mucho mejor!",
        ["[View previous cutscenes]"] = "[Ver escenas anteriores]",
        ["Meet the Trapper"] = "Conoce a the Trapper",
        ["With My Bear Hands"] = "Con mis manos de oso",
        ["Know Thy Enemy"] = "Conoce a tu enemigo",
        ["More"] = "Más",
        ["Warfare Is Based On Deception"] = "La guerra se basa en el engaño",
        ["Theories Abound"] = "Abundan las teorías",
        ["Reinforcement"] = "Refuerzo",
        ["Once More Into the Breach"] = "Una vez más en la brecha",
        ["Recipe Number 132: Fresh Idea"] = "Receta número 132: nueva idea",
        ["I'll have a pint later, my dear."] = "Tomaré una pinta más tarde, querida.",
        ["I don't buy my trophies. Begone!"] = "No compro mis trofeos. ¡Vete!",
        ["Well met, my good [man/lady]! Welcome to Torts R Us. Call me Reggie."] = "¡Bien conocido, mi buen [man/lady]! Bienvenido a Torts R Us. Llámame Reggie.",
        ["Torts R Us? Tell me you're not hunting poor defenceless tortles? I mean - it's not like they can run away - hardly sporting, Reggie."] = "¿Los agravios son nosotros? ¿Dime que no estás cazando pobres tortugas indefensas? Quiero decir, no es que puedan huir... no es nada deportivo, Reggie.",
        ["Oh, of course not. I prefer big game - this is just a side business to earn a few chimes, so that I can fund my next expedition!"] = "Oh, por supuesto que no. Prefiero la caza mayor: ¡esto es solo un negocio secundario para ganar algunas campanadas y poder financiar mi próxima expedición!",
        ["No, we're only interested in tortle shell chippings here. Very versatile substance."] = "No, aquí solo nos interesan las virutas de conchas de tortuga. Sustancia muy versátil.",
        ["I don't know, that still sounds dodgy."] = "No lo sé, eso todavía suena poco fiable.",
        ["We've developed a humane way of harvesting what we need without causing permanent damage. Plus the locals have been running subsistence surveys and whatnot."] = "Hemos desarrollado una forma humana de recolectar lo que necesitamos sin causar daños permanentes. Además, los lugareños han estado realizando encuestas de subsistencia y todo eso.",
        ["No harm comes to them, or my name isn't Reginald Wellington-Smythe."] = "No les pasa nada, o mi nombre no es Reginald Wellington-Smythe.",
        ["That being said, you do need to be a skilled hunter to harvest shell chipping without harming the beasts...and you are not quite there yet, my young buck!"] = "Dicho esto, debes ser un cazador experto para recolectar fragmentos de caparazón sin dañar a las bestias... ¡y aún no has llegado a ese punto, mi joven!",
        ["Want to trade?"] = "¿Quieres comerciar?",
        ["Aha, Portmaster, it's good to see you here on Waiko! Welcome to Torts R Us."] = "¡Ajá, capitán de puerto, qué bueno verte aquí en Waiko! Bienvenido a Torts R Us.",
        ["In fact, you needn't take my word for it, try it for yourself. There's a creep of tortles amassing on Whale's Maw, a perfect hunting ground!"] = "De hecho, no necesitas confiar en mi palabra, pruébalo tú mismo. Hay un montón de tortugas acumulándose en las Fauces de Whale, ¡un coto de caza perfecto!",
        ["Amassing? You make it sound like they're about to invade or something."] = "¿Acumulando? Haces que parezca que están a punto de invadir o algo así.",
        ["Well, maybe not those on Whale's Maw, but I don't trust the rare shiny tortles found out in the uncharted islands. I'll pay handsomely for some shell chippings from those."] = "Bueno, tal vez no las de las Fauces de Whale, pero no confío en las raras y brillantes tortugas que se encuentran en las islas inexploradas. Pagaré generosamente por algunas virutas de concha de esos.",
        ["Choose an option:"] = "Elige una opción:",
        ["Torts R Us."] = "Agravios R nosotros.",
        ["Farewell."] = "Adiós.",
    },
    ["The Violet Lotus"] = {
        ["You are the dust on the stained glass windows..."] = "Eres el polvo de los vitrales...",
        ["Trying to comprehend in a cathedral."] = "Tratando de comprender en una catedral.",
        ["You know not the depth of existence."] = "No conoces la profundidad de la existencia.",
        ["You will never get the chance."] = "Nunca tendrás la oportunidad.",
        ["Goodbye."] = "Adiós.",
    },
    ["The Whaler"] = {
        ["Jumping jellyfish! It's good to see you!"] = "¡Medusa saltadora! ¡Qué bueno verte!",
        ["Select an option"] = "Seleccione una opción",
        ["How are you doing, Hubbub?"] = "¿Cómo estás, alboroto?",
        ["*(Before The Misguide:)*"] = "*(Antes del error:)*",
        ["Oh, not bad. Feeling a bit stranded since my ship went down. I'm sure things will pick up, though."] = "Oh, no está mal. Me siento un poco varado desde que mi barco se hundió. Aunque estoy seguro de que las cosas mejorarán.",
        ["*(After The Misguide:)*"] = "*(Después del error:)*",
        ["A bit blue to be honest. Talking to you about my home and - well, what happened has brought it all flooding back."] = "Un poco azul para ser honesto. Hablar contigo sobre mi casa y... bueno, lo que pasó me ha devuelto todo.",
        ["*(After The Evacuation:)*"] = "*(Después de la evacuación:)*",
        ["I'm worried about ol' Shuma, if truth be told. Something's not right with that girl."] = "Estoy preocupado por el viejo Shuma, a decir verdad. Algo no anda bien con esa chica.",
        ["Believe me, there's nothing more dangerous than a spooked whale."] = "Créeme, no hay nada más peligroso que una ballena asustada.",
        ["*(After Ramraid:)*"] = "*(Después de Ramraid:)*",
        ["Nice of you to ask, matey. I'm just mulling over my plans for how we deal with Shuma. Don't worry, I'm cooking something up that might just be crazy enough to work."] = "Qué amable que preguntes, amigo. Sólo estoy reflexionando sobre mis planes sobre cómo lidiar con Shuma. No te preocupes, estoy cocinando algo que podría ser lo suficientemente loco como para funcionar.",
        ["*(After The Old Man of the Sea:)*"] = "*(Después del Old Man del Mar :)*",
        ["Who'd have thought I could speak with sea monsters? I can't wait to talk to old Shuma; that old girl and I have had some adventures in the past."] = "¿Quién hubiera pensado que podría hablar con monstruos marinos? No puedo esperar para hablar con el viejo Shuma; Esa vieja y yo hemos tenido algunas aventuras en el pasado.",
        ["*(After The Whale Whisperer:)*"] = "*(Después del susurrador de Whale :)*",
        ["I'm grand. Better than grand, even! Who'd have thought me and Shuma would ever be pals? I've got you to thank for that."] = "Estoy genial. ¡Incluso mejor que grandioso! ¿Quién hubiera pensado que Shuma y yo seríamos amigos? Tengo que agradecerte por eso.",
        ["*(After Meet the Partner - Again:)*"] = "*(Después de conocer a the Partner - Otra vez:)*",
        ["I'm raring to go, now we've got Shuma on our side I don't know how Quin can stop us. Shuma and Hubbub - what a pair, eh?"] = "Tengo muchas ganas de empezar, ahora que tenemos a Shuma de nuestro lado, no sé cómo Quin puede detenernos. Shuma y Hubbub... vaya pareja, ¿eh?",
        ["*(After In Memory of Kirau:)*"] = "*(Después En Memoria de Kirau :)*",
        ["I'm just waiting for everything to fall into place now! Soon we'll have Quin's heart on a platter and my people's souls will be put to rest."] = "¡Estoy esperando que todo encaje en su lugar ahora! Pronto tendremos el corazón de Quin en bandeja y las almas de mi pueblo descansarán.",
        ["*(After Assault on Paradise:)*"] = "*(Después del Asalto al Paraíso:)*",
        ["You've come for that hug, haven't you? Oh, I'm fine. I miss Shuma, I'm a little lost without her. But I've got you, and this place. It's sort of like a home away from home, isn't it?"] = "Has venido por ese abrazo, ¿no? Oh, estoy bien. Extraño a Shuma, estoy un poco perdido sin ella. Pero te tengo a ti y a este lugar. Es como un hogar lejos del hogar, ¿no?",
        ["*(If The Whaler has clue voyages available:)*"] = "*(Si The Whaler tiene viajes de pistas disponibles:)*",
        ["About your voyages..."] = "Sobre tus viajes...",
        ["Of course! Anything for a friend."] = "¡Por supuesto! Cualquier cosa por un amigo.",
        ["About clue voyages..."] = "Acerca de los viajes de pistas...",
        ["View all voyages..."] = "Ver todos los viajes...",
        ["*(Voyage list interface opens.)*"] = "*(Se abre la interfaz de lista de viajes.)*",
        ["I could use your help on an expedition."] = "Me vendría bien tu ayuda en una expedición.",
        ["Certainly, certainly! I'll just grab my apparatus and we'll be off."] = "¡Por supuesto, por supuesto! Cogeré mi aparato y nos iremos.",
        ["Do you prefer to work alone?"] = "¿Prefieres trabajar solo?",
        ["*(If The Biologist has not been unlocked:)*"] = "*(Si The Biologist no ha sido desbloqueado:)*",
        ["*(If The Biologist has been unlocked but is not present:)*"] = "*(Si The Biologist ha sido desbloqueado pero no está presente:)*",
        ["I've seen a little lady - Bethan, I think she's called - a scientist of some sort. I wouldn't mind working with her, when she's about."] = "He visto a una pequeña dama, Bethan, creo que se llama, una científica de algún tipo. No me importaría trabajar con ella, cuando esté por aquí.",
        ["If both the Biologist and Whaler are in port at the same time, additional joint voyages will be made available."] = "Si tanto the Biologist como Whaler están en puerto al mismo tiempo, estarán disponibles viajes conjuntos adicionales.",
        ["*(If The Biologist has been unlocked and she is present:)*"] = "*(Si The Biologist ha sido desbloqueado y ella está presente:)*",
        ["I reckon Bethan and I would make a good team. With her know-how and my..."] = "Creo que Bethan y yo haríamos un buen equipo. Con su saber hacer y mi...",
        ["...and your aptitude for taking a beating without dying,"] = "...y tu aptitud para recibir una paliza sin morir,",
        ["How's the whaling going?"] = "¿Cómo va la caza de ballenas?",
        ["The whaling? Oh fine, fine. Well, it's just catching big fish, isn't it? And if the rumours are true, I reckon you could teach me a thing or two about that. ¡"] = "¿La caza de ballenas? Ah, bien, bien. Bueno, simplemente se trata de pescar peces grandes, ¿no? Y si los rumores son ciertos, creo que podrías enseñarme un par de cosas al respecto. ¡",
        ["We should share big fish stories one of these days."] = "Deberíamos compartir historias de peces importantes uno de estos días.",
        ["[View Previous Cutscenes]"] = "[Ver escenas anteriores]",
        ["Which story cutscene would you like to see?"] = "¿Qué escena de la historia te gustaría ver?",
        ["*(Each dialogue option is unlocked after successfully completing the relevant voyage:)*"] = "*(Cada opción de diálogo se desbloquea después de completar con éxito el viaje correspondiente :)*",
        ["*(If the Whaler was not the first adventurer unlocked by the player:)*"] = "*(Si the Whaler no fue el primer aventurero desbloqueado por el player:)*",
        ["Meet the Whaler"] = "Conoce a the Whaler",
        ["You're about to watch 'Meet the Whaler'."] = "Estás a punto de ver 'Conoce a the Whaler'.",
        ["The Misguide"] = "El error",
        ["You're about to watch 'The Misguide'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'El Misguide'. ¿Quieres ver el principio o el final?",
        ["Beginning."] = "Comienzo.",
        ["End."] = "Fin.",
        ["The Evacuation"] = "La evacuación",
        ["You're about to watch 'The Evacuation'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'La Evacuación'. ¿Quieres ver el principio o el final?",
        ["Ramraid"] = "Asalto",
        ["You're about to watch 'Ramraid'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Ramraid'. ¿Quieres ver el principio o el final?",
        ["More"] = "Más",
        ["The Old Man of the Sea"] = "El Old Man del Mar",
        ["You're about to watch 'The Old Man of the Sea'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'El Old Man del Mar'. ¿Quieres ver el principio o el final?",
        ["The Whale Whisperer"] = "El susurrador de Whale",
        ["You're about to watch 'The Whale Whisperer'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'The Whale Whisperer'. ¿Quieres ver el principio o el final?",
        ["Meet the Partner - Again"] = "Conoce a the Partner - Otra vez",
        ["You're about to watch 'Meet the Partner - Again'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Conoce a the Partner - Otra vez'. ¿Quieres ver el principio o el final?",
        ["In Memory of Kirau"] = "En memoria de Kirau",
        ["You're about to watch 'In Memory of Kirau'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'En Memoria de Kirau'. ¿Quieres ver el principio o el final?",
        ["Assault on Paradise"] = "Asalto al paraíso",
        ["You're about to watch 'Assault on Paradise'. Would you like to see the beginning or the end?"] = "Estás a punto de ver 'Asalto al Paraíso'. ¿Quieres ver el principio o el final?",
        ["*(Dialogue from the \"Clue focus\" option on The Whaler. When one of the islands is successfully searched, it disappears from the dialogue options.)*"] = "*(Diálogo desde la opción \"Enfoque de pista\" en The Whaler. Cuando una de las islas se busca con éxito, desaparece de las opciones de diálogo).*",
        ["Hubbub is currently searching The Hook for the perfect gift for seasingers."] = "Actualmente, Hubbub está buscando en The Hook el regalo perfecto para los cantantes marinos.",
        ["The next island Hubbub is planning to search is: [island]"] = "La próxima isla que Hubbub planea buscar es: [island]",
        ["Suggest an island to search?"] = "¿Sugerir una isla para buscar?",
        ["Teardrop Islands"] = "Islas Lágrima",
        ["The Bay of Playful Sirens"] = "La Bahía de las Sirenas Juguetonas",
        ["Leave them to it!"] = "¡Déjalos ahí!",
        ["I don't suppose you've had any shipments of good whiskey, recently..."] = "Supongo que últimamente no has recibido ningún envío de buen whisky...",
        ["Another beer? Maybe later."] = "¿Otra cerveza? Quizás más tarde.",
        ["Hmm, you are a skilled [fisherman/fisherwoman], I can tell. I am in need of someone such as you, but first I must know that I can trust you."] = "Hmm, eres un [fisherman/fisherwoman] experto, lo noto. Necesito a alguien como tú, pero primero debo saber que puedo confiar en ti.",
        ["To get contracts from Hubbub, you must first complete the 'Meet the Whaler' Ports voyage."] = "Para obtener contracts de Hubbub, primero debe completar el viaje por los puertos 'Meet the Whaler'.",
        ["Scampering shiny tortles! It is good to see you, matey! Welcome to my humble home of Whale's Maw. I could hug you!"] = "¡Tortugas brillantes correteando! ¡Qué bueno verte, amigo! Bienvenidos a mi humilde hogar de Whale's Maw. ¡Podría abrazarte!",
        ["Please don't. You smell of fish."] = "Por favor, no lo hagas. Hueles a pescado.",
        ["Haha! Spend long enough here and so will you! In fact, you should make use of these docks here. I have contracts! Here you can catch seerfish and sillago, but shaggy bearded sharks, if you want to catch the rare wobbegong, you should venture out into the uncharted islands."] = "¡Jaja! ¡Pasa suficiente tiempo aquí y tú también! De hecho, deberías hacer uso de estos muelles aquí. ¡Tengo contracts! Aquí podrás pescar videntes y sillagos, pero también tiburones barbudos y peludos. Si quieres pescar el raro wobbegong, deberías aventurarte a las islas inexploradas.",
        ["Thanks, Hubbub."] = "Gracias, Hubbub.",
        ["Would you like a fishing contract...or a hug?"] = "¿Te gustaría un contrato de pesca... o un abrazo?",
        ["Talk about fishing contracts?"] = "¿Hablar de pescar contracts?",
        ["Yes."] = "Sí.",
    },
    ["Theh Orses"] = {
        ["Who are you?"] = "¿Quién eres?",
        ["His name is Theh Orses. <br/>He pulls the cart."] = "Su nombre es Theh Orses. <br/>Tira el carrito.",
        ["Select an option"] = "Selecciona una opción",
        ["Theh Orses? That's a silly name."] = "¿Theh Orses? Ese es un nombre tonto.",
        ["Nay."] = "No.",
        ["Does he pay you well?"] = "¿Te paga bien?",
        ["Have you always pulled a cart?"] = "¿Siempre has tirado de un carrito?",
        ["Goodbye."] = "Adiós.",
    },
    ["Theho Rses"] = {
        ["Who are you?"] = "¿Quién eres?",
        ["His name is Theho Rses. <br/>He pulls the cart."] = "Su nombre es Theho Rses. <br/>Tira el carrito.",
        ["Select an option"] = "Selecciona una opción",
        ["Your name seems strangely familiar."] = "Tu nombre me parece extrañamente familiar.",
        ["Nay."] = "No.",
        ["Theho here doesn't say much."] = "Theho aquí no dice mucho.",
        ["Will you tell me why you pull this cart?"] = "¿Me dirás por qué tiras de este carrito?",
        ["Do you enjoy your job?"] = "¿Disfrutas de tu trabajo?",
        ["Goodbye."] = "Adiós.",
    },
    ["Thessalia"] = {
        ["Would you like to buy any fine clothes?"] = "¿Te gustaría comprar ropa fina?",
        ["Or if you're more after fancy dress costumes or commemorative capes, talk to granny Iffie."] = "O si prefieres disfraces o capas conmemorativas, habla con la abuela Iffie.",
        ["Choose an option:"] = "Elige una opción:",
        ["What do you have?"] = "¿Qué tienes?",
        ["Well, I have a number of fine pieces of clothing on sale or, if you prefer, I can offer you an exclusive, total clothing makeover?"] = "Bueno, tengo varias prendas finas en oferta o, si lo prefieres, ¿puedo ofrecerte un cambio de imagen total y exclusivo?",
        ["Select an option"] = "Selecciona una opción",
        ["Tell me more about this makeover."] = "Cuéntame más sobre este cambio de imagen.",
        ["Certainly!"] = "¡Por supuesto!",
        ["Here at Thessalia's Fine Clothing Boutique we offer a unique service, where we will totally revamp your outfit to your choosing. Tired of always wearing the same old outfit, day-in, day-out? Then this is the service for you!"] = "Aquí en Boutique de Ropa Fina de Thessalia ofrecemos un servicio único, donde renovaremos totalmente tu outfit a tu elección. ¿Estás cansado de usar siempre la misma ropa de siempre, día tras día? ¡Entonces este es el servicio para ti!",
        ["So, what do you say? Interested?"] = "Entonces, ¿qué dices? ¿Interesado?",
        ["I'd like to change my outfit, please."] = "Me gustaría cambiarme de ropa, por favor.",
        ["I'd like to change my outfit, please"] = "Me gustaría cambiarme de ropa, por favor.",
        ["I'd just like to buy some clothes."] = "Sólo me gustaría comprar algo de ropa.",
        ["No, thank you."] = "No, gracias.",
        ["Well, please return if you change your mind."] = "Bueno, regresa si cambias de opinión.",
        ["You can't try them on while wearing armour. Take it off and speak to me again."] = "No puedes probártelos mientras llevas armadura. Quítatelo y hablame de nuevo.",
        ["You must deactivate any outfit overrides you have active before you can change your clothes."] = "Debes desactivar cualquier anulación de vestimenta que tengas activa antes de poder cambiarte de ropa.",
        ["Clothing for sale! <br>Though I wish I could give you a total makeover.<br>You're looking too lifelike for my taste."] = "¡Ropa a la venta! <br>Aunque desearía poder hacerte un cambio de imagen total.<br>Te ves demasiado realista para mi gusto.",
        ["Here at Thessalia's Fine Clothes, we specialise in spritzing up the drab zombie look."] = "Aquí en Fine Clothes de Thessalia, nos especializamos en realzar el monótono look zombie.",
        ["Toss away your bloodstained rags! Clean out those unsightly eye sockets! A zombie doesn't have to look miserable."] = "¡Tira tus harapos manchados de sangre! ¡Limpia esas antiestéticas cuencas de los ojos! Un zombi no tiene por qué parecer miserable.",
    },
    ["Thok of Daemonheim"] = {
        ["What you want with Thok?"] = "¿Qué quieres con Thok?",
        ["Select an Option"] = "Selecciona una opción",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is camp. This where warriors rest and prepare for onslaught."] = "Este es el campamento. Aquí los guerreros descansan y se preparan para el ataque.",
        ["Thok wait here to reward those who survive Daemonheim, who show might as great as Thok's."] = "Thok espera aquí para recompensar a aquellos que sobrevivan a Daemonheim, quienes muestran un poder tan grande como el de Thok.",
        ["It mean Demon Halls. Name not quite right, as there worse things than demons in Daemonheim. It less a hall and more a pit, too. Some say it has no end, but Thok know better."] = "Significa Salas de Demonios. Name no está del todo bien, ya que hay cosas peores que los demonios en Daemonheim. Es menos una sala y más un foso también. Algunos dicen que no tiene fin, pero Thok lo sabe mejor.",
        ["What can I do here?"] = "¿Qué puedo hacer aquí?",
        ["What is that cape beside you?"] = "¿Qué es esa capa a tu lado?",
        ["Can I buy a Skillcape of Dungeoneering?"] = "¿Puedo comprar un Skillcape o un Dungeoneering?",
        ["Up path is Daemonheim. It hold more treasure than Thok can put in his pockets, which is lucky for you, but it guarded by countless monsters, which is unlucky for you. First-timers should talk to tutor before going into castle."] = "El camino ascendente es Daemonheim. Contiene más tesoro del que Thok puede guardar en sus bolsillos, lo cual es una suerte para ti, pero está custodiado por innumerables monstruos, lo cual es una mala suerte para ti. Los principiantes deben hablar con el tutor antes de entrar al castillo.",
        ["Ah, this Dungeoneering skillcape. It mark bearer as true master of Demon Halls."] = "Ah, este Dungeoneering skillcape. Marca al portador como un verdadero maestro de Demon Halls.",
        ["Though Thok has been far into Daemonheim, no-one believe him. So, Thok must guard skillcape, and offer it to brave warriors who find bottom of this place."] = "Aunque Thok ha estado muy metido en Daemonheim, nadie le cree. Entonces, Thok debe proteger skillcape y ofrecerlo a los valientes guerreros que encuentren el fondo de este lugar.",
        ["Thok say it okay. You are great warrior and Thok will raise a drink to you this eventide."] = "Bueno, dilo bien. Eres un gran guerrero y Thok te brindará una bebida esta tarde.",
        ["Thok must ask for 99,000 coins for materials, though."] = "Sin embargo, Thok debe pedir 99.000 coins para materiales.",
        ["Thok see you have inversion coin! Thok will take that and offer you different colour cape."] = "¡Mira que tienes una moneda de inversión! Thok tomará eso y le ofrecerá una capa de diferentes colores.",
        ["Choose an option:"] = "Elige una opción:",
        ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
        ["Not at all; there are many other adventurers who would love the opportunity to purchase such a prestigious item! You can find me here if you change your mind."] = "En absoluto; ¡Hay muchos otros aventureros a quienes les encantaría tener la oportunidad de comprar un artículo tan prestigioso! Puedes encontrarme aquí si cambias de opinión.",
        ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
        ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
        ["Thok say he impressed. For being true master of skill you have option for two skillcapes."] = "Creo que me impresionó. Para ser un verdadero maestro de la habilidad tienes opción a dos skillcapes.",
        ["Buy the level 99 skillcape."] = "Compra el nivel 99 skillcape.",
        ["cond=If the player has given Thok an inverted skillcape token:"] = "cond=Si el player le ha dado a Thok un token inverted skillcape:",
        ["I've mastered this skill. Is there anything else?"] = "He dominado esta habilidad. ¿Hay algo más?",
        ["There is something...though I have kept it a secret for a very long time. It is something that can only be worn by a true master."] = "Hay algo... aunque lo he mantenido en secreto durante mucho tiempo. Es algo que sólo puede ser usado por un verdadero maestro.",
        ["Not even I can wear it - that's how hard it is to achieve."] = "Ni siquiera yo puedo usarlo, así de difícil es lograrlo.",
        ["You say you're a master. Stand straight, let me take a look at you..."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo...",
        ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Dungeoneering master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderle un Dungeoneering master cape.",
        ["Buy Dungeoneering master cape for 120,000 coins?"] = "¿Comprar Dungeoneering master cape por 120.000 coins?",
        ["Yes."] = "Sí.",
        ["cond=If the player has given Thok an inverted master skillcape token:"] = "cond=Si el player le ha dado a Thok un token maestro skillcape invertido:",
        ["Buy the level 120 skillcape."] = "Compra el nivel 120 skillcape.",
        ["Thok must ask for 120,000 coins for materials, though."] = "Sin embargo, Thok debe pedir 120.000 coins para materiales.",
        ["No, that's too much."] = "No, eso es demasiado.",
        ["Thok would offer loan, but has spent all money on beer."] = "Thok ofrecería un préstamo, pero gastó todo el dinero en cerveza.",
        ["Okay, that seems reasonable."] = "Bien, eso parece razonable.",
        ["I would like a normal master cape."] = "Me gustaría un master cape normal.",
        ["I would like an inverted master cape."] = "Me gustaría un master cape invertido.",
        ["I managed to find all your letters."] = "Logré encontrar todas tus cartas.",
        ["Marm! Marm, wake up. Thok was wrong: someone managed to find our letters!"] = "¡Marm! Marma, despierta. Thok se equivocó: ¡alguien logró encontrar nuestras cartas!",
        ["W... What - all of them? You... You know we made it to bottom of that place?"] = "W... ¿Qué? ¿Todos ellos? Tú... ¿Sabes que llegamos al fondo de ese lugar?",
        ["You must have done. The letters go all the way down to the lowest floors."] = "Debes haberlo hecho. Las letras llegan hasta los pisos más bajos.",
        ["I can't believe it! Do, you know what ha... happened to me? Why I have trouble thinking? Why I can't even sl... sleep for fear?"] = "¡No puedo creerlo! ¿Sabes lo que me ha pasado? ¿Por qué tengo problemas para pensar? ¿Por qué ni siquiera puedo dormir por miedo?",
        ["Neither of you remember? Your letters aren't clear, but it was like someone pulled a plug and drained Marmaros of all hope and optimism. You became suicidal, and Thok had to stop you hurting yourself by breaking your arms."] = "¿Ninguno de ustedes se acuerda? Tus cartas no son claras, pero fue como si alguien desconectara y drenara a Marmaros de toda esperanza y optimismo. Te volviste suicida y Thok tuvo que evitar que te lastimaras rompiéndote los brazos.",
        ["Not remember that at all, but it feel true. Thok and Marm can't remember what happened at bottom of the halls at all, Player. Memory a mess, like when Thok fell asleep in keg of stout."] = "No lo recuerdo en absoluto, pero parece cierto. Thok y Marm no pueden recordar en absoluto lo que pasó al fondo de los pasillos, Player. La memoria es un desastre, como cuando Thok se quedó dormido en un barril de cerveza negra.",
        ["You wrote that somebody saved you and brought you back here: a man with a...white beard, I think you said. I guess he must have-"] = "Escribiste que alguien te salvó y te trajo de regreso aquí: un hombre con... barba blanca, creo que dijiste. Supongo que debe haber-",
        ["A white beard? No, it couldn't be..."] = "¿Barba blanca? No, no puede ser...",
        ["Haha, look! Marm must be getting better: he using his head again!"] = "¡Jaja, mira! Marm debe estar mejorando: ¡está usando la cabeza otra vez!",
        ["What is it?"] = "¿Qué es?",
        ["I... I can't be sure, but I might have an idea of who this man with a white beard is. There's someone I need to talk to...someone who has a lot of explaining to do."] = "Yo... No puedo estar seguro, pero podría tener una idea de quién es este hombre de barba blanca. Hay alguien con quien necesito hablar... alguien que tiene mucho que dar explicaciones.",
        ["But for now, Thok have work to do, and mustn't exhaust Marm from excitement. You have thanks, Player. Thok will sing your name at tonight's eveningtide."] = "Pero por ahora, Thok tiene trabajo que hacer y no debe agotar a Marm por la emoción. Tienes gracias, Player. Thok cantará tu nombre esta noche al atardecer.",
        ["I've been you."] = "Yo he sido tú.",
        ["What? You confuse Thok."] = "¿Qué? Confundes a Thok.",
        ["Skaldrun showed me the story of how you battled your way through the dungeons to save Marmaros."] = "Skaldrun me mostró la historia de cómo te abriste camino a través de las mazmorras para salvar a Marmaros.",
        ["Yes, was a great adventure."] = "Sí, fue una gran aventura.",
        ["Thanks for teaching me how to headbutt like you."] = "Gracias por enseñarme a dar cabezazos como tú.",
        ["You welcome. No try headbutt Thok though. Thok head thicker than yours."] = "De nada. Pero no intentes darle un cabezazo a Thok. Creo que la cabeza es más gruesa que la tuya.",
        ["Can you teach me that ability? You know, the one where you obliterate the enemy with your forehead?"] = "¿Puedes enseñarme esa habilidad? Ya sabes, ¿ese en el que destruyes al enemigo con tu frente?",
        ["Ha ha ha. No, tiny person, only Thok has head thick and powerful enough for that."] = "Ja, ja, ja. No, personita, sólo Thok tiene la cabeza lo suficientemente gruesa y poderosa para eso.",
        ["It all seemed a little"] = "Todo parecía un poco",
        ["It all seemed a little . Did you really fight so many boss monsters?"] = "Todo parecía un poco. ¿Realmente luchaste contra tantos monstruos jefes?",
        ["Thok fought many powerful monsters and Thok beat them all. Do not mock Thok."] = "Thok luchó contra muchos monstruos poderosos y Thok los venció a todos. No te burles de Thok.",
        ["Erm, sorry."] = "Erm, lo siento.",
        ["Whatever happened to Mini Marm?"] = "¿Qué pasó con Mini Marm?",
        ["Mini Marm is great and mighty crab warrior. He went back into dungeon to slay many monsters."] = "Mini Marm es un gran y poderoso guerrero cangrejo. Regresó al calabozo para matar muchos monstruos.",
        ["Will he be alright?"] = "¿Estará bien?",
        ["Do not fear for Mini Marm, fear for the monsters that dare stand in his way!"] = "¡No temas por Mini Marm, teme por los monstruos que se atreven a interponerse en su camino!",
        ["About the Task System..."] = "Acerca del sistema de tareas...",
        ["I've completed all of the Elite tasks in the Daemonheim set."] = "He completado todas las tareas Elite del conjunto Daemonheim.",
        ["Good, good."] = "Bien, bien.",
        ["[Thok hands you a few lamps]"] = "[Thok te entrega algunas lámparas.]",
        ["In Daemonheim you make second gatestone and teleport to it. Also in Daemonehim then bury bones of dead enemies - you get prayer. Also, let you through magical barrier in Brimhaven Dungeon - Thok try head-butting"] = "En Daemonheim creas una segunda piedra de acceso y te teletransportas hasta ella. También en Daemonehim entierras los huesos de los enemigos muertos: obtendrás oración. Además, te permitirá atravesar la barrera mágica en Brimhaven Dungeon: Thok intenta dar cabezazos.",
        ["but now he share the secret."] = "pero ahora comparte el secreto.",
        ["Thanks! What else does it do?"] = "¡Gracias! ¿Qué más hace?",
        ["For doing all tasks your ring of kinship made better! Also Thok persuade smuggler to take less monies for stuff. If you really think you as good as Thok, you try hard mode...but me not think your head hard enough for that."] = "¡Por hacer todas las tareas, tu anillo de parentesco mejoró! También Thok convence al contrabandista para que acepte menos dinero para las cosas. Si realmente crees que eres tan bueno como Thok, intenta el modo difícil... pero yo no creo que tu cabeza sea lo suficientemente dura para eso.",
        ["Tell me about the Achievement System."] = "Háblame del Sistema de Logros.",
        ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
        ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
        ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
        ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
        ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
        ["If Thok think you strong enough, you get aura."] = "Si Thok cree que eres lo suficientemente fuerte, obtienes aura.",
        ["Aura will become better if you do more harder task sets."] = "El aura mejorará si realizas conjuntos de tareas más difíciles.",
        ["When you get aura, you learn about its powers."] = "Cuando obtienes aura, aprendes sobre sus poderes.",
        ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
        ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
        ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
        ["To get reward, you complete all tasks in set, then you come get reward."] = "Para obtener una recompensa, debes completar todas las tareas del conjunto y luego recibirás la recompensa.",
        ["Some of the tasks are simple, some need good skills, and some need quests. Thok did all tasks easy!"] = "Algunas de las tareas son simples, otras requieren buenas habilidades y otras necesitan misiones. ¡Thok hizo todas las tareas fácilmente!",
        ["For shiny rewards, talk to Drangund the Dungeoneering Tutor, Marmaros the Rewards trader, Talsar or Thok."] = "Para obtener recompensas brillantes, habla con Drangund, Dungeoneering Tutor, Marmaros the Rewards trader, Talsar o Thok.",
        ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
        ["I've noticed there are a couple versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
        ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
        ["It looks like you're currently using the old model for your Dungeoneering skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Dungeoneering skillcape. ¿Quieres cambiar a uno más nuevo?",
        ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes elegir usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
        ["Yes, I would like to wear the [new/old] version of the skillcape."] = "Sí, me gustaría usar la versión [new/old] del skillcape.",
        ["Would you like to wear the [old/newer] model for just this cape, or for the Quest Cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo [old/newer] solo para esta capa, o para el Quest Cape y todos los skillcapes que tienes?",
        ["I would just like to change the Dungeoneering skillcape."] = "Solo me gustaría cambiar el Dungeoneering skillcape.",
        ["No problem, you will now use the [older/newer] model for your Dungeoneering skillcape."] = "No hay problema, ahora utilizarás el modelo [older/newer] para tu Dungeoneering skillcape.",
        ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
        ["No problem, you will now use the [older/newer] model for all of your skillcapes!"] = "¡No hay problema, ahora usarás el modelo [older/newer] para todos tus skillcapes!",
        ["I've changed my mind!"] = "¡He cambiado de opinión!",
        ["No, thank you."] = "No, gracias.",
        ["Great! I'm glad you're still enjoying the [old/new] version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión [old/new]!",
        ["If you want, I can make it so you use the old model for all of the skillcapes you own."] = "Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas.",
        ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
        ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
        ["No, thanks."] = "No, gracias.",
        ["I found this book of yours by rummaging in Balthazar's Raffle, it was at the bottom of a barrel!"] = "Encontré este libro tuyo hurgando en la Rifa de Balthazar, ¡estaba en el fondo de un barril!",
        ["Book did not sell as well as Thok want. Showing book off to people, I punch everyone who say book was stupid."] = "El libro no se vendió tan bien como Thok quería. Al mostrar un libro a la gente, golpeo a todos los que dicen que el libro es estúpido.",
        ["Then weaklings who chop tree with axe start to hate Thok too. They say I take all trees so they have nothing to cut. So I punch them too."] = "Entonces los débiles que cortan árboles con un hacha empiezan a odiar a Thok también. Dicen que tomo todos los árboles para que no tengan nada que cortar. Así que también les golpeo.",
        ["After Thok punch weaklings, green people who hug trees say Thok not think about trees feelings. They say Thok no care if a tree not want to become place where beer goes, I punch them as well."] = "Después de que Thok golpea a los débiles, las personas verdes que abrazan a los árboles dicen que Thok no piensa en los sentimientos de los árboles. Dicen que a Thok no le importa si un árbol no quiere convertirse en el lugar donde va la cerveza, yo también los golpeo.",
        ["Thok not stupid, Thok king of make stuff with trees!"] = "¡No es estúpido, eres el rey de hacer cosas con árboles!",
        ["How do you make furniture? I don't see a workbench around here and I'd be very surprised if the Housing Agency allowed you to own a house."] = "¿Cómo se hace furniture? No veo un banco de trabajo por aquí y me sorprendería mucho que la Agencia de Vivienda le permitiera ser propietario de una casa.",
        ["Thok pick up tree and smash tree over knee until Thok is happy."] = "Thok levanta un árbol y lo aplasta sobre la rodilla hasta que Thok esté feliz.",
        ["I'm not sure how that works."] = "No estoy seguro de cómo funciona.",
        ["Thok think of what to make and smash on knee until it is made. It not hard, just need to find tree. Here Thok show-"] = "Piensa en qué hacer y aplasta la rodilla hasta que esté hecho. No es difícil, sólo hay que encontrar el árbol. Aquí Thok muestra",
        ["No no no Thok, that isn't necessary. Thank you for whatever that conversation was."] = "No, no, Thok, eso no es necesario. Gracias por lo que fue esa conversación.",
        ["Thok happy to see book again, Thok no punch you this time."] = "Aunque estoy feliz de ver el libro de nuevo, aunque esta vez no te golpearé.",
        ["Thok not talk to you with that around."] = "Creo que no te hablo con eso alrededor.",
        ["With what around?"] = "¿Con qué alrededor?",
        ["DOOM!"] = "¡CONDENACIÓN!",
        ["[Thok barely brings himself to look at your pet ferret.]"] = "[Thok apenas se atreve a mirar a su hurón mascota.]",
        ["I understand. I'll come back once I have a different companion."] = "Lo entiendo. Volveré una vez que tenga un compañero diferente.",
        ["Player! Thok is pleased to see you! But Thok is busy, busy watching all these villains."] = "¡Player! ¡Thok está encantado de verte! Pero Thok está ocupado, muy ocupado observando a todos estos villanos.",
        ["One of them is bound to do something EVIL and when they do, Thok will teach them a lesson."] = "Uno de ellos seguramente hará algo MALVADO y cuando lo haga, Thok les dará una lección.",
        ["With his FIST!"] = "¡Con su PUÑO!",
    },
    ["Thora (Miscellania Castle)"] = {
        ["Hello."] = "Hola.",
        ["Good day, Your Royal Highness."] = "Buenos días, Su Alteza Real.",
    },
    ["Thora"] = {
        ["Hello."] = "Hola.",
        ["Good day, Your Royal Highness."] = "Buenos días, Su Alteza Real.",
    },
    ["Thora (Miscellania Dungeon)"] = {
        ["Hello."] = "Hola.",
        ["Good day, your Royal Highness."] = "Buenos días, Alteza Real.",
    },
    ["Thora the Barkeep"] = {
        ["Hello there."] = "Hola.",
        ["Hello yourself, outerlander. A little out of the way up here, aren't you?"] = "Hola a ti mismo, outsider. Un poco alejado aquí arriba, ¿no?",
        ["I would love to stop and chat with you, but unfortunately we have a custom that no Fremennik may speak with the outerlanders without the permission of our chieftain."] = "Me encantaría detenerme y charlar contigo, pero desafortunadamente tenemos la costumbre de que ningún Fremennik puede hablar con los extranjeros sin el permiso de nuestro jefe.",
        ["Don't take it personally. The Chieftain is stood just over there, his name is Brundt. I suggest you go and introduce yourself."] = "No te lo tomes como algo personal. El Cacique está justo allí, su nombre es Brundt. Te sugiero que vayas y te presentes.",
        ["You wouldn't want to go making any enemies because you weren't aware of our customs now, would you?"] = "No querrías hacerte enemigos porque no conocías nuestras costumbres ahora, ¿verdad?",
        ["No, I guess not. Thanks anyway."] = "No, supongo que no. Gracias de todos modos.",
        ["Not a problem, outerlander. It's always nice to see a new face in the long hall; it happens so rarely."] = "No hay problema, extranjero. Siempre es agradable ver una cara nueva en el largo pasillo; sucede muy raramente.",
        ["Only Fremenniks may buy drinks here."] = "Sólo los Fremenniks pueden comprar bebidas aquí.",
        ["Hello again, [Fremennik name]. I suppose you want a drink? Or are you going to try another scam with that terrible Askeladden again?"] = "Hola de nuevo, [Fremennik name]. ¿Supongo que quieres un trago? ¿O vas a volver a intentar otra estafa con ese terrible Askeladden?",
        ["Scam? Oh... You mean his promise not to come in here anymore?"] = "¿Estafa? Oh... ¿Te refieres a su promesa de no volver a entrar aquí?",
        ["Yes. Yes I do. I should never have trusted him not to come in here, even with that written promise. Anyway, do you want a drink or not?"] = "Sí. Sí. Nunca debí haber confiado en que él no vendría aquí, ni siquiera con esa promesa escrita. De todos modos, ¿quieres una copa o no?",
        ["*(After Hero's Welcome)* Can I ask about V?"] = "*(Después de la bienvenida del héroe)* ¿Puedo preguntar sobre V?",
        ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
        ["Yes please"] = "si por favor",
        ["No thanks"] = "No gracias",
        ["No thanks."] = "No, gracias.",
        ["Okay then."] = "Está bien, entonces.",
    },
    ["Thordur"] = {
        ["Well go on then. You don't want to wait around here, do you? It's just a mostly featureless room."] = "Bueno, entonces continúa. No querrás esperar por aquí, ¿verdad? Es sólo una habitación prácticamente sin rasgos distintivos.",
        ["Select an option"] = "Selecciona una opción",
        ["Can you explain this place again?"] = "¿Puedes explicar este lugar otra vez?",
        ["It's Behind the Scenes!"] = "¡Está detrás de escena!",
        ["-PLACEHOLDER- hilarious placeholder dialogue here. Wait, what? Why did I say that?"] = "-PLACEHOLDER- Diálogo divertido de marcador de posición aquí. Espera, ¿qué? ¿Por qué dije eso?",
        ["It's the editing. There's no one checking the dialogue, so you just spew any old rubbish."] = "Es la edición. No hay nadie revisando el diálogo, así que simplemente arrojas basura.",
        ["-PLACEHOLDER- the player still doesn't understand. Yuck! That feels horrible!"] = "-PLACEHOLDER- el player todavía no entiende. ¡Qué asco! ¡Eso se siente horrible!",
        ["Don't worry, you've probably gotten it out of your system now. You may still find yourself saying some pretty weird things though!"] = "No te preocupes, probablemente ya lo hayas eliminado de tu sistema. ¡Es posible que aún te encuentres diciendo algunas cosas bastante raras!",
        ["So, what is this place?"] = "Entonces, ¿qué es este lugar?",
        ["I'll break it down for you. You're from RuneScape, right?"] = "Te lo desglosaré. Eres de RuneScape, ¿verdad?",
        ["I'm from Gielinor."] = "Soy de Gielinor.",
        ["Sure, big rebranding exercise, world building, but same thing. Sometimes in RuneScape things change. People change how they look. New stuff appears. Old stuff disappears."] = "Claro, un gran ejercicio de cambio de marca, construcción de mundos, pero lo mismo. A veces en RuneScape las cosas cambian. La gente cambia su apariencia. Aparecen cosas nuevas. Las cosas viejas desaparecen.",
        ["I never noticed this happening."] = "Nunca me di cuenta de que esto sucediera.",
        ["You're part of the system, see, you don't see it happening. Take Rat Pits, you remember Rat Pits?"] = "Eres parte del sistema, ¿ves? No ves que eso suceda. Tomemos como ejemplo Rat Pits, ¿recuerdas Rat Pits?",
        ["No. What's Rat Pits?"] = "No. ¿Qué es Rat Pits?",
        ["It was a minigame, and it was broken, and no one played it, so it got removed. Now for you it's like it never existed."] = "Era un minijuego, estaba roto y nadie lo jugó, así que lo eliminaron. Ahora para ti es como si nunca hubiera existido.",
        ["But what does that have to do with this place?"] = "¿Pero qué tiene eso que ver con este lugar?",
        ["Well when something gets removed from the world, or before it gets added, this is where it goes. We call it Behind the Scenes. Look, just think of it as like the afterlife. Afterlife-slash- theme-bar."] = "Bueno, cuando algo se elimina del mundo, o antes de que se agregue, aquí es donde va. Lo llamamos Detrás de Escena. Mira, piensa en ello como en la otra vida. Afterlife-slash-barra temática.",
        ["So it's full of dead people?"] = "¿Entonces está lleno de gente muerta?",
        ["Close enough. You go on in. You'll either figure it out or go mad from the trying."] = "Bastante cerca. Continúas. O lo descubrirás o te volverás loco por intentarlo.",
        ["Off I go, then."] = "Entonces me voy.",
        ["I'd rather stay here for a bit."] = "Prefiero quedarme aquí un rato.",
    },
    ["Thorhild"] = {
        ["Hello."] = "Hola.",
        ["Good day, Your Royal Highness."] = "Buenos días, Su Alteza Real.",
    },
    ["Thormac"] = {
        ["Thank you for rescuing my scorpions."] = "Gracias por rescatar a mis escorpiones.",
        ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
        ["That's okay."] = "Está bien.",
        ["You said you'd enchant my battlestaff for me."] = "Dijiste que encantarías mi battlestaff para mí.",
        ["Yes, although it'll cost you 40,000 coins for the materials. What kind of staff did you want enchanting?"] = "Sí, aunque los materiales te costarán 40.000 coins. ¿Qué tipo de staff querías encantador?",
        ["Yes. Usually, it would cost you 40,000 coins, but, since you made the effort to get to know the Seers' area, it will be 27,000 coins. What kind of staff did you want enchanting?"] = "Sí. Normalmente te costaría 40.000 coins, pero, como te esforzaste en conocer la zona de los Videntes, te costará 27.000 coins. ¿Qué tipo de staff querías encantador?",
        ["You don't have the correct battlestaff."] = "No tienes el battlestaff correcto.",
        ["You need [27,000/40,000] coins to pay Thormac."] = "Necesitas [27,000/40,000] coins para pagar Thormac.",
        ["[27,000/40,000] coins have been removed from your money pouch."] = "[27,000/40,000] coins se han eliminado de su bolsa de dinero.",
        ["Thormac enchants your battlestaves."] = "Thormac encanta tus bastones de batalla.",
        ["Could you enchant my Armadyl battlestaff?"] = "¿Podrías encantar mi Armadyl battlestaff?",
        ["I don't know where you got this, but it already has plenty of mystic power flowing through it. I don't think I can make it any more mystical."] = "No sé de dónde sacaste esto, pero ya tiene mucho poder místico fluyendo a través de él. No creo que pueda hacerlo más místico.",
    },
    ["Thorodin"] = {
        ["Good day, [sir/madam]."] = "Buenos días, [sir/madam].",
        ["Select an Option"] = "Selecciona una opción",
        ["What are you doing down here?"] = "¿Qué estás haciendo aquí abajo?",
        ["We're extending the cave so more people can live in it."] = "Estamos ampliando la cueva para que más personas puedan vivir en ella.",
        ["These Miscellanians aren't so bad. They appreciate the benefits of living underground."] = "Estos misceláneos no son tan malos. Aprecian los beneficios de vivir bajo tierra.",
        ["...such as?"] = "...¿como?",
        ["Not getting rained on, for example."] = "Que no llueva, por ejemplo.",
        ["Did you do anything about that monster Donal was talking about?"] = "¿Hiciste algo con ese monstruo del que hablaba Donal?",
        ["It's been taken care of."] = "Ya se ha solucionado.",
        ["Glad to hear it. Now we can get on with excavating."] = "Me alegra oírlo. Ahora podemos seguir con la excavación.",
        ["Good day."] = "Buenos días.",
    },
    ["Thorvald the Warrior"] = {
        ["Leave me be, outerlander. I have nothing to say to the likes of you."] = "Déjame en paz, extranjero. No tengo nada que decir a gente como tú.",
        ["Outerlander... do not test my patience. I do not take kindly to people wandering in here and acting as though they own the place."] = "Outerlander... no pongas a prueba mi paciencia. No me agrada que la gente deambule por aquí y actúe como si fuera la dueña del lugar.",
        ["Howdy Thorvald!"] = "¡Hola Thorvald!",
        ["And greetings to you too. It is good to see new blood entering the Fremennik; we gain our strength by bringing new warriors into the tribe."] = "Y un saludo para ti también. Es bueno ver sangre nueva entrando al Fremennik; Obtenemos nuestra fuerza trayendo nuevos guerreros a la tribu.",
        ["Hey, Thorvald! Is everything okay here?"] = "¡Hola, Thorvald! ¿Está todo bien aquí?",
        ["No, everything is not alright! Koschei turned out to be a powerful being known as a Mahjarrat! I heard arguing and popped my head down to see what was going on! Saw the whole thing!"] = "¡No, no todo está bien! ¡Koschei resultó ser un ser poderoso conocido como Mahjarrat! ¡Escuché una discusión y agaché la cabeza para ver qué estaba pasando! ¡Vi todo!",
        ["Yes, it's true. He's your friend, so I don't think he is a threat to you."] = "Sí, es verdad. Es tu amigo, así que no creo que sea una amenaza para ti.",
        ["That's not what I am worried about."] = "Eso no es lo que me preocupa.",
        ["Then what is the matter?"] = "Entonces, ¿cuál es el problema?",
        ["Who am I going to get to test the young Fremennik warriors now? No one else will volunteer to be attacked every day!"] = "¿A quién voy a poner a prueba a los jóvenes guerreros Fremennik ahora? ¡Nadie más se ofrecerá como voluntario para ser atacado todos los días!",
        ["Maybe you should take his place: dress like him and fight in the trial. Since it is only a test of bravery, you can stop when they have proven themselves."] = "Quizás deberías tomar su lugar: vestirte como él y luchar en el juicio. Dado que es sólo una prueba de valentía, puedes detenerte cuando hayan demostrado su valía.",
        ["Ah, I see how you got Peer the Seer's vote now! You are wise indeed. Let's keep this little...arrangement between us."] = "¡Ah, ya veo cómo obtuviste el voto de Peer the Seer! Eres realmente sabio. Mantengamos este pequeño... arreglo entre nosotros.",
    },
    ["Thuddley"] = {
        ["Hi, human."] = "Hola, humano.",
        ["Hi, ogre."] = "Hola, ogro.",
        ["How are you today, little ogre?"] = "¿Cómo estás hoy, pequeño ogro?",
        ["*Dialogue 1:*"] = "*Diálogo 1:*",
        ["Can I have some shiny pretties, human?"] = "¿Puedo tener algunas bellezas brillantes, humano?",
        ["What makes you think I'd give my shiny pretties to you?"] = "¿Qué te hace pensar que te daría mis bellezas brillantes?",
        ["That skinny lady at de bank say visitors bring lots of shiny pretties with them when they come visit Oo'glog. Me want my share!"] = "Esa señora flaca del banco dice que los visitantes traen consigo muchas bellezas brillantes cuando vienen a visitar Oo'glog. ¡Quiero mi parte!",
        ["Ah, you see, I've given your share to that skinny lady at the bank; you'll have to ask her for it yourself. Make sure you ask really loudly and growl at her every time she uses a word you don't understand, okay?"] = "Ah, verás, le he dado tu parte a esa señora flaca del banco; Tendrás que pedírselo tú mismo. Asegúrate de preguntarle en voz muy alta y gruñirle cada vez que use una palabra que no entiendes, ¿de acuerdo?",
        ["Yay! Thanks human. I'm gonna get my shiny pretties, even if I have to growl all afternoon."] = "¡Sí! Gracias humano. Voy a conseguir mis bellezas brillantes, incluso si tengo que gruñir toda la tarde.",
        ["*Dialogue 2:*"] = "*Diálogo 2:*",
        ["Fine, please and thank you very much, madam sir!"] = "¡Bien, por favor y muchas gracias señora señor!",
        ["You're very...polite."] = "Eres muy... educado.",
        ["Me know! Me practising! Balnea say I can have job in Customer Rations when I grow up if me polite enough."] = "¡Lo sé! ¡Yo practicando! Balnea dice que puedo tener trabajo en Customer Rations cuando sea mayor si soy lo suficientemente educado.",
        ["Don't you mean 'Customer Relations'?"] = "¿No te refieres a 'Relaciones Customer'?",
        ["Blechh! Dat not sound near as tasty as 'Customer Rations'. Me not sure me want de job after all."] = "¡Blechh! Eso no suena tan sabroso como 'Customer Rations'. Después de todo, no estoy seguro de querer el trabajo.",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["Hey, human. What did you bring me?"] = "Hola, humano. ¿Qué me trajiste?",
        ["Hmm, let me think carefully about this. Oh, yes, I remember, now! Absolutely nothing."] = "Hmm, déjame pensar detenidamente en esto. ¡Oh, sí, ahora lo recuerdo! Absolutamente nada.",
        ["Aw, shucks."] = "Ay, caray.",
        ["*Dialogue 4:*"] = "*Diálogo 4:*",
        ["How does it feel to be so puny wee small, human?"] = "¿Cómo se siente ser tan pequeño, humano?",
        ["Oh, I dunno. How does it feel to be so incredibly dense?"] = "Oh, no lo sé. ¿Cómo se siente ser tan increíblemente denso?",
        ["Uhh...what dat s'pposed to mean?"] = "Uhh... ¿qué se supone que significa eso?",
        ["Never mind."] = "No importa.",
        ["*Dialogue 5:*"] = "*Diálogo 5:*",
        ["Me like pie!"] = "¡Me gusta el pastel!",
        ["Doesn't everyone?"] = "¿No es así para todos?",
        ["Pie! Pie! Pie! Pie! Pie!"] = "¡Pastel! ¡Pastel! ¡Pastel! ¡Pastel! ¡Pastel!",
        ["Yes, dear, pie."] = "Sí, querido, pastel.",
        ["*Dialogue 6:*"] = "*Diálogo 6:*",
        ["Me wanna go visit Fycie 'n Bugs!"] = "¡Quiero ir a visitar Fycie y Bugs!",
        ["Yes, they're both delightful individuals."] = "Sí, ambos son personas encantadoras.",
        ["Will you take me to see dem, human?"] = "¿Me llevarás a verlos, humano?",
        ["Didn't your mother ever teach you not to talk to strangers?"] = "¿Tu madre nunca te enseñó a no hablar con extraños?",
        ["*Dialogue 7:*"] = "*Diálogo 7:*",
        ["Me wants CHOMPY for dinner!"] = "¡Quiero CHOMPY para cenar!",
        ["Me hopes you GETS chompy for dinner!"] = "¡Espero que te pongas nervioso para la cena!",
        ["What you talk weird like dat for, human? You sound silly!"] = "¿Por qué hablas así de raro, humano? ¡Suenas tonto!",
        ["*Dialogue 8:*"] = "*Diálogo 8:*",
        ["Not so very good. Me just drop me lunch in de pool."] = "No muy bien. Simplemente déjame el almuerzo en la piscina.",
        ["Ew...I think I can see it floating over there."] = "Ew... Creo que puedo verlo flotando por allí.",
        ["Oh, thank you human! I have it as a snack next time I go for swim!"] = "¡Oh, gracias humano! ¡Lo tomaré como refrigerio la próxima vez que vaya a nadar!",
        ["*Dialogue 9:*"] = "*Diálogo 9:*",
        ["You very cute, little creature. Me want to have a human as a pet. What you doing, human? You busy? You want be my little pet human creature?"] = "Eres una pequeña criatura muy linda. Quiero tener un humano como mascota. ¿Qué estás haciendo, humano? ¿Estas ocupado? ¿Quieres ser mi pequeña criatura humana mascota?",
        ["Uh...I think I'm busy at the moment."] = "Uh... Creo que estoy ocupado en este momento.",
        ["Pwetty please?"] = "¿Pequeño, por favor?",
        ["Look, sorry to disappoint, but this isn't going to happen."] = "Mira, lamento decepcionarte, pero esto no va a suceder.",
        ["Aw, you no fun, human."] = "Ay, no eres divertido, humano.",
        ["Select an Option"] = "Selecciona una opción",
        ["How are you today?"] = "¿Cómo estás hoy?",
        ["Can you tell me about this copper-coloured pool?"] = "¿Puedes hablarme de esta piscina de color cobre?",
        ["Yeah, it red!"] = "¡Sí, es rojo!",
        ["Yes, I can see that."] = "Sí, puedo verlo.",
        ["Then why you ask, silly human?"] = "Entonces, ¿por qué lo preguntas, humano tonto?",
        ["Well, it's hard to explain. I just sense a strange energy coming from this pool. Do you know anything about it?"] = "Bueno, es difícil de explicar. Siento una extraña energía proveniente de este estanque. ¿Sabes algo al respecto?",
        ["Oh, well, it called de 'Bandos pool' round here. It s'pposed to be special-special. It hard to explain to human creature like you. Maybe you need talk to auntie Seegud. She explain good about these things."] = "Oh, bueno, por aquí se llama 'piscina Bandos'. Se supone que es especial, especial. Es difícil de explicarle a una criatura humana como tú. Quizás necesites hablar con la tía Seegud. Ella explica bien sobre estas cosas.",
    },
    ["Thump"] = {
        ["C'mere, human. Me need practice at dis massage thing. Me not sure how to do it without breaking spine of small, puny creatures."] = "Ven aquí, humano. Necesito práctica en el masaje. No estoy seguro de cómo hacerlo sin romper la columna vertebral de criaturas pequeñas y enclenques.",
        ["I...think I'll take a rain check on that."] = "Yo... creo que lo dejaré a un lado.",
        ["RAAAAAAAGH!"] = "¡RAAAAAAAGH!",
        ["Send...help...!"] = "¡Envía...ayuda...!",
    },
    ["Thurgo"] = {
        ["What would you like to ask about? {{anchor"] = "¿Sobre qué te gustaría preguntar? {{anchor",
        ["Skillcape of Smithing"] = "Skillcape de Smithing",
        ["That's an unusual cape you're wearing, what is it?"] = "Esa capa que llevas es inusual, ¿qué es?",
        ["It's a Skillcape of Smithing. Shows that I am a master blacksmith, but of course that's only to be expected. I am an Imcando dwarf after all and everybody knows we're the best blacksmiths."] = "Es un Skillcape de Smithing. Demuestra que soy un maestro herrero, pero, por supuesto, eso es de esperarse. Después de todo, soy un enano Imcando y todo el mundo sabe que somos los mejores herreros.",
        ["I don't do this for anyone, but I've got a special offer today! Normally I require 99,000 coins for this prestigious item, but for you it's half price. Only 92,000 coins!"] = "No hago esto por nadie, ¡pero hoy tengo una oferta especial! Normalmente necesito 99.000 coins para este prestigioso artículo, pero para ti es la mitad de precio. ¡Solo 92.000 coins!",
        ["Choose an option:"] = "Elige una opción:",
        ["92,000 coins? That's much too expensive."] = "¿92.000 coins? Eso es demasiado caro.",
        ["I know where to find you if I change my mind."] = "Sé dónde encontrarte si cambio de opinión.",
        ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
        ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some backpack space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar espacio en backpack antes de que pueda venderte uno.",
        ["But unfortunately, I was mistaken."] = "Pero desafortunadamente me equivoqué.",
        ["Well, come back and see me when you do."] = "Bueno, vuelve a verme cuando lo hagas.",
        ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
        ["I've mastered this skill. Is there anything else?"] = "He dominado esta habilidad. ¿Hay algo más?",
        ["There is something...though I have kept it a secret for a very long time. It is something that can only be worn by a true master."] = "Hay algo... aunque lo he mantenido en secreto durante mucho tiempo. Es algo que sólo puede ser usado por un verdadero maestro.",
        ["Not even I can wear it - that's how hard it is to achieve."] = "Ni siquiera yo puedo usarlo, así de difícil es lograrlo.",
        ["You say you're a master. Stand straight, let me take a look at you."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo.",
        ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Smithing master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderle un Smithing master cape.",
        ["Buy Smithing master cape for 120,000 coins?"] = "¿Comprar Smithing master cape por 120.000 coins?",
        ["Yes."] = "Sí.",
        ["You do not have enough room in your backpack. Please come back when you have some more."] = "No tienes suficiente espacio en tu backpack. Por favor regresa cuando tengas más.",
        ["You do not have enough money to purchase this cape."] = "No tienes suficiente dinero para comprar esta capa.",
        ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
        ["I've noticed there are a couple of versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
        ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
        ["It looks like you're currently using the old model for your Smithing skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Smithing skillcape. ¿Quieres cambiar a uno más nuevo?",
        ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes optar por usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes, I would like to wear the [new/old] version of the skillcape."] = "Sí, me gustaría usar la versión [new/old] del skillcape.",
        ["Would you like to wear the [old/newer] model for just this cape, or for the Quest Cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo [old/newer] solo para esta capa, o para el Quest Cape y todos los skillcapes que tienes?",
        ["I would just like to change the Smithing skillcape."] = "Solo me gustaría cambiar el Smithing skillcape.",
        ["No problem, you will now use the [older/newer] model for your Smithing skillcape."] = "No hay problema, ahora utilizarás el modelo [older/newer] para tu Smithing skillcape.",
        ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
        ["No problem, you will now use the [older/newer] model for all of your skillcapes!"] = "¡No hay problema, ahora usarás el modelo [older/newer] para todos tus skillcapes!",
        ["I've changed my mind!"] = "¡He cambiado de opinión!",
        ["No, thank you."] = "No, gracias.",
        ["Great! I'm glad you're still enjoying the [old/new] version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión [old/new]!",
        ["If you want, I can make it so you use the old model for all of the skillcapes you own."] = "Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas.",
        ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
        ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
        ["No, thanks."] = "No, gracias.",
        ["Something else."] = "Algo más.",
        ["About that sword..."] = "Sobre esa espada...",
        ["Thanks for all your help in getting it for me!"] = "¡Gracias por toda tu ayuda para conseguirlo!",
        ["No worries mate."] = "No te preocupes, amigo.",
        ["A tingling in my Imcando bones! Can it really be..."] = "¡Un cosquilleo en mis huesos de Imcando! ¿Puede realmente ser...?",
        ["Yes! You've found part of an ancient Imcando pickaxe! May I take a look at it?"] = "¡Sí! ¡Has encontrado parte de un antiguo pico Imcando! ¿Podría verlo?",
        ["Please do."] = "Por favor hazlo.",
        ["*(If you have one to three Imcando pickaxe fragment in your inventory:)*"] = "*(Si tienes de uno a tres fragmentos de pico Imcando en tu inventario:)*",
        ["Yes! You have a piece of the ancient Imcando pickaxe! If you bring me all four pieces, I can recreate the pickaxe for you."] = "¡Sí! ¡Tienes un trozo del antiguo pico Imcando! Si me traes las cuatro piezas, puedo recrear el pico para ti.",
        ["*(If you have all four Imcando pickaxe fragments in your inventory:)*"] = "*(Si tienes los cuatro fragmentos del pico Imcando en tu inventario:)*",
        ["You have all four pieces! With these, I can recreate an ancient Imcando pickaxe for you!"] = "¡Tienes las cuatro piezas! ¡Con esto puedo recrear un antiguo pico Imcando para ti!",
        ["It won't be easy, though. As well as the pieces, I'll need a gilded dragon pickaxe, and one million coins to buy other materials."] = "Aunque no será fácil. Además de las piezas, necesitaré un pico de dragón dorado y un millón de coins para comprar otros materiales.",
        ["And a redberry pie, of course. Smithing makes me hungry!"] = "Y un pastel de frutos rojos, por supuesto. ¡Smithing me da hambre!",
        ["I have those things with me now."] = "Tengo esas cosas conmigo ahora.",
        ["Excellent! Let me get to work."] = "¡Excelente! Déjame ponerme a trabajar.",
        ["[Thurgo creates a magical pickaxe for you.]"] = "[Thurgo crea un pico mágico para ti.]",
        ["An Imcando pickaxe?"] = "¿Un pico Imcando?",
        ["[The Imcando pickaxe is equivalent to a bane pickaxe +4, and similarly requires 80 Mining to use. Unlike a bane pickaxe, the Imcando pickaxe can be augmented with the Invention skill.]"] = "[El pico Imcando es equivalente a un pico bane +4 y, de manera similar, requiere 80 Mining para su uso. A diferencia de un pico Bane, el pico Imcando se puede aumentar con la habilidad Invention.]",
        ["Thanks, bye."] = "Gracias, adiós.",
        ["Ask about something else."] = "Pregunta por otra cosa.",
        ["A tingling in my Imcando toes! Is that really what I think it is?"] = "¡Un hormigueo en los dedos de mis pies Imcando! ¿Es eso realmente lo que creo que es?",
        ["Yes! You've come across a very rare thing. Some unforged Imcando metal. Do you mind if I take a look at it?"] = "¡Sí! Te has encontrado con algo muy raro. Algo de metal Imcando sin forjar. ¿Te importa si le echo un vistazo?",
        ["Yes! You have a piece of the ancient Imcando metal! With Archaeology being the big craze right now, if you bring me all four pieces, I can teach you how to make your very own Imcando mattock."] = "¡Sí! ¡Tienes un trozo del antiguo metal Imcando! Dado que Archaeology es la gran moda en este momento, si me traes las cuatro piezas, puedo enseñarte cómo hacer tu propio azadón Imcando.",
        ["Can you help me make a mattock?"] = "¿Puedes ayudarme a hacer un azadón?",
        ["You have enough pieces! With these, rather than do it myself, I can actually teach you how to work Imcando metals and make the mattock for yourself."] = "¡Tienes suficientes piezas! Con estos, en lugar de hacerlo yo mismo, puedo enseñarte cómo trabajar los metales Imcando y hacer el azadón tú mismo.",
        ["Can you help me make a pickaxe?"] = "¿Puedes ayudarme a hacer un pico?",
        ["Sadly not, for a tool as large as an Imcando pickaxe I'd require some much larger pieces, with Archaeology being the big craze right now this is enough for a mattock."] = "Lamentablemente no, para una herramienta tan grande como un pico Imcando necesitaría piezas mucho más grandes, siendo Archaeology la gran moda en este momento, esto es suficiente para un azadón.",
        ["It won't be easy, though. As well as the pieces, I'll need a dragon mattock, and one million coins for the time."] = "Aunque no será fácil. Además de las piezas, necesitaré un azadón de dragón y un millón de coins por el momento.",
        ["And a redberry pie, of course."] = "Y un pastel de frutos rojos, por supuesto.",
        ["Lets get to work."] = "Pongámonos a trabajar.",
        ["You've learnt how to create an Imcando mattock, take the Imcando metal to an anvil in the warforge."] = "Has aprendido cómo crear un azadón Imcando, lleva el metal Imcando a un yunque en la forja.",
        ["...and then once you bind these two pieces together with some flux to prevent the metal from oxidising. You've made yourself a tool the dwarves would be proud to weild{{Sic}}."] = "...y luego, una vez que unes estas dos piezas con un poco de fundente para evitar que el metal se oxide. Te has convertido en una herramienta que los enanos estarían orgullosos de usar {{Sic}}.",
        ["Thank you, Thurgo."] = "Gracias, Thurgo.",
        ["An Imcando mattock"] = "Un azadón Imcando",
        ["An Imcando mattock?"] = "¿Un azadón Imcando?",
        ["With all the ancient sites that have been uncovered lately, it only feels right to equip the best archaeologists with the tools and means to uncover the secrets of our ancestory."] = "Con todos los sitios antiguos que se han descubierto últimamente, parece correcto equipar a los mejores arqueólogos con las herramientas y los medios para descubrir los secretos de nuestros antepasados.",
        ["If you can find enough of these rare Imcando metals, I can teach you how to create a such a tool for yourself."] = "Si puedes encontrar suficientes de estos raros metales Imcando, puedo enseñarte cómo crear una herramienta de este tipo por ti mismo.",
        ["You! May I take a look at that coral crossbow?"] = "¡Tú! ¿Puedo echarle un vistazo a esa ballesta de coral?",
        ["This is amazing engineering! Your crossbow could become extremely powerful if we added the right components onto it."] = "¡Esta es una ingeniería increíble! Tu ballesta podría volverse extremadamente poderosa si le agregamos los componentes adecuados.",
        ["Unfortunately, judging by the materials, the flames you'll need to forge these components together will need to be extremely hot; far beyond anything any conventional forge could produce. You'd probably need an ancient"] = "Desafortunadamente, a juzgar por los materiales, las llamas que necesitarás para forjar estos componentes deberán estar extremadamente calientes; mucho más allá de lo que cualquier forja convencional podría producir. Probablemente necesitarías un antiguo",
        ["dragon from the legends to produce a flame hot enough!"] = "¡un dragón de las leyendas que produce una llama lo suficientemente caliente!",
        ["In the meantime, I can perform a basic assembly of these components if you'd like; it won't be usable as a weapon until you expose it to extreme heat, though."] = "Mientras tanto, puedo realizar un ensamblaje básico de estos componentes si lo deseas; Sin embargo, no se podrá utilizar como arma hasta que lo expongas a un calor extremo.",
        ["Assemble the unforged royal crossbow?"] = "¿Montar la ballesta real no forjada?",
        ["*(If royal crossbow parts are missing:)*"] = "*(Si faltan piezas de la ballesta real:)*",
        ["You are missing the following components: <br>a bolt stabiliser <br>a frame <br>a sight <br>a spring"] = "Le faltan los siguientes componentes: <br>a perno estabilizador <br>a marco <br>a mira <br>a resorte",
        ["*(If all royal crossbow parts are present:)*"] = "*(Si todas las piezas de la ballesta real están presentes:)*",
        ["Thurgo starts assembling the crossbow. Thurgo hands you the unforged crossbow."] = "Thurgo comienza a montar la ballesta. Thurgo te entrega la ballesta sin forjar.",
        ["You need to expose it to extreme heat to finish the process. I'll probably be able to perform any maintenance needed once that's done, if you'll let me."] = "Debes exponerlo a calor extremo para finalizar el proceso. Probablemente podré realizar cualquier mantenimiento necesario una vez que esté hecho, si me lo permite.",
        ["Not right now."] = "No ahora mismo.",
        ["A tingling in my Imcando fingers! Is that..."] = "¡Un hormigueo en mis dedos Imcando! ¿Es eso...?",
        ["Yes! You've found part of an ancient Imcando hatchet! May I take a look at it?"] = "¡Sí! ¡Has encontrado parte de un antiguo hacha de Imcando! ¿Podría verlo?",
        ["Yes! You have a piece of the ancient Imcando hatchet! If you bring me all four pieces, I can recreate the hatchet for you."] = "¡Sí! ¡Tienes un trozo del antiguo hacha Imcando! Si me traes las cuatro piezas, puedo recrear el hacha para ti.",
        ["You have all four pieces! With these, I can recreate an ancient Imcando hatchet for you!"] = "¡Tienes las cuatro piezas! ¡Con esto puedo recrear un antiguo hacha Imcando para ti!",
        ["It won't be easy, though. As well as the pieces, I'll need a dragon hatchet, and one million coins to buy other materials."] = "Aunque no será fácil. Además de las piezas, necesitaré un hacha de dragón y un millón de coins para comprar otros materiales.",
        ["And as I'm sure you know by now, my redberry pie is of utmost importance!"] = "Y como estoy seguro de que ya sabrás, ¡mi pastel de frutos rojos es de suma importancia!",
        ["Congratulations! You have completed: 'Imcando at a tree' - Obtain an Imcando hatchet."] = "¡Felicitaciones! Has completado: 'Imcando at a tree' - Obtén un hacha de Imcando.",
        ["[Thurgo creates a magical hatchet for you.]"] = "[Thurgo crea un hacha mágica para ti.]",
        ["An Imcando hatchet?"] = "¿Un hacha Imcando?",
        ["It's an ancient dwarven artefact, isn't that exciting enough?"] = "Es un antiguo artefacto enano, ¿no es suficientemente emocionante?",
        ["An  hatchet will be far better at cutting trees than a dragon hatchet, that's for sure."] = "Un hacha será mucho mejor para cortar árboles que un hacha de dragón, eso es seguro.",
        ["Oh, I already have a crystal hatchet on my toolbelt. It's an enhanced dragon hatchet!"] = "Oh, ya tengo un hacha de cristal en mi cinturón de herramientas. ¡Es un hacha de dragón mejorada!",
        ["This flimsy thing? Bah! An Imcando hatchet will cut right through it!"] = "¿Esta cosa endeble? ¡Bah! ¡Un hacha Imcando lo atravesará!",
    },
    ["Tiadeche"] = {
        ["*(Randomly says one of the following lines:)*"] = "*(Dice aleatoriamente una de las siguientes líneas:)*",
        ["Just leave a depressed fish hunter alone..."] = "Deja en paz a un cazador de peces deprimido...",
        ["I'll never be able to catch a Karambwan..."] = "Nunca podré atrapar un Karambwan...",
        ["Go away! Can't you see I'm concentrating?"] = "¡Vete! ¿No ves que me estoy concentrando?",
        ["Hello, Tiadeche."] = "Hola, Tiadeche.",
        ["Hello, Bwana! Would you like to buy some Karambwan?"] = "¡Hola, Bwana! ¿Quieres comprar Karambwan?",
        ["Select an option"] = "Seleccione una opción",
        ["Yes."] = "Sí.",
        ["Very well. Let me know if you change your mind."] = "Muy bien. Déjame saber si cambias de opinión.",
    },
    ["Tick-Tock"] = {
        ["Crocodiles and humans, living together in harmony. Who'd have thought?"] = "Cocodrilos y humanos, conviviendo en armonía. ¿Quién lo hubiera pensado?",
        ["Ah, no thanks. I'm trying to get off meat."] = "Ah, no, gracias. Estoy tratando de dejar la carne.",
        ["**Player** Oh, okay!"] = "**Player** ¡Oh, está bien!",
        ["Congratulations! You have completed: 'Vegan Unfriendly' - Feed all the crocodiles some steak."] = "¡Felicitaciones! Has completado: 'Vegan Unfriendly': alimenta a todos los cocodrilos con un poco de filete.",
        ["You have unlocked the title: {{Colour {{Colour|#FFFFFF|Player}}|color=#00FF00}}"] = "Has desbloqueado el título: {{Colour ZZCMD0ZZPlayer}}|color=#00FF00}}",
        ["You can activate this via the 'Titles' tab in the 'Customisations' interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz 'Personalizaciones'.",
    },
    ["Ticket dwarf"] = {
        ["*When speaking to Ticket dwarf at the Keldagrim station*"] = "*Al hablar con Ticket dwarf en la estación Keldagrim*",
        ["Can I buy a ticket?"] = "¿Puedo comprar un billete?",
        ["There's no need. Under our agreement with the Dorgeshuun, you get free train travel in return for services rendered."] = "No es necesario. Según nuestro acuerdo con Dorgeshuun, usted obtiene viajes en tren gratuitos a cambio de los servicios prestados.",
    },
    ["Ticket goblin"] = {
        ["*When talking to Ticket goblin on the train platform in Dorgesh-Kaan.*"] = "*Al hablar con Ticket goblin en el andén del tren en Dorgesh-Kaan.*",
        ["Can I buy a ticket?"] = "¿Puedo comprar un billete?",
        ["You don't need to buy a ticket! You're [Player's name]! Without you, this train wouldn't exist! Just board the train and wait for it to travel to Keldagrim."] = "¡No necesitas comprar un boleto! ¡Eres [Player's name]! ¡Sin vosotros, este tren no existiría! Simplemente suba al tren y espere a que viaje a Keldagrim.",
    },
    ["Tiggy"] = {
        ["Spiky on the outside, but seems to be very friendly!"] = "¡Puntiagudo por fuera, pero parece muy amigable!",
    },
    ["Timble"] = {
        ["Good day. How can I help you?"] = "Buenos días. ¿Le puedo ayudar en algo?",
        ["I was just wondering what you were up to."] = "Me preguntaba qué estabas haciendo.",
        ["I work for Aluft Aloft Gnome Food Delivery Service. It's a growing business you know. We get more customers every day!"] = "Trabajo para el servicio de entrega de alimentos Aluft Aloft Gnome. Es un negocio en crecimiento, ¿sabes? ¡Cada día tenemos más clientes!",
        ["So do you have any spare jobs then?"] = "Entonces, ¿tienes algún trabajo libre?",
        ["Aluft Gianne jnr. is in charge - he'll be able to help you."] = "Aluft Gianne jnr. está a cargo; él podrá ayudarlo.",
        ["Thanks."] = "Gracias.",
        ["Have a nice day."] = "Que tengas un buen día.",
    },
    ["Time (echo)"] = {
        ["It cannot be true - this is not how it will end. I am a god; I am not subject to the mortal cycle like those I loved."] = "No puede ser cierto; así no es como terminará. Soy un dios; No estoy sujeto al ciclo mortal como aquellos a quienes amé.",
        ["What [he/she] told me cannot be true. How are they even who they claim to be? This is not something that should be!"] = "Lo que me dijo [he/she] no puede ser cierto. ¿Cómo son incluso quienes dicen ser? ¡Esto no es algo que debería ser!",
        ["How can they come here and tell me things I cannot know? It must be a lie! And where did they get this key, that unlocks such a journey?"] = "¿Cómo pueden venir aquí y decirme cosas que no puedo saber? ¡Debe ser mentira! ¿Y de dónde sacaron esta llave que abre ese viaje?",
        ["It cannot be the truth of this world! I made this place what it is - my time cannot be done!"] = "¡No puede ser la verdad de este mundo! Hice de este lugar lo que es: ¡mi tiempo no se puede terminar!",
        ["Why me? Why now? I have given so much of myself to this place and this is how I am repaid?"] = "¿Por qué yo? ¿Por qué ahora? ¿He dado mucho de mí a este lugar y así es como me recompensan?",
        ["This is the sacrifice that is asked of me? How can this happen to me; why would this be my fate?"] = "¿Este es el sacrificio que se me pide? ¿Cómo puede pasarme esto? ¿Por qué este sería mi destino?",
        ["I who have slept rather than bring suffering to people, who has not demanded worship, but avoided furthering such practices...and now my time is to come and I will be no more?"] = "Yo, que he dormido en lugar de traer sufrimiento a la gente, que no he exigido adoración, pero he evitado promover tales prácticas... ¿y ahora mi tiempo está por llegar y ya no estaré?",
        ["This cannot be right. This cannot be just. Where is the balance in this? Where is my own freedom? Why should I pay this cost?"] = "Esto no puede ser correcto. Esto no puede ser justo. ¿Dónde está el equilibrio en esto? ¿Dónde está mi propia libertad? ¿Por qué debería pagar este costo?",
        ["What if I made a different offer to them? Is there a negotiation to this, a path to a truer harmony?"] = "¿Qué pasa si les hago una oferta diferente? ¿Existe una negociación para esto, un camino hacia una armonía más verdadera?",
        ["Perhaps there is a different path from the one I have tried to follow, one which leaves me with a different fate?"] = "¿Quizás hay un camino diferente al que he intentado seguir, uno que me deja con un destino diferente?",
        ["What if I were to find this person again, before my time has come? What would it take for them to change their part in what is going to happen?"] = "¿Qué pasaría si volviera a encontrar a esta persona antes de que llegara mi hora? ¿Qué haría falta para que cambien su papel en lo que va a pasar?",
        ["No more of this eternal life? A death to come, unsought when it comes."] = "¿No más de esta vida eterna? Una muerte por venir, no buscada cuando llegue.",
        ["Why could it not have come so long ago, before all of this, before the eons that have passed since last I saw her, my beautiful Aagi? How can it be now it happens?"] = "¿Por qué no pudo haber ocurrido hace tanto tiempo, antes de todo esto, antes de los eones que han pasado desde la última vez que la vi, mi hermosa Aagi? ¿Cómo puede ser que ahora suceda?",
        ["And, oh my daughter, how I have missed you! An empty heart for you still - I had almost forgotten in my rage how long I have lost you, how much I wish I was with you."] = "Y, ¡oh hija mía, cómo te he echado de menos! Un corazón vacío para ti todavía. Casi había olvidado en mi rabia cuánto tiempo te he perdido, cuánto desearía estar contigo.",
        ["Your smile! I have no hope now to ever see it again - I will be as gone as you both are. I am lost."] = "¡Tu sonrisa! Ahora no tengo esperanzas de volver a verlo; estaré tan desaparecido como ustedes dos. Estoy perdido.",
        ["So it is to come, I can see that now. They have the Amserdrwys, and so it must be true; [he/she] will be my friend."] = "Así que está por llegar, puedo verlo ahora. Tienen los Amserdrwys, y por eso debe ser cierto; [he/she] será mi amigo.",
        ["It is not a fight I can win or one I wish to. Instead, I must accept what is to come."] = "No es una pelea que pueda ganar o que desee. En cambio, debo aceptar lo que está por venir.",
        ["The time has come to prepare for my own end...but I cannot let this world be exposed to the horrors others would unleash upon it. The Guardians must be in place."] = "Ha llegado el momento de prepararme para mi propio fin... pero no puedo permitir que este mundo quede expuesto a los horrores que otros desatarían sobre él. Los Guardianes deben estar en su lugar.",
        ["[He/She] who told me of what is to come will be the one who completes them - they will serve me as I have served their people."] = "[He/She] quien me dijo lo que está por venir será quien los complete: me servirán como yo he servido a su gente.",
        ["And they, in turn, will come to see me again and tell me of what will pass."] = "Y ellos, a su vez, vendrán a verme nuevamente y me contarán lo que pasará.",
        ["They will always remember their purpose, as I will always remember mine."] = "Ellos siempre recordarán su propósito, como yo siempre recordaré el mío.",
    },
    ["Time"] = {
        ["It cannot be true - this is not how it will end. I am a god; I am not subject to the mortal cycle like those I loved."] = "No puede ser cierto; así no es como terminará. Soy un dios; No estoy sujeto al ciclo mortal como aquellos a quienes amé.",
        ["What [he/she] told me cannot be true. How are they even who they claim to be? This is not something that should be!"] = "Lo que me dijo [he/she] no puede ser cierto. ¿Cómo son incluso quienes dicen ser? ¡Esto no es algo que debería ser!",
        ["How can they come here and tell me things I cannot know? It must be a lie! And where did they get this key, that unlocks such a journey?"] = "¿Cómo pueden venir aquí y decirme cosas que no puedo saber? ¡Debe ser mentira! ¿Y de dónde sacaron esta llave que abre ese viaje?",
        ["It cannot be the truth of this world! I made this place what it is - my time cannot be done!"] = "¡No puede ser la verdad de este mundo! Hice de este lugar lo que es: ¡mi tiempo no se puede terminar!",
        ["Why me? Why now? I have given so much of myself to this place and this is how I am repaid?"] = "¿Por qué yo? ¿Por qué ahora? ¿He dado mucho de mí a este lugar y así es como me recompensan?",
        ["This is the sacrifice that is asked of me? How can this happen to me; why would this be my fate?"] = "¿Este es el sacrificio que se me pide? ¿Cómo puede pasarme esto? ¿Por qué este sería mi destino?",
        ["I who have slept rather than bring suffering to people, who has not demanded worship, but avoided furthering such practices...and now my time is to come and I will be no more?"] = "Yo, que he dormido en lugar de traer sufrimiento a la gente, que no he exigido adoración, pero he evitado promover tales prácticas... ¿y ahora mi tiempo está por llegar y ya no estaré?",
        ["This cannot be right. This cannot be just. Where is the balance in this? Where is my own freedom? Why should I pay this cost?"] = "Esto no puede ser correcto. Esto no puede ser justo. ¿Dónde está el equilibrio en esto? ¿Dónde está mi propia libertad? ¿Por qué debería pagar este costo?",
        ["What if I made a different offer to them? Is there a negotiation to this, a path to a truer harmony?"] = "¿Qué pasa si les hago una oferta diferente? ¿Existe una negociación para esto, un camino hacia una armonía más verdadera?",
        ["Perhaps there is a different path from the one I have tried to follow, one which leaves me with a different fate?"] = "¿Quizás hay un camino diferente al que he intentado seguir, uno que me deja con un destino diferente?",
        ["What if I were to find this person again, before my time has come? What would it take for them to change their part in what is going to happen?"] = "¿Qué pasaría si volviera a encontrar a esta persona antes de que llegara mi hora? ¿Qué haría falta para que cambien su papel en lo que va a pasar?",
        ["No more of this eternal life? A death to come, unsought when it comes."] = "¿No más de esta vida eterna? Una muerte por venir, no buscada cuando llegue.",
        ["Why could it not have come so long ago, before all of this, before the eons that have passed since last I saw her, my beautiful Aagi? How can it be now it happens?"] = "¿Por qué no pudo haber ocurrido hace tanto tiempo, antes de todo esto, antes de los eones que han pasado desde la última vez que la vi, mi hermosa Aagi? ¿Cómo puede ser que ahora suceda?",
        ["And, oh my daughter, how I have missed you! An empty heart for you still - I had almost forgotten in my rage how long I have lost you, how much I wish I was with you."] = "Y, ¡oh hija mía, cómo te he echado de menos! Un corazón vacío para ti todavía. Casi había olvidado en mi rabia cuánto tiempo te he perdido, cuánto desearía estar contigo.",
        ["Your smile! I have no hope now to ever see it again - I will be as gone as you both are. I am lost."] = "¡Tu sonrisa! Ahora no tengo esperanzas de volver a verlo; estaré tan desaparecido como ustedes dos. Estoy perdido.",
        ["So it is to come, I can see that now. They have the Amserdrwys, and so it must be true; [he/she] will be my friend."] = "Así que está por llegar, puedo verlo ahora. Tienen los Amserdrwys, y por eso debe ser cierto; [he/she] será mi amigo.",
        ["It is not a fight I can win or one I wish to. Instead, I must accept what is to come."] = "No es una pelea que pueda ganar o que desee. En cambio, debo aceptar lo que está por venir.",
        ["The time has come to prepare for my own end...but I cannot let this world be exposed to the horrors others would unleash upon it. The Guardians must be in place."] = "Ha llegado el momento de prepararme para mi propio fin... pero no puedo permitir que este mundo quede expuesto a los horrores que otros desatarían sobre él. Los Guardianes deben estar en su lugar.",
        ["[He/She] who told me of what is to come will be the one who completes them - they will serve me as I have served their people."] = "[He/She] quien me dijo lo que está por venir será quien los complete: me servirán como yo he servido a su gente.",
        ["And they, in turn, will come to see me again and tell me of what will pass."] = "Y ellos, a su vez, vendrán a verme nuevamente y me contarán lo que pasará.",
        ["They will always remember their purpose, as I will always remember mine."] = "Ellos siempre recordarán su propósito, como yo siempre recordaré el mío.",
    },
    ["Timfraku"] = {
        ["I am the Chief of Tai Bwo Wannai Village! Who dares set foot in my hut?"] = "¡Soy el jefe de Tai Bwo Wannai Village! ¿Quién se atreve a poner un pie en mi choza?",
        ["Select an Option"] = "Selecciona una opción",
        ["I am a roving adventurer."] = "Soy un aventurero ambulante.",
        ["Well then adventurer, you would do better to rove elsewhere."] = "Bueno, entonces aventurero, sería mejor que vagaras por otro lado.",
        ["I am a travelling explorer."] = "Soy un explorador viajero.",
        ["Well then explorer, you would do better to travel elsewhere."] = "Bueno, entonces explorador, sería mejor que viajaras a otro lugar.",
        ["I am a wandering wayfarer."] = "Soy un caminante errante.",
        ["Well then wayfarer, you would do better to wander elsewhere."] = "Bueno, entonces caminante, sería mejor que vagaras por otro lado.",
        ["Who me? Oh I'm just a nobody."] = "¿Quién y yo? Oh, sólo soy un don nadie.",
        ["Well then , you would do better to go elsewhere."] = "Bueno, entonces será mejor que vayas a otro lado.",
        ["Why should I leave?"] = "¿Por qué debería irme?",
        ["This place has been cursed. Our people have angered the gods and fled the village."] = "Este lugar ha sido maldecido. Nuestro pueblo enfureció a los dioses y huyó del pueblo.",
        ["Where is this place?"] = "¿Dónde está este lugar?",
        ["You ask too many questions! Now begone!"] = "¡Haces demasiadas preguntas! ¡Ahora vete!",
        ["Who are the gods?"] = "¿Quiénes son los dioses?",
        ["Where have your people fled to?"] = "¿A dónde ha huido tu gente?",
        ["Right, I'm going then."] = "Bien, entonces me voy.",
        ["You again! Only a fool would ignore my instructions."] = "¡Tú otra vez! Sólo un tonto ignoraría mis instrucciones.",
        ["Well there's a simple explanation for that..."] = "Bueno, hay una explicación simple para eso...",
        ["I said: begone!"] = "Dije: ¡vete!",
        ["Not so much ignore as disregard..."] = "No es tanto ignorarlo como ignorarlo...",
        ["What instructions??"] = "¿Qué instrucciones?",
        ["Trufitus sent me."] = "Trufitus me envió.",
        ["Trufitus Shakaya? What news does he send?"] = "Trufitus ¿Shakaya? ¿Qué noticias envía?",
        ["Trufitus has communed with the gods. Your village was never cursed and your people are free to return."] = "Trufitus ha estado en comunión con los dioses. Tu aldea nunca estuvo maldita y tu gente es libre de regresar.",
        ["Bwana, do you speak the truth?"] = "Bwana, ¿dices la verdad?",
        ["Yes, I helped Trufitus gather ingredients for a commune potion."] = "Sí, ayudé a Trufitus a reunir ingredientes para una poción comunal.",
        ["Then it must be true."] = "Entonces debe ser verdad.",
        ["Timfraku appears to concentrate very deeply."] = "Timfraku parece concentrarse muy profundamente.",
        ["I cannot thank you enough for what you have done so far."] = "No puedo agradecerte lo suficiente por lo que has hecho hasta ahora.",
        ["Your gratitude is all I deserve."] = "Tu gratitud es todo lo que merezco.",
        ["Well, some gold would be nice."] = "Bueno, algo de oro estaría bien.",
        ["So far??"] = "¿Hasta ahora?",
        ["Ask about"] = "Preguntar sobre",
        ["Ah, [Adventurer/Explorer/Wayfarer/Nobody], welcome back to Tai Bwo Wannai."] = "Ah, [Adventurer/Explorer/Wayfarer/Nobody], bienvenido de nuevo a Tai Bwo Wannai.",
        ["Select an Option{{anchor"] = "Seleccione una opción{{anchor",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["It should be clear to anyone that I am the chief of Tai Bwo Wannai. I ensure that things run smoothly in this village."] = "Cualquiera debería tener claro que soy el jefe de Tai Bwo Wannai. Me aseguro de que todo funcione sin problemas en este pueblo.",
        ["Is there anything interesting to do here?"] = "¿Hay algo interesante que hacer aquí?",
        ["I've been doing some work around the village."] = "He estado trabajando en el pueblo.",
        ["Ok, thanks."] = "Vale, gracias.",
        ["Yes Bwana, plenty of interesting things to do. Firstly you could make an effort to tidy the place up a little. Equip yourself with a machete and start cutting down the jungle that seems to be growing all around here."] = "Sí Bwana, hay muchas cosas interesantes que hacer. En primer lugar podrías hacer un esfuerzo por ordenar un poco el lugar. Equípate con un machete y comienza a talar la jungla que parece crecer por aquí.",
        ["Go and have a chat with Murcaily for information, he's tending the hardwood grove to the east of here."] = "Ve y charla con Murcaily para obtener información, él está cuidando el bosquecillo de madera al este de aquí.",
        ["That's good Bwana, I would hate to think that you were just being lazy while you're in my kingdom!"] = "Eso es bueno Bwana, ¡odiaría pensar que estabas siendo un holgazán mientras estás en mi reino!",
        ["I'm just passing through."] = "Estoy de paso.",
        ["Ahhhhhhhh - Get away from me you beast!"] = "Ahhhhhhhh - ¡Aléjate de mí, bestia!",
        ["Ahhhhhhhh!"] = "¡Ahhhhhhhh!",
        ["Ahhhhhhhh - It's a monster!"] = "Ahhhhhhhh - ¡Es un monstruo!",
        ["Waahhhhh! - It's da evil broodoo beast come ta eat my very soul!"] = "¡Waahhhhh! - ¡Es una bestia malvada que viene a comerse mi alma!",
        ["What's the problem... oh, I'm wearing this big scary mask! I'd better take it off before I start talking to the natives."] = "¿Cuál es el problema? ¡Oh, estoy usando esta gran máscara aterradora! Será mejor que me lo quite antes de empezar a hablar con los nativos.",
    },
    ["Tina"] = {
        ["Hi! What can I get you?"] = "¡Hola! ¿Qué puedo conseguirte?",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["What ales are you serving?"] = "¿Qué cervezas estás sirviendo?",
        ["Well, we've got Asgarnian Ale, Wizard's Mind Bomb and Dwarven Stout, all for only 3 coins."] = "Bueno, tenemos Asgarnian Ale, Wizard's Mind Bomb y Dwarven Stout, todas por solo 3 coins.",
        ["Select an Option"] = "Selecciona una opción",
        ["One Asgarnian Ale, please."] = "Una cerveza Asgarnian, por favor.",
        ["I said 3 coins! You haven't got 3 coins! {{anchor|isaid3coins}}"] = "¡Dije 3 coins! ¡No tienes 3 coins! {{anchor|isaid3coins}}",
        ["Sorry, I'll come back another day."] = "Lo siento, volveré otro día.",
        ["Thanks, Tina."] = "Gracias, Tina.",
        ["I'll try the Mind Bomb."] = "Probaré la bomba mental.",
        ["Can I have a Dwarven Stout?"] = "¿Puedo tener una Dwarven Stout?",
        ["I don't feel like any of those."] = "No me apetece nada de eso.",
        ["What can you tell me about dwarves and ale?"] = "¿Qué puedes decirme sobre los enanos y la cerveza?",
        ["Oh it's you again. Forgotten the secret already?"] = "Oh, eres tú otra vez. ¿Ya olvidaste el secreto?",
        ["No... I just... misplaced it."] = "No... Simplemente... lo perdí.",
        ["Mmmmm... the secret is in the gold. Drop a gold coin into asgarnian ale and you'll get this weird golden ale that the dwarves seem to love, I think they're genetically attracted to gold."] = "Mmmmm... el secreto está en el oro. Echa una moneda de oro en cerveza asgarniana y obtendrás esta extraña cerveza dorada que parece encantar a los enanos. Creo que se sienten atraídos genéticamente por el oro.",
        ["Thanks, I won't forg...err.. misplace it, this time."] = "Gracias, esta vez no lo olvidaré... err... extravío.",
        ["I was wondering if you could give some feedback on this mead?"] = "Me preguntaba si podrías darnos algún comentario sobre este hidromiel.",
        ["I'd recognise those old kegs anywhere."] = "Reconocería esos viejos barriles en cualquier lugar.",
        ["I'd love to try the next batch of Leslie's mead."] = "Me encantaría probar el próximo lote de hidromiel de Leslie.",
        ["Mead isn't my favourite choice of drink but that's very nice."] = "El hidromiel no es mi bebida favorita, pero es muy agradable.",
        ["That may be the best mead I've ever drunk actually."] = "En realidad, ese puede ser el mejor hidromiel que he bebido.",
        ["The flavours are very subtle. Delicious."] = "Los sabores son muy sutiles. Delicioso.",
        ["Fantastic, I'll pass that on. Thank you!"] = "Fantástico, lo pasaré. ¡Gracias!",
        ["Thanks!"] = "¡Gracias!",
    },
    ["Tindar"] = {
        ["Creeespy frogs' legs! Get your creeeespy frogs' legs! You want some crispy frogs' legs? Just 10gp."] = "¡Ancas de rana espeluznantes! ¡Consigue tus espeluznantes ancas de rana! ¿Quieres unas ancas de rana crujientes? Sólo 10 po.",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes please."] = "Sí por favor.",
        ["Yes please!"] = "¡Sí, por favor!",
        ["But I don't have enough money on me."] = "Pero no tengo suficiente dinero encima.",
        ["Looks like your hands are full. You'll have to free up some inventory space before I sell you anything."] = "Parece que tienes las manos ocupadas. Tendrás que liberar algo de espacio en el inventario antes de que te venda algo.",
        ["There you go."] = "Ahí lo tienes.",
        ["No thanks."] = "No, gracias.",
    },
    ["Tindel Marchant"] = {
        ["**Tindel Marchant:{{anchor|start}}** Hello there! Welcome to my special antiques boutique."] = "**Tindel Marchant:{{anchor|start}}** ¡Hola! Bienvenidos a mi boutique especial de antigüedades.",
        ["Select an option"] = "Selecciona una opción",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["I'm a specialist at identifying exotic and antique weapons, specifically swords, but I plan to branch out. If you have any old and rusty weapons that you want me to check out, just show them to me, pay me 100 Gold and I'll see if you have an antique on your hands. I can also repair some antique weapons and armours, just show me the item and I'll let you know if I can repair it and for how much."] = "Soy un especialista en identificar armas exóticas y antiguas, específicamente espadas, pero planeo expandirme. Si tienes armas viejas y oxidadas que quieres que revise, enséñamelas, págame 100 de oro y veré si tienes una antigüedad en tus manos. También puedo reparar algunas armas y armaduras antiguas, solo muéstrame el artículo y te diré si puedo repararlo y por cuánto.",
        ["What's involved?"] = "¿Qué implica?",
        ["Well, pay me 100 Gold and I'll see if any rusty swords that you've found are actually worth anything. Some of them might be worth some money! If it's an antique item though, I reserve the right to purchase it immediately for adding to my own personal collection. I'll give you fair price for it."] = "Bueno, págame 100 de oro y veré si alguna espada oxidada que hayas encontrado realmente vale algo. ¡Algunos de ellos podrían valer algo de dinero! Sin embargo, si se trata de un artículo antiguo, me reservo el derecho de comprarlo inmediatamente para agregarlo a mi colección personal. Te daré un precio justo por ello.",
        ["What do I get from this?"] = "¿Qué obtengo de esto?",
        ["If I can reclaim the sword with my own specialist skills, I'll return it to you in peak condition. If it's an antique, I'll just give you what I think it's worth and I generally pay quite well. However, if it's just a piece of junk, I'll simply give you the bad news and get rid of the item for you."] = "Si puedo recuperar la espada con mis propias habilidades especializadas, te la devolveré en óptimas condiciones. Si es una antigüedad, te daré lo que creo que vale y, en general, pago bastante bien. Sin embargo, si es sólo un pedazo de basura, simplemente te daré las malas noticias y me desharé del artículo por ti.",
        ["Ok, I'll give it a go!"] = "Ok, ¡lo intentaré!",
        ["Sorry my friend, but you don't seem to have any swords that need to be identified."] = "Lo siento, amigo mío, pero parece que no tienes ninguna espada que deba identificarse.",
        ["[You hand Tindel 100 coins plus the rusty sword.]"] = "[Le entregas a Tindel 100 coins más la espada oxidada.]",
        ["There you go my friend, it turned out to be a <sword name>."] = "Ahí tienes amigo, resultó ser un <sword name>.",
        ["[Tindel gives you a <sword name>.]"] = "[Tindel te regala un <sword name>.]",
        ["Ok, thanks."] = "Vale, gracias.",
        ["Repairing or recharging degradable items costs money. If you want me to repair all of your items, I will take the correct fee from your inventory or money pouch."] = "Reparar o recargar artículos degradables cuesta dinero. Si desea que repare todos sus artículos, tomaré la tarifa correcta de su inventario o bolsa de dinero.",
        ["Repair or recharge all your items?"] = "¿Reparar o recargar todos tus artículos?",
        ["You do not have any items that can be repaired or recharged."] = "No tienes ningún artículo que pueda repararse o recargarse.",
        ["All done! That cost you <amount> coins."] = "¡Todo listo! Eso te costó <amount> coins.",
        ["All your items have been fixed for <amount> coins."] = "Todos sus elementos han sido reparados para <amount> coins.",
        ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
        ["[You ring for attention.]"] = "[Llamas para llamar la atención.]",
    },
    ["Tinsay"] = {
        ["*(One of the following lines is spoken:)*"] = "*(Se pronuncia una de las siguientes líneas:)*",
        ["Braaar! Jogres!"] = "¡Braaar! ¡Jogres!",
        ["mmm ... Jogre bones ..."] = "mmm… Jogre huesos…",
        ["Leave me alone! Can't you see I'm a mad priest?"] = "¡Déjame en paz! ¿No ves que soy un sacerdote loco?",
        ["Hello, Tinsay."] = "Hola, Tinsay.",
        ["Why hello there! What are you doing back here?"] = "¡Hola! ¿Qué estás haciendo aquí atrás?",
        ["Just passing through."] = "Estoy de paso.",
    },
