        ["What are you?"] = "¿Qué eres?",
        ["What is it?"] = "¿Qué es?",
        ["ARGH!"] = "¡ARGH!",
        ["What?"] = "¿Qué?",
        ["Tiny Zemouregal is staring at you, unblinking.<br>It's more than a bit unnerving."] = "Tiny Zemouregal te está mirando sin parpadear. <br>Es más que un poco desconcertante.",
        ["Why are you looking at me like that?"] = "¿Por qué me miras así?",
        ["Never mind."] = "No importa.",
        ["Select an Option"] = "Selecciona una opción",
        ["No, seriously, what are you?"] = "No, en serio, ¿qué eres?",
        ["Forget I asked."] = "Olvida que pregunté.",
        ["TINY ZEMO!"] = "¡PEQUEÑO ZEMO!",
        ["OR JUST TINY FOR SHORT!"] = "¡O SIMPLEMENTE PEQUEÑO PARA BREVE!",
        ["I gathered that much, but where did you come from and what do you do here?"] = "Ya lo entendí, pero ¿de dónde vienes y qué haces aquí?",
        ["BIG ZEMO MAKE FOR CHORES!"] = "¡GRAN ZEMO HACE PARA LAS TAREAS!",
