        ["You need the following skills to start this quest: 74 Firemaking, 76 Constitution, 64 Agility."] = "Necesitas las siguientes habilidades para comenzar esta misión: 74 Firemaking, 76 Constitution, 64 Agility.",
        ["What are you all doing here?"] = "¿Qué están haciendo todos aquí?",
        ["Top secret, my friend. But perhaps when you're more experienced you could help us."] = "Alto secreto, amigo mío. Pero quizás cuando tengas más experiencia puedas ayudarnos.",
        ["I see."] = "Ya veo.",
        ["Hi, Player!"] = "¡Hola, Player!",
        ["Twig, you're not scared!"] = "¡Twig, no tienes miedo!",
        ["No, the circus is so lively I can't help but forget about my fears."] = "No, el circo es tan animado que no puedo evitar olvidarme de mis miedos.",
        ["Sometimes."] = "A veces.",
    },
    ["Twig"] = {
        ["You need the following skills to start this quest: 74 Firemaking, 76 Constitution, 64 Agility."] = "Necesitas las siguientes habilidades para comenzar esta misión: 74 Firemaking, 76 Constitution, 64 Agility.",
        ["What are you all doing here?"] = "¿Qué están haciendo todos aquí?",
        ["Top secret, my friend. But perhaps when you're more experienced you could help us."] = "Alto secreto, amigo mío. Pero quizás cuando tengas más experiencia puedas ayudarnos.",
        ["I see."] = "Ya veo.",
        ["Hi, Player!"] = "¡Hola, Player!",
        ["Twig, you're not scared!"] = "¡Twig, no tienes miedo!",
        ["No, the circus is so lively I can't help but forget about my fears."] = "No, el circo es tan animado que no puedo evitar olvidarme de mis miedos.",
        ["Sometimes."] = "A veces.",
    },
    ["Tyke"] = {
        ["Hi, human."] = "Hola, humano.",
        ["Hi, ogre."] = "Hola, ogro.",
        ["How are you today, little ogre?"] = "¿Cómo estás hoy, pequeño ogro?",
        ["*Dialogue 1:*"] = "*Diálogo 1:*",
        ["Can I have some shiny pretties, human?"] = "¿Puedo tener algunas bellezas brillantes, humano?",
        ["What makes you think I'd give my shiny pretties to you?"] = "¿Qué te hace pensar que te daría mis bellezas brillantes?",
        ["That skinny lady at de bank say visitors bring lots of shiny pretties with them when they come visit Oo'glog. Me want my share!"] = "Esa señora flaca del banco dice que los visitantes traen consigo muchas bellezas brillantes cuando vienen a visitar Oo'glog. ¡Quiero mi parte!",
        ["Ah, you see, I've given your share to that skinny lady at the bank; you'll have to ask her for it yourself. Make sure you ask really loudly and growl at her every time she uses a word you don't understand, okay?"] = "Ah, verás, le he dado tu parte a esa señora flaca del banco; Tendrás que pedírselo tú mismo. Asegúrate de preguntarle en voz muy alta y gruñirle cada vez que use una palabra que no entiendes, ¿de acuerdo?",
        ["Yay! Thanks human. I'm gonna get my shiny pretties, even if I have to growl all afternoon."] = "¡Sí! Gracias humano. Voy a conseguir mis bellezas brillantes, incluso si tengo que gruñir toda la tarde.",
        ["*Dialogue 2:*"] = "*Diálogo 2:*",
        ["Fine, please and thank you very much, madam sir!"] = "¡Bien, por favor y muchas gracias señora señor!",
        ["You're very...polite."] = "Eres muy... educado.",
        ["Me know! Me practising! Balnea say I can have job in Customer Rations when I grow up if me polite enough."] = "¡Lo sé! ¡Yo practicando! Balnea dice que puedo tener trabajo en Customer Rations cuando sea mayor si soy lo suficientemente educado.",
        ["Don't you mean 'Customer Relations'?"] = "¿No te refieres a 'Relaciones Customer'?",
        ["Blechh! Dat not sound near as tasty as 'Customer Rations'. Me not sure me want de job after all."] = "¡Blechh! Eso no suena tan sabroso como 'Customer Rations'. Después de todo, no estoy seguro de querer el trabajo.",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["Hey, human. What did you bring me?"] = "Hola, humano. ¿Qué me trajiste?",
        ["Hmm, let me think carefully about this. Oh, yes, I remember, now! Absolutely nothing."] = "Hmm, déjame pensar detenidamente en esto. ¡Oh, sí, ahora lo recuerdo! Absolutamente nada.",
        ["Aw, shucks."] = "Ay, caray.",
        ["*Dialogue 4:*"] = "*Diálogo 4:*",
        ["How does it feel to be so puny wee small, human?"] = "¿Cómo se siente ser tan pequeño, humano?",
        ["Oh, I dunno. How does it feel to be so incredibly dense?"] = "Oh, no lo sé. ¿Cómo se siente ser tan increíblemente denso?",
        ["Uhh...what dat s'pposed to mean?"] = "Uhh... ¿qué se supone que significa eso?",
        ["Never mind."] = "No importa.",
        ["*Dialogue 5:*"] = "*Diálogo 5:*",
        ["Me like pie!"] = "¡Me gusta el pastel!",
        ["Doesn't everyone?"] = "¿No es así para todos?",
        ["Pie! Pie! Pie! Pie! Pie!"] = "¡Pastel! ¡Pastel! ¡Pastel! ¡Pastel! ¡Pastel!",
        ["Yes, dear, pie."] = "Sí, querido, pastel.",
        ["*Dialogue 6:*"] = "*Diálogo 6:*",
        ["Me wanna go visit Fycie 'n Bugs!"] = "¡Quiero ir a visitar Fycie y Bugs!",
        ["Yes, they're both delightful individuals."] = "Sí, ambos son personas encantadoras.",
        ["Will you take me to see dem, human?"] = "¿Me llevarás a verlos, humano?",
        ["Didn't your mother ever teach you not to talk to strangers?"] = "¿Tu madre nunca te enseñó a no hablar con extraños?",
        ["*Dialogue 7:*"] = "*Diálogo 7:*",
        ["Me wants CHOMPY for dinner!"] = "¡Quiero CHOMPY para cenar!",
        ["Me hopes you GETS chompy for dinner!"] = "¡Espero que te pongas nervioso para la cena!",
        ["What you talk weird like dat for, human? You sound silly!"] = "¿Por qué hablas así de raro, humano? ¡Suenas tonto!",
        ["*Dialogue 8:*"] = "*Diálogo 8:*",
        ["Not so very good. Me just drop me lunch in de pool."] = "No muy bien. Simplemente déjame el almuerzo en la piscina.",
        ["Ew...I think I can see it floating over there."] = "Ew... Creo que puedo verlo flotando por allí.",
        ["Oh, thank you human! I have it as a snack next time I go for swim!"] = "¡Oh, gracias humano! ¡Lo tomaré como refrigerio la próxima vez que vaya a nadar!",
        ["*Dialogue 9:*"] = "*Diálogo 9:*",
        ["You very cute, little creature. Me want to have a human as a pet. What you doing, human? You busy? You want be my little pet human creature?"] = "Eres una pequeña criatura muy linda. Quiero tener un humano como mascota. ¿Qué estás haciendo, humano? ¿Estas ocupado? ¿Quieres ser mi pequeña criatura humana mascota?",
        ["Uh...I think I'm busy at the moment."] = "Uh... Creo que estoy ocupado en este momento.",
        ["Pwetty please?"] = "¿Pequeño, por favor?",
        ["Look, sorry to disappoint, but this isn't going to happen."] = "Mira, lamento decepcionarte, pero esto no va a suceder.",
        ["Aw, you no fun, human."] = "Ay, no eres divertido, humano.",
        ["Select an Option"] = "Selecciona una opción",
        ["How are you today?"] = "¿Cómo estás hoy?",
        ["Can you tell me about this stinky, green spring?"] = "¿Puedes hablarme de esta primavera verde y apestosa?",
        ["Can you tell me about this stinky, green pool?"] = "¿Puedes hablarme de esta piscina verde y apestosa?",
        ["What you mean, stinky? It smell delightful!"] = "¿Qué quieres decir con apestoso? ¡Huele delicioso!",
        ["Um, right. Semantics aside, can you tell me anything about it?"] = "Mmm, claro. Dejando a un lado la semántica, ¿puedes decirme algo al respecto?",
        ["Oh, yeah, it very nice place to have bath. You smell pretty and mum say it refresh the soul."] = "Oh, sí, es un lugar muy agradable para bañarse. Hueles bonito y mamá dice que refresca el alma.",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["Well, it a bit confusing, but mum say that dat taking bath here is as good as goin’ to altar."] = "Bueno, es un poco confuso, pero mamá dice que bañarse aquí es tan bueno como ir al altar.",
    },
    ["Tyr"] = {
        ["Hi, how can I help you?"] = "Hola, ¿en qué puedo ayudarte?",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm a Void Knight, one of the order of Guthix. We are warriors of balance who do Guthix's work here in Gielinor."] = "Soy un Void Knight, uno de la orden de Guthix. Somos guerreros del equilibrio que hacemos el trabajo de Guthix aquí en Gielinor.",
        ["**Select an option**"] = "**Seleccione una opción**",
        ["Wow, can I join?"] = "Vaya, ¿puedo unirme?",
        ["Entry is strictly invite only, however we do need help continuing Guthix's work."] = "La entrada es estrictamente solo por invitación, sin embargo, necesitamos ayuda para continuar con el trabajo de Guthix.",
        ["What kind of work?"] = "¿Qué tipo de trabajo?",
        ["*(Same as below.)*"] = "*(Igual que a continuación.)*",
        ["Good luck with that."] = "Buena suerte con eso.",
        ["Ah well you see we try to keep Gielinor as Guthix intended, it's very challenging. Actually we've been having some problems recently, maybe you could help us?"] = "Ah, bueno, verás, intentamos mantener Gielinor como pretendía Guthix, es un gran desafío. De hecho, hemos tenido algunos problemas recientemente, ¿quizás podrías ayudarnos?",
        ["What's the problem?"] = "¿Cuál es el problema?",
        ["Well the order has become quite diminished over the years, it's a very long process to learn the skills of a Void Knight. Recently there have been beaches into our realm from somewhere else, and strange creatures have been pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "Bueno, el orden ha disminuido bastante con los años, es un proceso muy largo aprender las habilidades de un Void Knight. Recientemente, han llegado playas a nuestro reino desde algún otro lugar, y han estado atravesando extrañas criaturas. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
        ["How can I help?"] = "¿Cómo puedo ayudar?",
        ["We send launchers from our outpost to the nearby islands. If you go and wait in the lander there that'd really help."] = "Enviamos lanzadores desde nuestro puesto de avanzada a las islas cercanas. Si vas y esperas en el módulo de aterrizaje, eso sería de gran ayuda.",
        ["Sorry, but I can't."] = "Lo siento, pero no puedo.",
        ["What's 'Gielinor'?"] = "¿Qué es 'Gielinor'?",
        ["*(Same as below)*"] = "*(Igual que a continuación)*",
        ["I'd rather not, sorry."] = "Preferiría no hacerlo, lo siento.",
        ["It is the name that Guthix gave to this world, so we honour him with its use."] = "Es el nombre que Guthix le dio a este mundo, por eso lo honramos con su uso.",
        ["Uh huh, sure."] = "Ajá, claro.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is our outpost. From here we send launches out to the nearby islands to beat back the invaders."] = "Este es nuestro puesto de avanzada. Desde aquí enviamos lanchas a las islas cercanas para hacer retroceder a los invasores.",
        ["What invaders?"] = "¿Qué invasores?",
        ["*(Same response as 'What's the problem' above.)*"] = "*(La misma respuesta que \"¿Cuál es el problema?\" arriba.)*",
        ["*(Same as above.)*"] = "*(Igual que el anterior.)*",
        ["I'm fine thanks."] = "Estoy bien, gracias.",
        ["Commodore Tyr."] = "Comodoro Tyr.",
        ["Player, it's good to see you. What can I do for you?"] = "Player, es un gusto verte. ¿Qué puedo hacer por ti?",
        ["**WHAT DO YOU WANT TO ASK?**"] = "**¿QUÉ QUIERES PREGUNTAR?**",
        ["How are things at the outpost?"] = "¿Cómo van las cosas en el puesto de avanzada?",
        ["We mourn the loss of our friends."] = "Lamentamos la pérdida de nuestros amigos.",
        ["But we are Void Knights and we balance our mourning with the destruction of portals. We'll continue fighting for as long as balance requires us to."] = "Pero somos Caballeros del Vacío y equilibramos nuestro duelo con la destrucción de portales. Seguiremos luchando mientras el equilibrio nos lo requiera.",
        ["*If Jessika died during The Void Stares Back:*"] = "*Si Jessika murió durante The Void Stares Back:*",
        ["Where's Korasi?"] = "¿Dónde está Korasi?",
        ["*If Korasi died during The Void Stares Back:*"] = "*Si Korasi murió durante The Void Stares Back:*",
        ["Where's Jessika?"] = "¿Dónde está Jessika?",
        ["She's probably on the battlefield. She's really thrown herself into it since the defeat of the Pest Queen. I think she finds relief there."] = "Probablemente esté en el campo de batalla. Ella realmente se ha volcado en ello desde la derrota de la Reina Pest. Creo que encuentra alivio allí.",
        ["Oh. I'd kind of hoped to speak to her."] = "Oh. En cierto modo esperaba hablar con ella.",
        ["Give her time, Player. Korasi and Jessika had become close friends during all of this. It was a hard battle for all of us, but, I think, hardest for her."] = "Dale tiempo, Player. Korasi y Jessika se habían hecho amigos cercanos durante todo esto. Fue una batalla dura para todos nosotros, pero creo que la más dura para ella.",
        ["I'm still a little bewildered by what happened."] = "Todavía estoy un poco desconcertado por lo que pasó.",
        ["It was an... odd plot that Grayzag hatched, for sure."] = "Fue un... complot extraño el que Grayzag tramó, sin duda.",
        ["Did he really think he could control the Pest Queen?"] = "¿Realmente pensó que podía controlar a la Reina Pest?",
        ["Grayzag was not mentally sound. There's no telling what he believed. He was a fool, and we paid a heavy price for his foolishness."] = "Grayzag no estaba mentalmente sano. No se sabe en qué creía. Era un tonto y pagamos un alto precio por su tontería.",
        ["And what about the Valluta? I thought you said it was a weapon."] = "¿Y qué pasa con el Valluta? Pensé que dijiste que era un arma.",
        ["Yes, that was a misintepretation of the text. Our people craved a weapon that would end our struggles against the pests, but, having spoken to the Valluta, I understand the truth:"] = "Sí, esa fue una mala interpretación del texto. Nuestro pueblo anhelaba un arma que pusiera fin a nuestra lucha contra las plagas, pero, habiendo hablado con Valluta, entiendo la verdad:",
        ["All creatures of Guthix and those who serve him in defending this world from outside imbalance are the Valluta. We are instruments of balance."] = "Todas las criaturas de Guthix y aquellos que le sirven para defender este mundo del desequilibrio exterior son los Valluta. Somos instrumentos de equilibrio.",
        ["So, was the big turtle the Valluta or a weapon?"] = "Entonces, ¿la tortuga grande era Valluta o un arma?",
        ["She is not a weapon. She is the Valluta, but so am I and so are you."] = "Ella no es un arma. Ella es la Valluta, pero yo también y tú también.",
        ["Guthix granted her the power to heal rifts between our world and the Void."] = "Guthix le otorgó el poder de curar las divisiones entre nuestro mundo y el Vacío.",
        ["Grayzag's meddling made too many portals for her to heal at once, distracting her, and then the goo drained her of her power."] = "La intromisión de Grayzag creó demasiados portales para que ella sanara a la vez, lo que la distrajo, y luego la sustancia viscosa le quitó su poder.",
        ["When the boxes of goo exploded, she regained her power and will now make sure the main portal remains closed."] = "Cuando las cajas de sustancia viscosa explotaron, ella recuperó su poder y ahora se asegurará de que el portal principal permanezca cerrado.",
        ["My people must continue to contain the pests using these portals, however, lest the Valluta spread her power too thin again."] = "Sin embargo, mi gente debe continuar conteniendo las plagas usando estos portales, no sea que Valluta vuelva a extender demasiado su poder.",
        ["I've lost Korasi's sword."] = "He perdido la espada de Korasi.",
        ["Really? Well, let's take a look."] = "¿En serio? Bueno, echemos un vistazo.",
        ["*If you have Korasi's sword:*"] = "*Si tienes la espada de Korasi:*",
        ["It seems you still have the sword, Player."] = "Parece que todavía tienes la espada, Player.",
        ["*If you do not have Korasi's sword:*"] = "*Si no tienes la espada de Korasi:*",
        ["Ah, yes, it's returned home. I can give it to you again, but I'll have to ask you for 500,000 coins to honour those who died in the Pest Queen conflict."] = "Ah, sí, ha regresado a casa. Puedo dártelo de nuevo, pero tendré que pedirte 500.000 coins para honrar a los que murieron en el conflicto de Pest Queen.",
        ["**WILL YOU PAY 500,000 COINS TO RETRIEVE THE SWORD?**"] = "**¿PAGARÁS 500.000 COINS PARA RECUPERAR LA ESPADA?**",
        ["Yes."] = "Sí.",
        ["500,000 coins have been removed from your money pouch."] = "Se han eliminado 500.000 coins de su bolsa de dinero.",
        ["Korasi's sword is yours once again. Look after it."] = "La espada de Korasi es tuya una vez más. Cuídalo.",
        ["*(Dialogue ends)*"] = "*(Termina el diálogo)*",
        ["I'd like to trade my regular void knight armour for its elite version."] = "Me gustaría cambiar mi armadura void knight habitual por su versión élite.",
        ["I'd like to trade my regular Void Knight armour for its elite version."] = "Me gustaría cambiar mi armadura Void Knight habitual por su versión élite.",
        ["I can do this for you for a hundred Commendations. Are you looking to trade the top, the legs or both?"] = "Puedo hacer esto por ti por cien elogios. ¿Estás buscando intercambiar la parte superior, las piernas o ambas?",
        ["**WHICH PIECE OF ARMOUR DO YOU REQUIRE?**"] = "**¿QUÉ PIEZA DE ARMADURA NECESITAS?**",
        ["The torso."] = "El torso.",
        ["*If you lack the torso piece of the regular armour:*"] = "*Si te falta la pieza del torso de la armadura normal:*",
        ["You will need your regular armour piece and a hundred Commendations to upgrade your top, I fear."] = "Me temo que necesitarás tu pieza de armadura habitual y cien elogios para mejorar tu camiseta.",
        ["*If you have the torso piece of the regular armour:*"] = "*Si tienes la pieza del torso de la armadura normal:*",
        ["The legs."] = "Las piernas.",
        ["*If you lack the legs piece of the regular armour:*"] = "*Si te falta la pieza de piernas de la armadura regular:*",
        ["You will need your regular armour piece and a hundred Commendations to upgrade your robes, I fear."] = "Me temo que necesitarás tu pieza de armadura habitual y cien elogios para mejorar tu túnica.",
        ["*If you have the legs piece of the regular armour:*"] = "*Si tienes la pieza de piernas de la armadura regular:*",
        ["Your robes are improved. Wear them proudly."] = "Tus túnicas han mejorado. Llévalos con orgullo.",
        ["Both."] = "Ambos.",
        ["*If you lack both pieces of the regular armour:*"] = "*Si te faltan ambas piezas de la armadura normal:*",
        ["*If you have both pieces of the regular armour:*"] = "*Si tienes ambas piezas de la armadura normal:*",
        ["Can I trade in superior Void Knight armour?"] = "¿Puedo intercambiar una armadura Void Knight superior?",
        ["Yes, for the same price. Are you looking to trade the superior top, the legs, or both?"] = "Sí, por el mismo precio. ¿Está buscando intercambiar la parte superior superior, las piernas o ambas?",
        ["*If you lack the torso piece of the superior armour:*"] = "*Si te falta la pieza del torso de la armadura superior:*",
        ["You will need your superior armour piece and a hundred Commendations to upgrade your top, I fear."] = "Me temo que necesitarás tu pieza de armadura superior y cien elogios para mejorar tu parte superior.",
        ["*If you have the torso piece of the superior armour:*"] = "*Si tienes la pieza del torso de la armadura superior:*",
        ["*If you lack the legs piece of the superior armour:*"] = "*Si te falta la pieza de piernas de la armadura superior:*",
        ["You will need your superior armour piece and a hundred Commendations to upgrade your robes, I fear."] = "Me temo que necesitarás tu pieza de armadura superior y cien elogios para mejorar tu túnica.",
        ["*If you have the legs piece of the superior armour:*"] = "*Si tienes la pieza de piernas de la armadura superior:*",
        ["*If you lack both pieces of superior armour:*"] = "*Si te faltan ambas piezas de armadura superior:*",
        ["*If you lack the torso piece of superior armour:*"] = "*Si te falta la pieza del torso de armadura superior:*",
        ["*If you lack the leg piece of superior armour:*"] = "*Si te falta la pieza de pierna de la armadura superior:*",
        ["*If you have both pieces of superior armour and a hundred commendations:*"] = "*Si tienes ambas piezas de armadura superior y cien elogios:*",
        ["I'd like to change the colour of my armour."] = "Me gustaría cambiar el color de mi armadura.",
        ["You feel your morality was not correctly reflected? Very well. I can alter your armour, but I must ask for a donation to our cause to ensure this is not merely a passing fancy."] = "¿Sientes que tu moralidad no se reflejó correctamente? Muy bien. Puedo alterar tu armadura, pero debo pedir una donación a nuestra causa para asegurar que esto no sea simplemente un capricho pasajero.",
        ["Changing your armour's colour will cost 100,000 coins."] = "Cambiar el color de tu armadura te costará 100.000 coins.",
        ["What colour do you feel best reflects your inner self?"] = "¿Qué color crees que refleja mejor tu yo interior?",
        ["**CHOOSE YOUR COLOUR.**"] = "**ELIGE TU COLOR.**",
        ["White (Guardian)."] = "Blanco (Guardián).",
        ["100,000 coins have been removed from your money pouch."] = "Se han eliminado 100.000 coins de su bolsa de dinero.",
        ["Your armour is recoloured. Wear it in balance and in Guthix's name."] = "Tu armadura ha sido recoloreada. Llévalo en equilibrio y en nombre de Guthix.",
        ["Grey (Justicar)."] = "Gris (Justicar).",
        ["Black (Executioner)."] = "Negro (verdugo).",
    },
    ["Tyton"] = {
        ["Hello, Player!"] = "¡Hola, Player!",
        ["Hi Tyton."] = "Hola Tyton.",
        ["Is there anything I can do for you?"] = "¿Hay algo que pueda hacer por usted?",
        ["Select an option"] = "Selecciona una opción",
        ["Ask about the owls."] = "Pregunta por los búhos.",
        ["What's the history between the owls and the City of Um?"] = "¿Cuál es la historia entre los búhos y City of Um?",
        ["You'll have to be more specific than that."] = "Tendrás que ser más específico que eso.",
        ["Well, did Death create you? How long have you been around?"] = "Bueno, ¿te creó la Muerte? ¿Cuánto tiempo llevas por aquí?",
        ["As far as I can remember, my siblings and I have been around since the before the inception of Um. Thus I would presume we were not creations of Harold."] = "Hasta donde puedo recordar, mis hermanos y yo hemos existido desde antes de la creación de Um. Por tanto, supongo que no éramos creaciones de Harold.",
        ["How were you created, then? What is your purpose?"] = "¿Cómo fuiste creado entonces? ¿Cuál es tu propósito?",
        ["That is a much larger existential question that I am unable to answer."] = "Ésa es una pregunta existencial mucho más amplia que no puedo responder.",
        ["My personal theory is that we were appointed here upon the creation of life, to oversee the many events of the Underworld. But  knows."] = "Mi teoría personal es que fuimos designados aquí tras la creación de la vida, para supervisar los numerosos eventos del inframundo. Pero lo sabe.",
        ["That's understandable. Do you ever get bored of the Underworld?"] = "Eso es comprensible. ¿Alguna vez te aburres del inframundo?",
        ["Speaking for myself, no. The Underworld is vast, with a never ending flow of new life passing through."] = "Hablando por mí, no. El inframundo es vasto, con un flujo interminable de nueva vida que lo atraviesa.",
        ["It's definitely not the worst place to be stuck in for eternity, I suppose."] = "Supongo que definitivamente no es el peor lugar para quedarse atrapado por la eternidad.",
        ["Talk about Deryn."] = "Habla de Deryn.",
        ["What do you think of Deryn?"] = "¿Qué opinas de Deryn?",
        ["Hmm... Yes, Deryn is a rather kind soul to spend her time in Um looking after my siblings and I."] = "Hmm... Sí, Deryn es un alma bastante amable que pasa su tiempo en Um cuidando a mis hermanos y a mí.",
        ["Before her, we were left to fend for ourselves. Which wasn't an awful way of living by any means - there's food and water aplenty in the Underworld."] = "Antes de ella, teníamos que valernos por nosotros mismos. Lo cual no era una forma terrible de vivir de ninguna manera: hay comida y agua en abundancia en el Inframundo.",
        ["I do enjoy feeling pampered, though - gourmet food with a fresh bath, right on my doorstep."] = "Aunque disfruto sentirme mimado: comida gourmet con un baño fresco, justo en la puerta de mi casa.",
        ["Nevermind."] = "No importa.",
        ["Farewell."] = "Adiós.",
    },
    ["TzHaar-Ga'al-Knot"] = {
        ["What's a nice Ga'al like you doing in a place like this?"] = "¿Qué hace un Ga'al tan agradable como tú en un lugar como este?",
        ["Is that what you humans call a joke?"] = "¿Es eso lo que los humanos llaman una broma?",
        ["Perhaps. Or an attempt at one."] = "Quizás. O un intento de hacerlo.",
        ["How did you end up here?"] = "¿Cómo terminaste aquí?",
        ["You were easier to find than I expected."] = "Fuiste más fácil de encontrar de lo que esperaba.",
        ["TzHaar-Ga'al-Knot hears that a lot."] = "TzHaar-Ga'al-Knot escucha eso mucho.",
        ["How did you end up here? <div id=\"How did you end up here\"></div>"] = "¿Cómo terminaste aquí? <div id=\"How did you end up here\"></div>",
        ["It was The Harbinger. They see no value in Ga'al crew. Left TzHaar-Ga'al-Knot stranded. Scuttled my ship."] = "Era El Heraldo. No ven ningún valor en el equipo de Ga'al. Dejó TzHaar-Ga'al-Knot varado. Hundió mi barco.",
        ["How did you even get here?"] = "¿Cómo llegaste hasta aquí?",
        ["Ga'al leave volcano. Seek adventure on high seas. Ga'al charter ship from Karamja. TzHaar-Ga'al-Knot new to sailing, but Ga'al learn fast. Ga'al learn to hide from ship with black sails."] = "Ga'al abandona el volcán. Busca aventuras en alta mar. Barco de alquiler Ga'al de Karamja. TzHaar-Ga'al-Knot es nuevo en la navegación, pero Ga'al aprende rápido. Ga'al aprende a esconderte de un barco con velas negras.",
        ["Farewell."] = "Adiós.",
        ["*(dialogue terminates)*"] = "*(termina el diálogo)*",
        ["*First time*"] = "*Primera vez*",
        ["TzHaar-Ga'al-Knot gives you a taijitu in thanks for the rescue."] = "TzHaar-Ga'al-Knot te regala un taijitu en agradecimiento por el rescate.",
    },
    ["TzHaar-Hur-Lek"] = {
        ["Ah, it is the JalYt that is now TzHaar. How can I help you, [TzHaar caste]-Player?"] = "Ah, es JalYt el que ahora es TzHaar. ¿En qué puedo ayudarte, [TzHaar caste]-Player?",
        ["Select an Option"] = "Selecciona una opción",
        ["What do you have to trade?"] = "¿Qué tienes para negociar?",
        ["What did you call me?"] = "¿Cómo me llamaste?",
        ["Are you not [TzHaar caste]?"] = "¿No eres [TzHaar caste]?",
        ["Why do you call me '[TzHaar caste]'?"] = "¿Por qué me llamas '[TzHaar caste]'?",
        ["That what you are... you user of mystic powers, no?"] = "Eso es lo que eres... usuario de poderes místicos, ¿no?",
        ["And you are JalYt no longer. You are TzHaar now."] = "Y ya no eres JalYt. Ahora eres TzHaar.",
        ["Well, yes, I suppose I am..."] = "Bueno, sí, supongo que lo soy...",
        ["Then you [TzHaar caste]!"] = "¡Entonces tú [TzHaar caste]!",
        ["What are you then?"] = "¿Qué eres entonces?",
        ["I am TzHaar-Hur, one of the crafters for this city. We craft tools and sculptures, and carve homes for the TzHaar."] = "Soy TzHaar-Hur, uno de los artesanos de esta ciudad. Fabricamos herramientas y esculturas, y tallamos casas para los TzHaar.",
        ["There are also the wise TzHaar-Mej who guide us, the mighty TzHaar-Kt who guard us, and the swift TzHaar-Xil who hunt for our food."] = "También están los sabios TzHaar-Mej que nos guían, los poderosos TzHaar-Kt que nos protegen y los veloces TzHaar-Xil que cazan nuestra comida.",
        ["Thanks for explaining it."] = "Gracias por explicarlo.",
        ["Yes, I certainly am."] = "Sí, ciertamente lo soy.",
        ["Then it is an honour to speak with you, [TzHaar caste]-Player. You great and powerful TzHaar, and defender of our city."] = "Entonces es un honor hablar contigo, [TzHaar caste]-Player. Tú, gran y poderoso TzHaar, y defensor de nuestra ciudad.",
        ["You must have me confused with another TzHaar."] = "Debes haberme confundido con otro TzHaar.",
        ["I heard you are modest, [TzHaar caste]-Player. No need. Revel in our praise. You deserve all honour."] = "He oído que eres modesto, [TzHaar caste]-Player. No hay necesidad. Deléitate con nuestra alabanza. Mereces todo honor.",
        ["No, I'm fine. Thanks."] = "No, estoy bien. Gracias.",
    },
    ["TzHaar-Hur-Roh"] = {
        ["*When speaking to TzHaar-Hur-Roh at the TzHaar city market plaza.*"] = "*Al hablar con TzHaar-Hur-Roh en la plaza del mercado de la ciudad de TzHaar.*",
        ["[TzHaar caste], it is an honour. How can I help you, esteemed [TzHaar caste]?"] = "[TzHaar caste], es un honor. ¿En qué puedo ayudarle, estimado [TzHaar caste]?",
        ["Select an option"] = "Seleccione una opción",
        ["What do you have to trade?"] = "¿Qué tienes para negociar?",
